/** Linha que vale a pena avaliar (não vazia, não cabeçalho/total, não taxa). */
private static boolean isCandidate(String line) {
    if (line.isEmpty()) {
        return false;
    }
    // SKIP_SUBSTR filtra texto legal/cabeçalhos, mas nunca pode vetar uma linha
    // que começa com data: "Cred/Cob Anuidade 8/12" contém "de 8" (e "9/12"
    // conteria "de 9") e era descartada, estourando o gate da fatura de agosto.
    if (isSkip(line) && !DATE_START.matcher(line).find()) {
        return false;
    }
    return !(line.contains("CET") || line.contains(" a.a") || line.contains(" a.m"));
}

