// Linha de início SEM valor: o PDFBox quebrou a transação (internacional/
// parcelada) em 2+ linhas. Varre as continuações (que não são início de
// transação) até achar a que carrega o valor — descrição longa empurra o
// "R$" para 2 linhas à frente (ex.: "Anthropic Claude Sub San Fran-" /
// "cisco BRL 1.077,66 = US$" / "0,00 R$ 0,00 R$ 1.077,66").
int scan = i + 1;
for (int hops = 0; hops < 3; hops++) {
    int next = nextMeaningfulLine(lines, scan);
    if (next == -1) {
        break;
    }
    String continuation = lines[next].strip();
    if (isTransactionStart(continuation)) {
        break;
    }
    List<String> continuationValues = findValues(continuation);
    if (!continuationValues.isEmpty()) {
        BigDecimal amount = toAmount(continuationValues.get(continuationValues.size() - 1));
        rows.add(new ParsedRow(pageNumber, line, amount, ""));
        for (int k = i + 1; k <= next; k++) {
            consumed[k] = true;
        }
        break;
    }
    scan = next + 1;
}

