                         CategoryRepository categories) {
        this.members = members;
        this.transactions = transactions;
        this.statements = statements;
        this.recurrences = recurrences;
        this.plans = plans;
        this.categories = categories;
    }

    public List<MemberView> list() {
        return members.findAll().stream()
                .sorted(Comparator.comparing(HouseholdMember::getId))
                .map(MemberService::toView)
                .toList();
    }

    @Transactional
    public MemberView create(String name, String cardLast4) {
        HouseholdMember member = new HouseholdMember();
        member.setName(name.strip());
        member.setCardLast4(normalizeCard(cardLast4));
        return toView(members.save(member));
    }

    @Transactional
    public MemberView update(Long id, String name, String cardLast4) {
        HouseholdMember member = members.findById(id)
                .orElseThrow(() -> new IllegalArgumentException("Membro " + id + " não encontrado."));
        if (name != null && !name.isBlank()) {
            member.setName(name.strip());
        }
        member.setCardLast4(normalizeCard(cardLast4));
        return toView(members.save(member));
    }

    /** Atribui (ou desatribui, com memberId null) um lançamento a um membro. */
    @Transactional
    public void attributeTransaction(Long transactionId, Long memberId) {
        Transaction tx = transactions.findById(transactionId)
                .orElseThrow(() -> new IllegalArgumentException("Transação " + transactionId + " não encontrada."));
        tx.setMemberId(requireMember(memberId));
        transactions.save(tx);
    }

    /** Atribui o plano inteiro: todas as parcelas (atuais e futuras) viram do membro. */
    @Transactional
    public void attributePlan(Long planId, Long memberId) {
        InstallmentPlan plan = plans.findById(planId)
                .orElseThrow(() -> new IllegalArgumentException("Plano " + planId + " não encontrado."));
        Long resolved = requireMember(memberId);
        plan.setMemberId(resolved);
        plans.save(plan);
        List<Transaction> txs = transactions.findByInstallmentPlanId(planId);
        for (Transaction tx : txs) {
            tx.setMemberId(resolved);
        }
        transactions.saveAll(txs);
    }

    @Transactional
    public void attributeRecurrence(Long recurrenceId, Long memberId) {
        Recurrence recurrence = recurrences.findById(recurrenceId)
                .orElseThrow(() -> new IllegalArgumentException("Recorrência " + recurrenceId + " não encontrada."));
        recurrence.setMemberId(requireMember(memberId));
        recurrences.save(recurrence);
    }

    /** Transações do mês de fatura, para a tela de atribuição (1 clique por linha). */
    public List<TransactionListItem> monthTransactions(YearMonth month) {
        Map<Long, String> categoryNames = new HashMap<>();
        for (Category c : categories.findAll()) {
            categoryNames.put(c.getId(), c.getName());
        }
        List<TransactionListItem> items = new ArrayList<>();
        for (Statement statement : statementsOf(month)) {
            for (Transaction tx : transactions.findByStatementId(statement.getId())) {
                items.add(new TransactionListItem(
                        tx.getId(),
                        tx.getPostedAt(),
                        SicrediDescription.resolve(tx.getDescriptionRaw(), tx.getMerchant()),
                        tx.getAmount(),
                        categoryNames.get(tx.getCategoryId()),
                        tx.getMemberId(),
                        tx.getCardLast4(),
                        tx.getInstallmentPlanId(),
                        tx.getInstallmentNo(),
                        tx.getInstallmentTotal(),
                        tx.isInternational()));
            }
        }
        items.sort(Comparator.comparing(TransactionListItem::postedAt).reversed()
                .thenComparing(TransactionListItem::id, Comparator.reverseOrder()));
        return items;
    }

    /** Resumo por pessoa: gasto no mês, assinaturas/mês e parcelas a vencer. */
    public CoupleSummaryView summary(YearMonth month) {
        List<Transaction> monthTxs = new ArrayList<>();
        for (Statement statement : statementsOf(month)) {
            monthTxs.addAll(transactions.findByStatementId(statement.getId()));
        }
        List<Recurrence> confirmed = recurrences
                .findByKindAndStatusAndActiveTrue(RecurrenceKind.SUBSCRIPTION, RecurrenceStatus.CONFIRMED);
        List<InstallmentPlan> openPlans = plans.findByRemainingInstallmentsGreaterThan(0);

        List<MemberSummaryView> views = new ArrayList<>();
        for (HouseholdMember member : members.findAll().stream()
                .sorted(Comparator.comparing(HouseholdMember::getId)).toList()) {
            views.add(bucket(member.getId(), member.getName(), monthTxs, confirmed, openPlans));
        }
        MemberSummaryView shared = bucket(null, "Casa (em comum)", monthTxs, confirmed, openPlans);
        return new CoupleSummaryView(month.atDay(1), views, shared);
    }

    private MemberSummaryView bucket(Long memberId, String name, List<Transaction> monthTxs,
                                     List<Recurrence> confirmed, List<InstallmentPlan> openPlans) {
        BigDecimal spent = BigDecimal.ZERO;
        long count = 0;
        for (Transaction tx : monthTxs) {
            if (tx.getAmount().signum() > 0 && Objects.equals(tx.getMemberId(), memberId)) {
                spent = spent.add(tx.getAmount());
                count++;
            }
        }
        BigDecimal subscriptions = BigDecimal.ZERO;
        for (Recurrence r : confirmed) {
            if (Objects.equals(r.getMemberId(), memberId) && r.getTypicalAmount() != null) {
                subscriptions = subscriptions.add(r.getTypicalAmount());
            }
        }
        BigDecimal upcoming = BigDecimal.ZERO;
        for (InstallmentPlan plan : openPlans) {
            if (Objects.equals(plan.getMemberId(), memberId) && plan.getInstallmentAmount() != null) {
                upcoming = upcoming.add(
                        plan.getInstallmentAmount().multiply(BigDecimal.valueOf(plan.getRemainingInstallments())));
            }
        }
        return new MemberSummaryView(memberId, name, spent, count, subscriptions, upcoming);
    }

    private List<Statement> statementsOf(YearMonth month) {
        return statements.findAll().stream()
                .filter(s -> YearMonth.from(s.getReferenceMonth()).equals(month))
                .toList();
    }

    private Long requireMember(Long memberId) {
        if (memberId == null) {
            return null;
        }
        members.findById(memberId)
                .orElseThrow(() -> new IllegalArgumentException("Membro " + memberId + " não encontrado."));
        return memberId;
    }

    private static String normalizeCard(String cardLast4) {
        if (cardLast4 == null || cardLast4.isBlank()) {
            return null;
        }
        String digits = cardLast4.replaceAll("\\D", "");
        if (digits.length() != 4) {
            throw new IllegalArgumentException("cardLast4 deve ter 4 dígitos.");
        }
        return digits;
    }

    private static MemberView toView(HouseholdMember member) {
        return new MemberView(member.getId(), member.getName(), member.getCardLast4());
    }
}

