/** Modo casal: membros do domicílio + visão por pessoa + atribuição em lote. */
@RestController
@RequestMapping("/api")
public class MemberController {

    private final MemberService service;

    public MemberController(MemberService service) {
        this.service = service;
    }

    @GetMapping("/members")
    public List<MemberView> list() {
        return service.list();
    }

    @PostMapping("/members")
    public MemberView create(@Valid @RequestBody MemberRequest request) {
        return service.create(request.name(), request.cardLast4());
    }

    @PutMapping("/members/{id}")
    public MemberView update(@PathVariable Long id, @Valid @RequestBody MemberRequest request) {
        return service.update(id, request.name(), request.cardLast4());
    }

    /** Resumo do casal no mês de fatura (default: mês mais recente importado). */
    @GetMapping("/couple/summary")
    public CoupleSummaryView summary(@RequestParam String month) {
        return service.summary(parseMonth(month));
    }

    /** Transações do mês para atribuição (quem gastou o quê). */
    @GetMapping("/couple/transactions")
    public List<TransactionListItem> transactions(@RequestParam String month) {
        return service.monthTransactions(parseMonth(month));
    }

    private static YearMonth parseMonth(String month) {
        try {
            return YearMonth.parse(month);
        } catch (Exception e) {
            throw new IllegalArgumentException("month deve estar no formato YYYY-MM.");
        }
    }
}

