private Transaction toTransaction(ParsedRow row, Long accountId, Long statementId,
                                  LocalDate referenceMonth, Map<String, Long> categoryIds,
                                  Map<String, Long> memberByCard) {
    String description = SicrediDescription.resolve(row.raw(), row.merchant());
    String categoryName = categorizer.categorize(description);

    Transaction tx = new Transaction();
    tx.setAccountId(accountId);
    tx.setStatementId(statementId);
    tx.setCategoryId(categoryIds.get(categoryName));
    tx.setPostedAt(resolvePostedDate(row.raw(), referenceMonth));
    tx.setDescriptionRaw(row.raw());
    tx.setMerchant(row.merchant() == null || row.merchant().isBlank() ? null : row.merchant());
    tx.setAmount(row.amount());
    tx.setInternational(row.raw().contains("US$") || row.raw().contains("BRL "));
    tx.setSource(DataSource.PDF_IMPORT);
    // Modo casal: a seção "Cartão ... (final NNNN)" da fatura identifica o dono
    // (cartão adicional cadastrado em household_member.card_last4 => atribuição automática).
    tx.setCardLast4(row.cardLast4());
    if (row.cardLast4() != null) {
        tx.setMemberId(memberByCard.get(row.cardLast4()));
    }
    applyInstallment(tx, description);
    return tx;
}

private Map<String, Long> loadMemberByCard() {
    Map<String, Long> byCard = new HashMap<>();
