  accent: 'border-accent/50 bg-accent/10 text-accent',
  ok: 'border-ok/50 bg-ok/10 text-ok',
  warn: 'border-warn/50 bg-warn/10 text-warn',
  danger: 'border-danger/50 bg-danger/10 text-danger',
  shared: 'border-border bg-panel text-muted',
}

function memberTone(index: number): MemberTone {
  return MEMBER_TONES[index % MEMBER_TONES.length]
}

function CasalRoute() {
  const qc = useQueryClient()

  const membersQuery = useQuery({
    queryKey: ['members'],
    queryFn: () => membersApi.list(),
  })

  const statementsQuery = useQuery({
    queryKey: ['statements'],
    queryFn: () => statements.list(),
  })

  const monthOptions = useMemo(() => {
    const months = (statementsQuery.data ?? [])
      .map((s) => s.referenceMonth.slice(0, 7))
      .sort()
      .reverse()
    return [...new Set(months)]
  }, [statementsQuery.data])

  const [monthChoice, setMonthChoice] = useState<string | null>(null)
  const month = monthChoice ?? monthOptions[0] ?? null

  const memberList = membersQuery.data ?? []

  if (membersQuery.isLoading) {
    return (
      <>
        <PageHeader eyebrow="modo casal" title="Casal" subtitle="Quem gastou o quê" />
        <Skeleton className="mt-6 h-64 w-full" />
      </>
    )
  }

  return (
    <>
      <PageHeader
        eyebrow="modo casal"
        title="Casal"
        subtitle="Cada gasto com dono: você, sua esposa ou a casa"
        actions={
          <div className="flex items-center gap-2">
            {monthOptions.length > 0 && (
              <select
                value={month ?? ''}
                onChange={(e) => setMonthChoice(e.target.value)}
                className="h-9 rounded-md border border-border bg-panel px-3 font-mono text-xs text-text outline-none focus:border-accent"
              >
                {monthOptions.map((m) => (
                  <option key={m} value={m}>
                    {m}
                  </option>
                ))}
              </select>
            )}
            <NewMemberDialog
              onCreated={() => qc.invalidateQueries({ queryKey: ['members'] })}
            />
          </div>
        }
      />

      {memberList.length === 0 ? (
        <div className="mt-6">
          <EmptyState
            icon={HeartHandshake}
            title="Nenhum membro cadastrado"
            description='Crie os dois membros do casal (ex.: "Vinicius" e "Esposa"). Com o cartão adicional dela cadastrado, os gastos se separam sozinhos a cada import.'
            action={
              <NewMemberDialog
                onCreated={() => qc.invalidateQueries({ queryKey: ['members'] })}
              />
            }
          />
        </div>
      ) : month == null ? (
        <div className="mt-6">
          <EmptyState
            icon={HeartHandshake}
            title="Nenhuma fatura importada"
            description="Importe uma fatura para começar a atribuir gastos."
          />
        </div>
      ) : (
        <CoupleBody month={month} members={memberList} />
      )}
    </>
  )
}

function CoupleBody({ month, members }: { month: string; members: HouseholdMember[] }) {
  const summaryQuery = useQuery({
    queryKey: ['couple', 'summary', month],
    queryFn: () => couple.summary(month),
  })

  const summaries: MemberSummary[] = summaryQuery.data
    ? [...summaryQuery.data.members, summaryQuery.data.shared]
    : []

  return (
    <>
      <div className="mt-6 grid grid-cols-1 gap-3 md:grid-cols-3">
        {summaryQuery.isLoading
          ? Array.from({ length: 3 }).map((_, i) => <Skeleton key={i} className="h-40" />)
          : summaries.map((s) => (
              <MemberCard
                key={s.memberId ?? 'shared'}
                summary={s}
                tone={
                  s.memberId == null
                    ? 'shared'
                    : memberTone(members.findIndex((m) => m.id === s.memberId))
                }
              />
            ))}
      </div>

      <Tabs defaultValue="transacoes" className="mt-6">
        <TabsList>
          <TabsTrigger value="transacoes">Lançamentos do mês</TabsTrigger>
          <TabsTrigger value="assinaturas">Assinaturas</TabsTrigger>
        </TabsList>
        <TabsContent value="transacoes">
          <TransactionsPanel month={month} members={members} />
        </TabsContent>
        <TabsContent value="assinaturas">
          <SubscriptionsPanel members={members} />
        </TabsContent>
      </Tabs>
    </>
  )
}

function MemberCard({
  summary,
  tone,
}: {
  summary: MemberSummary
  tone: MemberTone | 'shared'
}) {
  return (
    <div className="rounded-lg border border-border bg-surface p-5">
      <div className="flex items-center justify-between">
        <span
          className={cn(
            'inline-flex items-center gap-1.5 rounded-full border px-2.5 py-0.5 font-mono text-[10px] uppercase tracking-[0.18em]',
            TONE_CHIP[tone],
          )}
        >
          <UserRound className="h-3 w-3" />
          {summary.name}
        </span>
        <span className="font-mono text-[10px] uppercase tracking-[0.18em] text-muted">
          {summary.transactionsInMonth} lançamentos
        </span>
      </div>
      <div className="mt-4 font-mono text-2xl tabular-nums text-text">
        {brlMoney(summary.spentInMonth)}
      </div>
      <div className="mt-1 font-mono text-[10px] uppercase tracking-[0.18em] text-muted">
        gasto no mês
      </div>
      <div className="mt-4 grid grid-cols-2 gap-2 border-t border-border pt-3">
        <div>
          <div className="font-mono text-sm tabular-nums text-text">
            {brlMoney(summary.subscriptionsMonthly)}
          </div>
          <div className="font-mono text-[10px] uppercase tracking-[0.18em] text-muted">
            assinaturas/mês
          </div>
        </div>
        <div className="text-right">
          <div className="font-mono text-sm tabular-nums text-text">
            {brlMoney(summary.upcomingInstallments)}
          </div>
          <div className="font-mono text-[10px] uppercase tracking-[0.18em] text-muted">
            parcelas a vencer
          </div>
        </div>
      </div>
    </div>
  )
}

function MemberChips({
  members,
  value,
  disabled,
  onSelect,
}: {
  members: HouseholdMember[]
  value: number | null
  disabled?: boolean
  onSelect: (memberId: number | null) => void
}) {
  return (
    <div className="flex items-center justify-end gap-1">
      {members.map((m, i) => {
        const active = value === m.id
        return (
          <button
            key={m.id}
            type="button"
            disabled={disabled}
            title={m.name}
            onClick={() => onSelect(active ? null : m.id)}
            className={cn(
              'rounded-full border px-2 py-0.5 font-mono text-[10px] uppercase tracking-[0.12em] transition-colors',
              active ? TONE_CHIP[memberTone(i)] : 'border-border bg-panel text-muted hover:text-text',
            )}
          >
            {m.name.slice(0, 3)}
          </button>
        )
      })}
      <button
        type="button"
        disabled={disabled}
        title="Casa (em comum)"
        onClick={() => onSelect(null)}
        className={cn(
          'rounded-full border px-2 py-0.5 font-mono text-[10px] uppercase tracking-[0.12em] transition-colors',
          value == null ? TONE_CHIP.shared : 'border-transparent text-muted/60 hover:text-text',
        )}
      >
        casa
      </button>
    </div>
  )
}

function TransactionsPanel({ month, members }: { month: string; members: HouseholdMember[] }) {
  const qc = useQueryClient()
  const [onlyUnassigned, setOnlyUnassigned] = useState(false)

  const txQuery = useQuery({
    queryKey: ['couple', 'transactions', month],
    queryFn: () => couple.transactions(month),
  })

  const assign = useMutation({
    mutationFn: ({ id, memberId }: { id: number; memberId: number | null }) =>
      couple.assignTransaction(id, memberId),
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ['couple'] })
    },
    onError: (err: ApiError) =>
      toast.error('Falha ao atribuir', { description: err.message }),
  })

  const all = txQuery.data ?? []
  const expenses = all.filter((t) => t.amount > 0)
  const rows = onlyUnassigned ? expenses.filter((t) => t.memberId == null) : expenses

  if (txQuery.isLoading) {
    return <Skeleton className="h-64 w-full" />
  }

  return (
    <div className="rounded-lg border border-border bg-surface">
      <div className="flex items-center justify-between border-b border-border px-4 py-2">
        <span className="font-mono text-[10px] uppercase tracking-[0.18em] text-muted">
          {rows.length} de {expenses.length} despesas
        </span>
        <label className="flex cursor-pointer items-center gap-2 font-mono text-[10px] uppercase tracking-[0.18em] text-muted">
          <input
            type="checkbox"
            checked={onlyUnassigned}
            onChange={(e) => setOnlyUnassigned(e.target.checked)}
            className="h-3 w-3 accent-amber-500"
          />
          só sem dono
        </label>
      </div>
      <Table>
        <TableHeader>
          <TableRow>
            <TableHead>Data</TableHead>
            <TableHead>Descrição</TableHead>
            <TableHead>Categoria</TableHead>
            <TableHead>Cartão</TableHead>
            <TableHead className="text-right">Valor</TableHead>
            <TableHead className="text-right">Dono</TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {rows.map((tx: CoupleTransaction) => (
            <TableRow key={tx.id}>
              <TableCell className="font-mono text-xs tabular-nums text-muted">
                {tx.postedAt.slice(8, 10)}/{tx.postedAt.slice(5, 7)}
              </TableCell>
              <TableCell className="max-w-[280px] truncate text-sm text-text">
                {tx.description}
                {tx.installmentNo != null && tx.installmentTotal != null && (
                  <span className="ml-2 font-mono text-[10px] text-muted">
                    {String(tx.installmentNo).padStart(2, '0')}/
                    {String(tx.installmentTotal).padStart(2, '0')}
                  </span>
                )}
              </TableCell>
              <TableCell className="text-xs text-muted">{tx.categoryName ?? '—'}</TableCell>
              <TableCell className="font-mono text-xs tabular-nums text-muted">
                {tx.cardLast4 ? `•${tx.cardLast4}` : '—'}
              </TableCell>
              <TableCell className="text-right font-mono text-sm tabular-nums text-text">
                {brlMoney(tx.amount)}
              </TableCell>
              <TableCell>
                <MemberChips
                  members={members}
                  value={tx.memberId}
                  disabled={assign.isPending}
                  onSelect={(memberId) => assign.mutate({ id: tx.id, memberId })}
                />
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </div>
  )
}

function SubscriptionsPanel({ members }: { members: HouseholdMember[] }) {
  const qc = useQueryClient()
  const confirmed = useQuery({
    queryKey: ['recurrences', 'CONFIRMED'],
    queryFn: () => recurrences.list('CONFIRMED'),
  })

  const assign = useMutation({
    mutationFn: ({ id, memberId }: { id: number; memberId: number | null }) =>
      couple.assignRecurrence(id, memberId),
    onSuccess: () => {
      qc.invalidateQueries({ queryKey: ['recurrences'] })
      qc.invalidateQueries({ queryKey: ['couple'] })
    },
    onError: (err: ApiError) =>
      toast.error('Falha ao atribuir', { description: err.message }),
  })

  const items = confirmed.data?.recurrences ?? []

  if (confirmed.isLoading) {
    return <Skeleton className="h-48 w-full" />
  }

  return (
    <div className="rounded-lg border border-border bg-surface">
      <Table>
        <TableHeader>
          <TableRow>
            <TableHead>Assinatura</TableHead>
            <TableHead className="text-right">Valor/mês</TableHead>
            <TableHead className="text-right">Dono</TableHead>
          </TableRow>
        </TableHeader>
        <TableBody>
          {items.map((r) => (
            <TableRow key={r.id}>
              <TableCell className="text-sm text-text">
                {r.displayName}
                {!r.active && (
                  <Pill tone="muted" className="ml-2">
                    inativa
                  </Pill>
                )}
              </TableCell>
              <TableCell className="text-right font-mono text-sm tabular-nums text-text">
                {brlMoney(r.typicalAmount)}
              </TableCell>
              <TableCell>
                <MemberChips
                  members={members}
                  value={r.memberId}
                  disabled={assign.isPending}
                  onSelect={(memberId) => assign.mutate({ id: r.id, memberId })}
                />
              </TableCell>
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </div>
  )
}

function NewMemberDialog({ onCreated }: { onCreated: () => void }) {
  const [open, setOpen] = useState(false)
  const [name, setName] = useState('')
  const [card, setCard] = useState('')

  const create = useMutation({
    mutationFn: () =>
      membersApi.create({ name, cardLast4: card.trim() === '' ? null : card.trim() }),
    onSuccess: (m) => {
      toast.success(`Membro "${m.name}" criado`)
      setName('')
      setCard('')
      setOpen(false)
      onCreated()
    },
    onError: (err: ApiError) =>
      toast.error('Falha ao criar membro', { description: err.message }),
  })

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button>
          <Plus className="h-4 w-4" />
          Novo membro
        </Button>
      </DialogTrigger>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Novo membro do casal</DialogTitle>
          <DialogDescription>
            Se a pessoa tem cartão adicional, informe os 4 últimos dígitos: os
            gastos daquele cartão passam a ser atribuídos a ela automaticamente
            a cada import.
          </DialogDescription>
        </DialogHeader>
        <div className="grid gap-4 py-2">
          <div className="grid gap-2">
            <Label htmlFor="member-name">Nome</Label>
            <Input
              id="member-name"
              value={name}
              onChange={(e) => setName(e.target.value)}
              placeholder="Ex.: Vinicius"
            />
          </div>
          <div className="grid gap-2">
            <Label htmlFor="member-card">Cartão (4 últimos dígitos, opcional)</Label>
            <Input
              id="member-card"
              value={card}
              onChange={(e) => setCard(e.target.value)}
              placeholder="Ex.: 8419"
              maxLength={4}
              inputMode="numeric"
            />
          </div>
        </div>
        <DialogFooter>
          <Button
            onClick={() => create.mutate()}
            disabled={create.isPending || name.trim() === ''}
          >
            {create.isPending ? 'Criando…' : 'Criar'}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

