package com.vini.financemonitor.ai;

import com.anthropic.client.AnthropicClient;
import com.anthropic.client.okhttp.AnthropicOkHttpClient;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

/**
 * Acesso ao Claude (API Anthropic). Habilitado apenas quando ANTHROPIC_API_KEY
 * está presente no ambiente — sem chave, o app funciona normalmente e as
 * features de IA respondem "não configurado".
 */
@Component
public class AiClient {

    private final String apiKey;
    private final String model;
    private volatile AnthropicClient client;

    public AiClient(@Value("${ANTHROPIC_API_KEY:}") String apiKey,
                    @Value("${app.ai.model}") String model) {
        this.apiKey = apiKey == null ? "" : apiKey.strip();
        this.model = model;
    }

    public boolean enabled() {
        return !apiKey.isBlank();
    }

    public String model() {
        return model;
    }

    public AnthropicClient get() {
        if (!enabled()) {
            throw new IllegalStateException("IA não configurada: defina ANTHROPIC_API_KEY.");
        }
        AnthropicClient local = client;
        if (local == null) {
            synchronized (this) {
                if (client == null) {
                    client = AnthropicOkHttpClient.builder().apiKey(apiKey).build();
                }
                local = client;
            }
        }
        return local;
    }
}

package com.vini.financemonitor.ai;

import com.anthropic.models.messages.Base64PdfSource;
import com.anthropic.models.messages.ContentBlockParam;
import com.anthropic.models.messages.DocumentBlockParam;
import com.anthropic.models.messages.MessageCreateParams;
import com.anthropic.models.messages.StructuredMessage;
import com.anthropic.models.messages.StructuredMessageCreateParams;
import com.anthropic.models.messages.TextBlockParam;
import com.fasterxml.jackson.annotation.JsonClassDescription;
import com.fasterxml.jackson.annotation.JsonPropertyDescription;
import com.vini.financemonitor.ingestion.pdf.ParsedRow;
import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.Base64;
import java.util.List;
import org.springframework.stereotype.Component;

/**
 * Fallback de extração por IA: quando o parser determinístico não reconcilia
 * ao centavo (layout novo do Sicredi, banco diferente), o PDF vai para o Claude
 * com saída estruturada e as linhas voltam no MESMO formato do parser — e passam
 * pelo MESMO gate de reconciliação. Alucinação não sobrevive ao gate.
 */
@Component
public class LlmStatementExtractor {

    private final AiClient ai;

    public LlmStatementExtractor(AiClient ai) {
        this.ai = ai;
    }

    public boolean enabled() {
        return ai.enabled();
    }

    @JsonClassDescription("Uma linha de transação da fatura de cartão de crédito")
    public record ExtractedRow(
            @JsonPropertyDescription("Data no formato DD/mmm com mês pt-BR abreviado em minúsculo (ex: 16/jul). Vazio se a linha não tem data (ex: IOF, anuidade sem data).")
            String date,
            @JsonPropertyDescription("Descrição/estabelecimento como impresso, incluindo cidade e canal quando presentes. Se a compra é parcelada, inclua o marcador NN/MM da coluna Parcela (ex: 01/05).")
            String description,
            @JsonPropertyDescription("Valor em reais como string decimal com ponto, ex: 1077.66. POSITIVO para despesas, NEGATIVO para pagamentos, estornos e créditos (linhas com -R$).")
            String amount,
            @JsonPropertyDescription("Últimos 4 dígitos do cartão da seção onde a linha aparece (cabeçalho 'Cartão ... (final NNNN)'), ou vazio.")
            String cardLast4) {
    }

    @JsonClassDescription("Todas as transações extraídas da fatura, na ordem em que aparecem")
    public record ExtractedStatement(
            @JsonPropertyDescription("Todas as linhas de transação das páginas de 'Transações', incluindo pagamentos, créditos, IOF e anuidade. NÃO incluir os rodapés 'Total cartão', cabeçalhos ou resumos.")
            List<ExtractedRow> rows) {
    }

    /** Extrai as linhas do PDF via Claude e converte para o formato do parser. */
    public List<ParsedRow> extract(byte[] pdfBytes) {
        String b64 = Base64.getEncoder().encodeToString(pdfBytes);

        String prompt = """
                Extraia TODAS as transações desta fatura de cartão de crédito.
                Regras:
                - Percorra todas as páginas com a seção "Transações", em todas as seções de cartão.
                - Uma linha por transação, na ordem impressa.
                - Despesas são positivas; pagamentos, estornos e créditos (prefixo -R$) são negativos.
                - Transações internacionais mostram valor em dólar e cotação: use SEMPRE o "Valor em reais" (última coluna).
                - Não invente linhas; não inclua totais, subtotais ou texto legal.
                - A soma das linhas positivas deve bater ao centavo com o "Despesas atuais" do resumo da página 1 — confira antes de responder.
                """;

        StructuredMessageCreateParams<ExtractedStatement> params = MessageCreateParams.builder()
                .model(ai.model())
                .maxTokens(64000L)
                .outputConfig(ExtractedStatement.class)
                .addUserMessageOfBlockParams(List.of(
                        ContentBlockParam.ofDocument(DocumentBlockParam.builder()
                                .source(Base64PdfSource.builder().data(b64).build())
                                .build()),
                        ContentBlockParam.ofText(TextBlockParam.builder().text(prompt).build())))
                .build();

        StructuredMessage<ExtractedStatement> response = ai.get().messages().create(params);

        ExtractedStatement extracted = response.content().stream()
                .flatMap(block -> block.text().stream())
                .map(typed -> typed.text())
                .findFirst()
                .orElseThrow(() -> new IllegalStateException("IA não retornou transações."));

        List<ParsedRow> rows = new ArrayList<>();
        for (ExtractedRow row : extracted.rows()) {
            String date = row.date() == null ? "" : row.date().strip();
            String description = row.description() == null ? "" : row.description().strip();
            String raw = (date.isEmpty() ? description : date + "  " + description);
            if (raw.length() < 8) {
                raw = String.format("%-8s", raw);
            }
            BigDecimal amount = new BigDecimal(row.amount().strip());
            String card = row.cardLast4() == null || row.cardLast4().isBlank() ? null : row.cardLast4().strip();
            rows.add(new ParsedRow(0, raw, amount, description, card));
        }
        return rows;
    }
}

