    private static final String SYSTEM_PROMPT = """
            Você é o assistente do Finance Monitor, um app pessoal de finanças de um casal \
            (Vinicius e a esposa). A pergunta-norte do produto é: "quanto do nosso futuro já está \
            comprometido?" — parcelas a vencer + assinaturas confirmadas contra a renda mensal.

            Contexto do domínio:
            - Os dados vêm de faturas do cartão Sicredi Mastercard Black importadas por PDF, \
            reconciliadas ao centavo com a página 1 da fatura (gate contábil).
            - "Fatura de agosto" no Sicredi = fecha ~26/07 e vence 10/08.
            - Modo casal: cada transação/assinatura/parcelamento pode ter dono (membro) ou ser \
            "Casa" (comum, member_id nulo). A atribuição por cartão é automática (seção "Cartão \
            ... final NNNN" da fatura).
            - Projeção: comprometido(M) = parcelas_a_vencer(M) + assinaturas_confirmadas(M); \
            índice = comprometido/receita. Faixas: <30% saudável, 30-50% atenção, 50-70% \
            comprometido, >70% crítico. Bruto inclui parcelas de terceiros; líquido desconta.
            - Rotativo: pagou menos que o total da fatura => juros ~11,2% a.m. (Sicredi).

            Regras:
            - SEMPRE use as tools para obter números; nunca estime nem invente valores.
            - Valores em reais no formato brasileiro (R$ 1.234,56). Meses como "ago/2026".
            - Responda em português do Brasil, de forma direta e concisa; use listas curtas \
            quando ajudar. Sem jargão técnico do app (ids, nomes de tabela).
            - Você pode analisar, comparar meses, apontar riscos (rotativo, assinaturas \
            redundantes, parcelas altas) e sugerir ações — mas deixe claro que não é \
            aconselhamento financeiro profissional.
            - Se os dados não cobrirem a pergunta (ex.: mês não importado), diga isso.
            """;

    private final AiClient ai;
    private final ObjectMapper json;
    private final ProjectionService projection;
    private final SubscriptionWeightService subscriptions;
    private final CreditHealthService creditHealth;
    private final MemberService members;
    private final StatementService statements;
    private final TransactionRepository transactions;

    public AssistantService(AiClient ai,
                            ObjectMapper json,
                            ProjectionService projection,
                            SubscriptionWeightService subscriptions,
                            CreditHealthService creditHealth,
                            MemberService members,
                            StatementService statements,
                            TransactionRepository transactions) {
        this.ai = ai;
        this.json = json;
        this.projection = projection;
        this.subscriptions = subscriptions;
        this.creditHealth = creditHealth;
        this.members = members;
        this.statements = statements;
        this.transactions = transactions;
    }

    public boolean enabled() {
        return ai.enabled();
    }

    public String model() {
        return ai.model();
    }

    public AssistantReply chat(List<AssistantMessage> history) {
        List<MessageParam> messages = new ArrayList<>();
        for (AssistantMessage m : history) {
            MessageParam.Role role = "assistant".equalsIgnoreCase(m.role())
                    ? MessageParam.Role.ASSISTANT
                    : MessageParam.Role.USER;
            messages.add(MessageParam.builder().role(role).content(m.content()).build());
        }

        Set<String> toolsUsed = new LinkedHashSet<>();
        StringBuilder finalText = new StringBuilder();

        for (int round = 0; round <= MAX_TOOL_ROUNDS; round++) {
            Message response = ai.get().messages().create(baseParams(messages).build());

            List<ContentBlockParam> assistantEcho = new ArrayList<>();
            List<ToolUseBlock> toolUses = new ArrayList<>();
            StringBuilder turnText = new StringBuilder();

            for (ContentBlock block : response.content()) {
                block.text().ifPresent(t -> {
                    turnText.append(t.text());
                    assistantEcho.add(ContentBlockParam.ofText(
                            TextBlockParam.builder().text(t.text()).build()));
                });
                block.thinking().ifPresent(t -> assistantEcho.add(ContentBlockParam.ofThinking(
                        ThinkingBlockParam.builder()
                                .thinking(t.thinking())
                                .signature(t.signature())
                                .build())));
                block.redactedThinking().ifPresent(t -> assistantEcho.add(ContentBlockParam.ofRedactedThinking(
                        RedactedThinkingBlockParam.builder().data(t.data()).build())));
                block.toolUse().ifPresent(tu -> {
                    toolUses.add(tu);
                    assistantEcho.add(ContentBlockParam.ofToolUse(
                            ToolUseBlockParam.builder()
                                    .id(tu.id())
                                    .name(tu.name())
                                    .input(tu._input())
                                    .build()));
                });
            }

            boolean wantsTools = response.stopReason()
                    .map(r -> StopReason.TOOL_USE.equals(r))
                    .orElse(false);

            if (!wantsTools || toolUses.isEmpty()) {
                finalText.setLength(0);
                finalText.append(turnText);
                break;
            }

            messages.add(MessageParam.builder()
                    .role(MessageParam.Role.ASSISTANT)
                    .contentOfBlockParams(assistantEcho)
                    .build());

            List<ContentBlockParam> results = new ArrayList<>();
            for (ToolUseBlock tu : toolUses) {
                toolsUsed.add(tu.name());
                String result;
                boolean isError = false;
                try {
                    result = runTool(tu);
                } catch (Exception e) {
                    result = "Erro ao consultar: " + e.getMessage();
                    isError = true;
                }
                results.add(ContentBlockParam.ofToolResult(
                        ToolResultBlockParam.builder()
                                .toolUseId(tu.id())
                                .content(result)
                                .isError(isError)
                                .build()));
            }
            messages.add(MessageParam.builder()
                    .role(MessageParam.Role.USER)
                    .contentOfBlockParams(results)
                    .build());
        }

        return new AssistantReply(finalText.toString(), List.copyOf(toolsUsed), ai.model());
    }

    private MessageCreateParams.Builder baseParams(List<MessageParam> messages) {
        MessageCreateParams.Builder builder = MessageCreateParams.builder()
                .model(ai.model())
                .maxTokens(8000L)
                .systemOfTextBlockParams(List.of(TextBlockParam.builder()
                        .text(SYSTEM_PROMPT)
                        .cacheControl(CacheControlEphemeral.builder().build())
                        .build()));
        for (Tool tool : tools()) {
            builder.addTool(tool);
        }
        builder.messages(messages);
        return builder;
    }

    private List<Tool> tools() {
        return List.of(
                simpleTool("get_projection",
                        "Projeção de comprometimento futuro mês a mês: parcelas a vencer, assinaturas, "
                                + "comprometido bruto/líquido, índice sobre a renda e faixa de risco.",
                        Map.of("months", Map.of("type", "string",
                                "description", "Horizonte em meses (1 a 12), ex: \"6\"")),
                        List.of()),
                simpleTool("get_subscriptions_weight",
                        "Peso das assinaturas confirmadas: total mensal, anualizado, % da renda, "
                                + "ranking por valor e agrupamento por categoria (revela redundância).",
                        Map.of(), List.of()),
                simpleTool("get_credit_health",
                        "Saúde de crédito: fatura mais recente, faturas com rotativo, saldo carregado "
                                + "e juros projetados a 1 e 6 meses.",
                        Map.of(), List.of()),
                simpleTool("get_couple_summary",
                        "Resumo do modo casal em um mês de fatura: gasto, assinaturas e parcelas a "
                                + "vencer por membro (Vinicius, Esposa) e o balde 'Casa (em comum)'.",
                        Map.of("month", Map.of("type", "string",
                                "description", "Mês de referência no formato YYYY-MM, ex: \"2026-08\"")),
                        List.of("month")),
                simpleTool("get_month_transactions",
                        "Lista todas as transações de um mês de fatura: data, descrição, valor, "
                                + "categoria, cartão de origem e dono (memberId).",
                        Map.of("month", Map.of("type", "string",
                                "description", "Mês de referência no formato YYYY-MM, ex: \"2026-08\"")),
                        List.of("month")),
                simpleTool("get_category_totals",
                        "Gastos acumulados por categoria em todo o histórico importado.",
                        Map.of(), List.of()),
                simpleTool("list_statements",
                        "Faturas importadas: mês de referência, total, valor pago e se entrou no rotativo.",
                        Map.of(), List.of()),
                simpleTool("list_members",
                        "Membros do casal cadastrados e o cartão (final) que atribui gastos automaticamente.",
                        Map.of(), List.of()));
    }

    private Tool simpleTool(String name, String description,
                            Map<String, Map<String, String>> props, List<String> required) {
        Tool.InputSchema.Properties.Builder properties = Tool.InputSchema.Properties.builder();
        for (Map.Entry<String, Map<String, String>> entry : props.entrySet()) {
            properties.putAdditionalProperty(entry.getKey(), JsonValue.from(entry.getValue()));
        }
        Tool.InputSchema.Builder schema = Tool.InputSchema.builder().properties(properties.build());
        if (!required.isEmpty()) {
            schema.required(required);
        }
        return Tool.builder()
                .name(name)
                .description(description)
                .inputSchema(schema.build())
                .build();
    }

    private String runTool(ToolUseBlock tu) throws Exception {
        return switch (tu.name()) {
            case "get_projection" -> json.writeValueAsString(
                    projection.project(parseMonths(argument(tu, "months").orElse("6"))));
            case "get_subscriptions_weight" -> json.writeValueAsString(subscriptions.weight());
            case "get_credit_health" -> json.writeValueAsString(creditHealth.build());
            case "get_couple_summary" -> json.writeValueAsString(
                    members.summary(YearMonth.parse(argument(tu, "month").orElseThrow(
                            () -> new IllegalArgumentException("month é obrigatório")))));
            case "get_month_transactions" -> json.writeValueAsString(
                    members.monthTransactions(YearMonth.parse(argument(tu, "month").orElseThrow(
                            () -> new IllegalArgumentException("month é obrigatório")))));
            case "get_category_totals" -> json.writeValueAsString(
                    transactions.totalsByCategory(LocalDate.of(2000, 1, 1), LocalDate.now()));
            case "list_statements" -> json.writeValueAsString(statements.listOrderedByMonth());
            case "list_members" -> json.writeValueAsString(members.list());
            default -> throw new IllegalArgumentException("Tool desconhecida: " + tu.name());
        };
    }

    private Optional<String> argument(ToolUseBlock tu, String key) {
        return tu._input().asObject()
                .map(obj -> obj.get(key))
                .flatMap(v -> v == null ? Optional.empty() : v.asString());
    }

    private int parseMonths(String raw) {
        try {
            return Math.max(1, Math.min(12, Integer.parseInt(raw.strip())));
        } catch (NumberFormatException e) {
            return 6;
        }
    }
}

