import { useMutation, useQuery } from '@tanstack/react-query'
import { createFileRoute } from '@tanstack/react-router'
import { KeyRound, Send, Sparkles } from 'lucide-react'
import { useEffect, useRef, useState } from 'react'
import { toast } from 'sonner'

import { Pill } from '@/components/lists/Pill'
import { PageHeader } from '@/components/shell/PageHeader'
import { Button } from '@/components/ui/button'
import { Skeleton } from '@/components/ui/skeleton'
import { ApiError, assistant } from '@/lib/api'
import { cn } from '@/lib/utils'
import type { AssistantChatMessage } from '@/types/api'

export const Route = createFileRoute('/assistente')({
  component: AssistenteRoute,
})

const TOOL_LABELS: Record<string, string> = {
  get_projection: 'projeção',
  get_subscriptions_weight: 'assinaturas',
  get_credit_health: 'saúde de crédito',
  get_couple_summary: 'casal',
  get_month_transactions: 'transações',
  get_category_totals: 'categorias',
  list_statements: 'faturas',
  list_members: 'membros',
}

const SUGGESTIONS = [
  'Como está nosso comprometimento para os próximos meses?',
  'Quais assinaturas estão redundantes ou caras?',
  'Quanto cada um gastou na fatura de agosto?',
  'Entramos no rotativo em algum mês? Quanto custou?',
  'Compare os gastos de mercado entre os últimos meses.',
]

interface ChatEntry extends AssistantChatMessage {
  toolsUsed?: string[]
}

function AssistenteRoute() {
  const status = useQuery({
    queryKey: ['assistant', 'status'],
    queryFn: () => assistant.status(),
  })

  return (
    <>
      <PageHeader
        eyebrow="ia"
        title="Assistente"
        subtitle="Converse sobre os dados de vocês: ele consulta o app, não inventa números"
        actions={
          status.data?.enabled ? (
            <Pill tone="ok">{status.data.model}</Pill>
          ) : undefined
        }
      />
      {status.isLoading ? (
        <Skeleton className="mt-6 h-64 w-full" />
      ) : status.data?.enabled ? (
        <Chat />
      ) : (
        <DisabledState />
      )}
    </>
  )
}

function DisabledState() {
  return (
    <div className="mt-6 rounded-lg border border-border bg-surface p-8">
      <div className="flex items-start gap-4">
        <KeyRound className="mt-1 h-5 w-5 shrink-0 text-accent" />
        <div className="space-y-2">
          <h2 className="text-sm font-medium text-text">IA não configurada</h2>
          <p className="max-w-xl text-sm text-muted">
            Defina a variável <span className="font-mono text-text">ANTHROPIC_API_KEY</span>{' '}
            no ambiente da API (arquivo <span className="font-mono text-text">.env</span> na
            raiz do projeto) e reinicie o serviço. A chave é criada em{' '}
            <span className="font-mono text-text">console.anthropic.com</span>. O modelo pode
            ser trocado via <span className="font-mono text-text">APP_AI_MODEL</span>.
          </p>
          <p className="max-w-xl text-xs text-muted">
            Sem a chave, o app continua funcionando normalmente; apenas o assistente e o
            fallback de extração por IA no import ficam desligados.
          </p>
        </div>
      </div>
    </div>
  )
}

function Chat() {
  const [entries, setEntries] = useState<ChatEntry[]>([])
  const [input, setInput] = useState('')
  const scrollRef = useRef<HTMLDivElement>(null)

  const send = useMutation({
    mutationFn: (history: AssistantChatMessage[]) => assistant.chat(history),
    onSuccess: (data) => {
      setEntries((prev) => [
        ...prev,
        { role: 'assistant', content: data.reply, toolsUsed: data.toolsUsed },
      ])
    },
    onError: (err: ApiError) => {
      toast.error('Falha no assistente', { description: err.message })
    },
  })

  useEffect(() => {
    scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' })
  }, [entries, send.isPending])

  function submit(text: string) {
    const content = text.trim()
    if (content === '' || send.isPending) return
    const next: ChatEntry[] = [...entries, { role: 'user', content }]
    setEntries(next)
    setInput('')
    send.mutate(next.map(({ role, content: c }) => ({ role, content: c })))
  }

  return (
    <div className="mt-6 flex h-[calc(100vh-220px)] min-h-[420px] flex-col rounded-lg border border-border bg-surface">
      <div ref={scrollRef} className="flex-1 space-y-4 overflow-y-auto p-4">
        {entries.length === 0 && (
          <div className="flex h-full flex-col items-center justify-center gap-4">
            <Sparkles className="h-6 w-6 text-accent" />
            <p className="text-sm text-muted">
              Pergunte qualquer coisa sobre as finanças de vocês.
            </p>
            <div className="flex max-w-xl flex-wrap justify-center gap-2">
              {SUGGESTIONS.map((s) => (
                <button
                  key={s}
                  type="button"
                  onClick={() => submit(s)}
                  className="rounded-full border border-border bg-panel px-3 py-1.5 text-xs text-muted transition-colors hover:border-accent/50 hover:text-text"
                >
                  {s}
                </button>
              ))}
            </div>
          </div>
        )}

        {entries.map((entry, i) => (
          <div
            key={i}
            className={cn('flex', entry.role === 'user' ? 'justify-end' : 'justify-start')}
          >
            <div
              className={cn(
                'max-w-[85%] rounded-lg border px-4 py-3 text-sm leading-relaxed',
                entry.role === 'user'
                  ? 'border-accent/30 bg-accent/10 text-text'
                  : 'border-border bg-panel text-text',
              )}
            >
              <div className="whitespace-pre-wrap">{entry.content}</div>
              {entry.toolsUsed && entry.toolsUsed.length > 0 && (
                <div className="mt-2 flex flex-wrap gap-1 border-t border-border pt-2">
                  <span className="font-mono text-[9px] uppercase tracking-[0.18em] text-muted">
                    consultou:
                  </span>
                  {entry.toolsUsed.map((t) => (
                    <span
                      key={t}
                      className="rounded-full border border-ok/30 bg-ok/10 px-1.5 py-0.5 font-mono text-[9px] uppercase tracking-[0.12em] text-ok"
                    >
                      {TOOL_LABELS[t] ?? t}
