          className="min-h-[44px] flex-1 resize-none rounded-md border border-border bg-panel px-3 py-2 text-sm text-text outline-none placeholder:text-muted/60 focus:border-accent"
        />
        <Button type="submit" disabled={send.isPending || input.trim() === ''}>
          <Send className="h-4 w-4" />
          Enviar
        </Button>
      </form>
    </div>
  )
}

