package com.vini.financemonitor.ai;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.MediaType;
import org.springframework.http.client.SimpleClientHttpRequestFactory;
import org.springframework.stereotype.Component;
import org.springframework.web.client.RestClient;
import org.springframework.web.client.RestClientResponseException;

/**
 * Acesso ao Google Gemini (API generativelanguage, REST v1beta). Habilitado
 * apenas quando GEMINI_API_KEY (ou GOOGLE_API_KEY) está presente — sem chave,
 * o app funciona normalmente e as features de IA respondem "não configurado".
 */
@Component
public class AiClient {

    private static final String BASE_URL = "https://generativelanguage.googleapis.com";

    private final String apiKey;
    private final String model;
    private volatile RestClient rest;

    public AiClient(@Value("${GEMINI_API_KEY:${GOOGLE_API_KEY:}}") String apiKey,
                    @Value("${app.ai.model}") String model) {
        this.apiKey = apiKey == null ? "" : apiKey.strip();
        this.model = model;
    }

    public boolean enabled() {
        return !apiKey.isBlank();
    }

    public String model() {
        return model;
    }

    /** POST models/{model}:generateContent com o corpo dado; retorna o JSON da resposta. */
    public JsonNode generateContent(ObjectNode body) {
        try {
            return rest().post()
                    .uri("/v1beta/models/{model}:generateContent", model)
                    .contentType(MediaType.APPLICATION_JSON)
                    .body(body.toString())
                    .retrieve()
                    .body(JsonNode.class);
        } catch (RestClientResponseException e) {
            String detail = e.getResponseBodyAsString();
            throw new IllegalStateException("Gemini retornou " + e.getStatusCode().value()
                    + (detail.isBlank() ? "" : ": " + truncate(detail)), e);
        }
    }

    /** GET /v1beta/models — útil para diagnosticar nome de modelo inválido. */
    public JsonNode listModels() {
        return rest().get().uri("/v1beta/models?pageSize=50").retrieve().body(JsonNode.class);
    }

    private RestClient rest() {
        if (!enabled()) {
            throw new IllegalStateException("IA não configurada: defina GEMINI_API_KEY.");
        }
        RestClient local = rest;
        if (local == null) {
            synchronized (this) {
                if (rest == null) {
                    SimpleClientHttpRequestFactory factory = new SimpleClientHttpRequestFactory();
                    factory.setConnectTimeout(10_000);
                    factory.setReadTimeout(180_000);
                    rest = RestClient.builder()
                            .baseUrl(BASE_URL)
                            .requestFactory(factory)
                            .defaultHeader("x-goog-api-key", apiKey)
                            .build();
                }
                local = rest;
            }
        }
        return local;
    }

    private static String truncate(String s) {
        return s.length() > 400 ? s.substring(0, 400) + "…" : s;
    }

    static ObjectMapper mapper() {
        return MAPPER;
    }

    private static final ObjectMapper MAPPER = new ObjectMapper();
}

package com.vini.financemonitor.ai;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.vini.financemonitor.ingestion.pdf.ParsedRow;
import java.math.BigDecimal;
import java.util.ArrayList;
import java.util.Base64;
import java.util.List;
import org.springframework.stereotype.Component;

/**
 * Fallback de extração por IA: quando o parser determinístico não reconcilia
 * ao centavo (layout novo do Sicredi, banco diferente), o PDF vai para o Gemini
 * com saída estruturada (responseSchema) e as linhas voltam no MESMO formato do
 * parser — e passam pelo MESMO gate de reconciliação. Alucinação não sobrevive
 * ao gate.
 */
@Component
public class LlmStatementExtractor {

    private final AiClient ai;
    private final ObjectMapper json;

    public LlmStatementExtractor(AiClient ai, ObjectMapper json) {
        this.ai = ai;
        this.json = json;
    }

    public boolean enabled() {
        return ai.enabled();
    }

    /** Extrai as linhas do PDF via Gemini e converte para o formato do parser. */
    public List<ParsedRow> extract(byte[] pdfBytes) {
        String b64 = Base64.getEncoder().encodeToString(pdfBytes);

        String prompt = """
                Extraia TODAS as transações desta fatura de cartão de crédito.
                Regras:
                - Percorra todas as páginas com a seção "Transações", em todas as seções de cartão.
                - Uma linha por transação, na ordem impressa.
                - "date": data no formato DD/mmm com mês pt-BR abreviado minúsculo (ex: 16/jul); vazio se a linha não tem data.
                - "description": descrição como impressa; se a compra é parcelada, inclua o marcador NN/MM da coluna Parcela (ex: 01/05).
                - "amount": valor em reais como string decimal com ponto (ex: 1077.66). POSITIVO para despesas; NEGATIVO para pagamentos, estornos e créditos (linhas com -R$).
                - "cardLast4": últimos 4 dígitos do cartão da seção onde a linha aparece (cabeçalho "Cartão ... (final NNNN)"), ou vazio.
                - Transações internacionais mostram valor em dólar e cotação: use SEMPRE o "Valor em reais" (última coluna).
                - Não invente linhas; não inclua os rodapés "Total cartão", cabeçalhos, resumos ou texto legal.
                - A soma das linhas positivas deve bater ao centavo com o "Despesas atuais" do resumo da página 1 — confira antes de responder.
                """;

        ObjectNode body = json.createObjectNode();
        ArrayNode contents = body.putArray("contents");
        ObjectNode user = contents.addObject();
        user.put("role", "user");
        ArrayNode parts = user.putArray("parts");
        ObjectNode inline = parts.addObject().putObject("inlineData");
        inline.put("mimeType", "application/pdf");
        inline.put("data", b64);
        parts.addObject().put("text", prompt);

        ObjectNode generationConfig = body.putObject("generationConfig");
        generationConfig.put("responseMimeType", "application/json");
        generationConfig.set("responseSchema", responseSchema());
        generationConfig.put("maxOutputTokens", 32768);

        JsonNode response = ai.generateContent(body);
        String text = firstText(response);
        if (text == null || text.isBlank()) {
            throw new IllegalStateException("IA não retornou transações (resposta vazia).");
        }

        List<ParsedRow> rows = new ArrayList<>();
        try {
            JsonNode parsed = json.readTree(text);
            for (JsonNode row : parsed.path("rows")) {
                String date = row.path("date").asText("").strip();
                String description = row.path("description").asText("").strip();
                String raw = date.isEmpty() ? description : date + "  " + description;
                if (raw.length() < 8) {
                    raw = String.format("%-8s", raw);
                }
                BigDecimal amount = new BigDecimal(row.path("amount").asText().strip());
                String card = row.path("cardLast4").asText("").strip();
                rows.add(new ParsedRow(0, raw, amount, description, card.isEmpty() ? null : card));
            }
        } catch (Exception e) {
            throw new IllegalStateException("Falha ao interpretar a extração da IA: " + e.getMessage(), e);
        }
        return rows;
    }

    private ObjectNode responseSchema() {
        ObjectNode rowSchema = json.createObjectNode();
        rowSchema.put("type", "OBJECT");
        ObjectNode rowProps = rowSchema.putObject("properties");
        rowProps.putObject("date").put("type", "STRING");
        rowProps.putObject("description").put("type", "STRING");
        rowProps.putObject("amount").put("type", "STRING");
        rowProps.putObject("cardLast4").put("type", "STRING");
        rowSchema.putArray("required").add("description").add("amount");

        ObjectNode schema = json.createObjectNode();
        schema.put("type", "OBJECT");
        ObjectNode props = schema.putObject("properties");
        ObjectNode rowsSchema = props.putObject("rows");
        rowsSchema.put("type", "ARRAY");
        rowsSchema.set("items", rowSchema);
        schema.putArray("required").add("rows");
        return schema;
    }

    private String firstText(JsonNode response) {
        StringBuilder sb = new StringBuilder();
        for (JsonNode part : response.path("candidates").path(0).path("content").path("parts")) {
            if (part.has("text")) {
                sb.append(part.get("text").asText());
            }
        }
        return sb.toString();
    }
}

package com.vini.financemonitor.ai;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.vini.financemonitor.member.MemberService;
import com.vini.financemonitor.projection.ProjectionService;
import com.vini.financemonitor.recurrence.SubscriptionWeightService;
import com.vini.financemonitor.statement.CreditHealthService;
import com.vini.financemonitor.statement.StatementService;
import com.vini.financemonitor.transaction.TransactionRepository;
import com.vini.financemonitor.web.dto.AssistantMessage;
import com.vini.financemonitor.web.dto.AssistantReply;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.springframework.stereotype.Service;

/**
 * Assistente do casal: chat (Gemini, function calling) com acesso somente
 * leitura aos serviços do próprio app — projeção, assinaturas, saúde de
 * crédito, modo casal e transações. O modelo consulta; nunca inventa números.
 */
@Service
public class AssistantService {

    private static final int MAX_TOOL_ROUNDS = 8;

    private static final String SYSTEM_PROMPT = """
            Você é o assistente do Finance Monitor, um app pessoal de finanças de um casal \
            (Vinicius e a esposa). A pergunta-norte do produto é: "quanto do nosso futuro já está \
            comprometido?" — parcelas a vencer + assinaturas confirmadas contra a renda mensal.

            Contexto do domínio:
            - Os dados vêm de faturas do cartão Sicredi Mastercard Black importadas por PDF, \
            reconciliadas ao centavo com a página 1 da fatura (gate contábil).
            - "Fatura de agosto" no Sicredi = fecha ~26/07 e vence 10/08.
            - Modo casal: cada transação/assinatura/parcelamento pode ter dono (membro) ou ser \
            "Casa" (comum). A atribuição por cartão é automática (seção "Cartão ... final NNNN").
            - Projeção: comprometido(M) = parcelas_a_vencer(M) + assinaturas_confirmadas(M); \
            índice = comprometido/receita. Faixas: <30% saudável, 30-50% atenção, 50-70% \
            comprometido, >70% crítico. Bruto inclui parcelas de terceiros; líquido desconta.
            - Rotativo: pagou menos que o total da fatura => juros ~11,2% a.m. (Sicredi).

            Regras:
            - SEMPRE use as funções para obter números; nunca estime nem invente valores.
            - Valores em reais no formato brasileiro (R$ 1.234,56). Meses como "ago/2026".
            - Responda em português do Brasil, direto e conciso; listas curtas quando ajudar. \
            Sem jargão técnico do app (ids, nomes de tabela).
            - Você pode analisar, comparar meses, apontar riscos (rotativo, assinaturas \
            redundantes, parcelas altas) e sugerir ações — deixando claro que não é \
            aconselhamento financeiro profissional.
            - Se os dados não cobrirem a pergunta (ex.: mês não importado), diga isso.
            """;

    private final AiClient ai;
    private final ObjectMapper json;
    private final ProjectionService projection;
    private final SubscriptionWeightService subscriptions;
    private final CreditHealthService creditHealth;
    private final MemberService members;
    private final StatementService statements;
    private final TransactionRepository transactions;

    public AssistantService(AiClient ai,
                            ObjectMapper json,
                            ProjectionService projection,
                            SubscriptionWeightService subscriptions,
                            CreditHealthService creditHealth,
                            MemberService members,
                            StatementService statements,
                            TransactionRepository transactions) {
        this.ai = ai;
        this.json = json;
        this.projection = projection;
        this.subscriptions = subscriptions;
        this.creditHealth = creditHealth;
        this.members = members;
        this.statements = statements;
        this.transactions = transactions;
    }

    public boolean enabled() {
        return ai.enabled();
    }

    public String model() {
        return ai.model();
    }

    public AssistantReply chat(List<AssistantMessage> history) {
        ArrayNode contents = json.createArrayNode();
        for (AssistantMessage m : history) {
            ObjectNode content = contents.addObject();
            content.put("role", "assistant".equalsIgnoreCase(m.role()) ? "model" : "user");
            content.putArray("parts").addObject().put("text", m.content());
        }

        Set<String> toolsUsed = new LinkedHashSet<>();
        String finalText = "";

        for (int round = 0; round <= MAX_TOOL_ROUNDS; round++) {
            JsonNode response = ai.generateContent(requestBody(contents));
            JsonNode content = response.path("candidates").path(0).path("content");

            StringBuilder turnText = new StringBuilder();
            List<JsonNode> functionCalls = new java.util.ArrayList<>();
            for (JsonNode part : content.path("parts")) {
                if (part.has("text")) {
                    turnText.append(part.get("text").asText());
                }
                if (part.has("functionCall")) {
                    functionCalls.add(part.get("functionCall"));
                }
            }

            if (functionCalls.isEmpty()) {
                finalText = turnText.toString();
                if (finalText.isBlank()) {
                    String reason = response.path("candidates").path(0).path("finishReason").asText("");
                    finalText = "Não consegui gerar uma resposta"
                            + (reason.isBlank() ? "." : " (motivo: " + reason + ").");
                }
                break;
            }

            // Ecoa o turno do modelo (com as functionCalls) e responde cada chamada.
            contents.add(content.deepCopy());
            ObjectNode toolTurn = contents.addObject();
            toolTurn.put("role", "user");
            ArrayNode toolParts = toolTurn.putArray("parts");
            for (JsonNode call : functionCalls) {
                String name = call.path("name").asText();
                toolsUsed.add(name);
                ObjectNode functionResponse = toolParts.addObject().putObject("functionResponse");
                functionResponse.put("name", name);
                ObjectNode payload = functionResponse.putObject("response");
                try {
                    payload.set("data", json.readTree(runTool(name, call.path("args"))));
                } catch (Exception e) {
                    payload.put("error", "Erro ao consultar: " + e.getMessage());
                }
            }
        }

        return new AssistantReply(finalText, List.copyOf(toolsUsed), ai.model());
    }

    private ObjectNode requestBody(ArrayNode contents) {
        ObjectNode body = json.createObjectNode();
        body.putObject("systemInstruction").putArray("parts").addObject().put("text", SYSTEM_PROMPT);
        body.set("contents", contents.deepCopy());
        ArrayNode tools = body.putArray("tools");
        tools.addObject().set("functionDeclarations", functionDeclarations());
        body.putObject("generationConfig").put("maxOutputTokens", 8192);
        return body;
    }

    private ArrayNode functionDeclarations() {
        ArrayNode declarations = json.createArrayNode();
        declarations.add(declaration("get_projection",
                "Projeção de comprometimento futuro mês a mês: parcelas a vencer, assinaturas, "
                        + "comprometido bruto/líquido, índice sobre a renda e faixa de risco.",
                Map.of("months", "Horizonte em meses (1 a 12), ex: \"6\""), List.of()));
        declarations.add(declaration("get_subscriptions_weight",
                "Peso das assinaturas confirmadas: total mensal, anualizado, % da renda, ranking "
                        + "por valor e agrupamento por categoria (revela redundância).",
                Map.of(), List.of()));
        declarations.add(declaration("get_credit_health",
                "Saúde de crédito: fatura mais recente, faturas com rotativo, saldo carregado e "
                        + "juros projetados a 1 e 6 meses.",
                Map.of(), List.of()));
        declarations.add(declaration("get_couple_summary",
                "Resumo do modo casal em um mês de fatura: gasto, assinaturas e parcelas a vencer "
                        + "por membro e o balde 'Casa (em comum)'.",
                Map.of("month", "Mês de referência no formato YYYY-MM, ex: \"2026-08\""),
                List.of("month")));
        declarations.add(declaration("get_month_transactions",
                "Lista todas as transações de um mês de fatura: data, descrição, valor, categoria, "
                        + "cartão de origem e dono (memberId).",
                Map.of("month", "Mês de referência no formato YYYY-MM, ex: \"2026-08\""),
                List.of("month")));
        declarations.add(declaration("get_category_totals",
                "Gastos acumulados por categoria em todo o histórico importado.",
                Map.of(), List.of()));
        declarations.add(declaration("list_statements",
                "Faturas importadas: mês de referência, total, valor pago e se entrou no rotativo.",
                Map.of(), List.of()));
        declarations.add(declaration("list_members",
                "Membros do casal cadastrados e o cartão (final) que atribui gastos automaticamente.",
                Map.of(), List.of()));
        return declarations;
    }

    private ObjectNode declaration(String name, String description,
                                   Map<String, String> stringProps, List<String> required) {
        ObjectNode declaration = json.createObjectNode();
        declaration.put("name", name);
        declaration.put("description", description);
        ObjectNode parameters = declaration.putObject("parameters");
        parameters.put("type", "OBJECT");
        ObjectNode properties = parameters.putObject("properties");
        for (Map.Entry<String, String> entry : stringProps.entrySet()) {
            ObjectNode prop = properties.putObject(entry.getKey());
            prop.put("type", "STRING");
            prop.put("description", entry.getValue());
        }
        if (!required.isEmpty()) {
            ArrayNode req = parameters.putArray("required");
            required.forEach(req::add);
        }
        return declaration;
    }

    private String runTool(String name, JsonNode args) throws Exception {
        return switch (name) {
            case "get_projection" -> json.writeValueAsString(
                    projection.project(parseMonths(args.path("months").asText("6"))));
            case "get_subscriptions_weight" -> json.writeValueAsString(subscriptions.weight());
            case "get_credit_health" -> json.writeValueAsString(creditHealth.build());
            case "get_couple_summary" -> json.writeValueAsString(
                    members.summary(requiredMonth(args)));
            case "get_month_transactions" -> json.writeValueAsString(
                    members.monthTransactions(requiredMonth(args)));
            case "get_category_totals" -> json.writeValueAsString(
                    transactions.totalsByCategory(LocalDate.of(2000, 1, 1), LocalDate.now()));
            case "list_statements" -> json.writeValueAsString(statements.listOrderedByMonth());
            case "list_members" -> json.writeValueAsString(members.list());
            default -> throw new IllegalArgumentException("Função desconhecida: " + name);
        };
    }

    private YearMonth requiredMonth(JsonNode args) {
        String month = args.path("month").asText("");
        if (month.isBlank()) {
            throw new IllegalArgumentException("month é obrigatório (YYYY-MM)");
        }
        return YearMonth.parse(month.strip());
    }

    private int parseMonths(String raw) {
        try {
            return Math.max(1, Math.min(12, Integer.parseInt(raw.strip())));
        } catch (NumberFormatException e) {
            return 6;
        }
    }
}

