import com.fasterxml.jackson.databind.ObjectMapper;
import com.vini.financemonitor.ai.AiClient;
import com.vini.financemonitor.ai.LlmStatementExtractor;
import com.vini.financemonitor.ingestion.pdf.OfficialStatementFigures;
import com.vini.financemonitor.ingestion.pdf.ReconciliationService;
import java.math.BigDecimal;
import java.nio.file.Files;
import java.nio.file.Path;

public class AiExtractTest {
    public static void main(String[] args) throws Exception {
        AiClient ai = new AiClient(
                System.getenv("GEMINI_API_KEY"),
                System.getenv().getOrDefault("APP_AI_MODEL", "gemini-3.6-flash"));
        LlmStatementExtractor extractor = new LlmStatementExtractor(ai, new ObjectMapper());

        byte[] pdf = Files.readAllBytes(Path.of(args[0]));
        long start = System.currentTimeMillis();
        var rows = extractor.extract(pdf);
        long elapsed = System.currentTimeMillis() - start;

        var official = new OfficialStatementFigures(
                new BigDecimal("13217.33"), new BigDecimal("13908.38"),
                new BigDecimal("-13996.71"), new BigDecimal("0.00"), new BigDecimal("13129.00"));
        var result = new ReconciliationService().reconcile(rows, official);

        System.out.println("rows=" + rows.size()
                + " sum=" + result.expensesSum()
                + " diff=" + result.expensesDiff()
                + " sumMatches=" + result.sumMatches()
                + " accounting=" + result.accountingMatches()
                + " gate=" + result.passesGate()
                + " tempo=" + (elapsed / 1000.0) + "s");
    }
}

