/**
 * POST models/{model}:generateContent com o corpo dado; retorna o JSON da resposta.
 * 429/503 (pico de demanda do Google) são retentados com backoff antes de falhar.
 */
public JsonNode generateContent(ObjectNode body) {
    int[] backoffSeconds = {0, 3, 8, 15};
    RestClientResponseException last = null;
    for (int attempt = 0; attempt < backoffSeconds.length; attempt++) {
        if (backoffSeconds[attempt] > 0) {
            try {
                Thread.sleep(backoffSeconds[attempt] * 1000L);
            } catch (InterruptedException e) {
                Thread.currentThread().interrupt();
                throw new IllegalStateException("Chamada à IA interrompida.", e);
            }
        }
        try {
            return rest().post()
                    .uri("/v1beta/models/{model}:generateContent", model)
                    .contentType(MediaType.APPLICATION_JSON)
                    .body(body.toString())
                    .retrieve()
                    .body(JsonNode.class);
        } catch (RestClientResponseException e) {
            int code = e.getStatusCode().value();
            if (code != 429 && code != 503) {
                throw wrap(e);
            }
            last = e;
        }
    }
    throw wrap(last);
}

private IllegalStateException wrap(RestClientResponseException e) {
    String detail = e.getResponseBodyAsString();
    return new IllegalStateException("Gemini retornou " + e.getStatusCode().value()
            + (detail.isBlank() ? "" : ": " + truncate(detail)), e);
}

