/**
 * Tipo de encargo da fatura. Superset do EnumCreditCardAccountsFinanceChargeType
 * do Open Finance Brasil, com a granularidade que a página 1 do Sicredi oferece.
 * Só ROTATIVO_JUROS (e PARCELAMENTO_ROTATIVO) confirmam entrada no rotativo;
 * IOF de compra internacional, anuidade e multa/mora NÃO são rotativo.
 */
public enum ChargeType {
    /** "Encargos rotativos" — juros remuneratórios do crédito rotativo. */
    ROTATIVO_JUROS,
    /** "Encargos saque" — juros de saque com o cartão. */
    SAQUE_JUROS,
    /** "Encargos compras parceladas" — juros de compras parceladas com juros. */
    PARCELAMENTO_COMPRAS,
    /** "Encargos parcelamento de fatura" — custo do parcelamento da fatura (não é rotativo). */
    PARCELAMENTO_FATURA,
    /** "Encargos parcelamento de rotativo" — parcelamento compulsório pós-rotativo (Res. 4.549). */
    PARCELAMENTO_ROTATIVO,
    /** "IOF" do resumo — IOF de financiamento (rotativo/saque), não o de compra internacional. */
    IOF_FINANCIAMENTO,
    /** Multa de 2% por atraso (CDC art. 52 §1º). */
    MULTA,
    /** Juros de mora 1% a.m. por atraso. */
    MORA,
    OUTROS
}

package com.vini.financemonitor.statement;

/**
 * Estado de liquidação de uma fatura. A previsão vem dos pagamentos datados
 * contra o vencimento; a confirmação vem dos encargos da fatura seguinte
 * (o banco é o juiz). Ver Resolução CMN 4.549/2017.
 */
public enum SettlementStatus {
    /** Sem total conhecido, ou vencimento ainda no futuro. */
    EM_ABERTO,
    /** Σ pagamentos com data ≤ vencimento cobriu o total. */
    PAGA_EM_DIA,
    /** Pagamentos até o vencimento < total e a fatura seguinte ainda não confirmou. */
    SUSPEITA_ROTATIVO,
    /** A fatura seguinte trouxe encargos de rotativo — verdade materializada pelo banco. */
    ROTATIVO_CONFIRMADO,
    /** A fatura seguinte trouxe multa/mora sem rotativo (pagou tudo, mas tarde). */
    ATRASO,
    /** Fatura objeto de parcelamento (nunca é rotativo — Res. 4.549 art. 2º §2º). */
    PARCELADA
}

