package com.vini.financemonitor.ingestion.pdf;

import com.vini.financemonitor.statement.ChargeType;
import java.io.IOException;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.apache.pdfbox.Loader;
import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.text.PDFTextStripper;
import org.springframework.stereotype.Component;

/**
 * Extrai da fatura Sicredi o que a página 1 sabe e as transações não contam:
 * o vencimento e o breakdown tipado dos encargos ("Encargos rotativos",
 * "Encargos parcelamento de fatura", IOF de financiamento...). É a base da
 * confirmação bancária do rotativo: encargo rotativo > 0 na fatura M prova
 * que a fatura M-1 entrou no rotativo.
 */
@Component
public class SicrediSummaryParser {

    /** Rótulo impresso -> tipo. Ordem importa: rótulos mais longos primeiro. */
    private static final Map<String, ChargeType> CHARGE_LABELS = buildLabels();

    private static Map<String, ChargeType> buildLabels() {
        Map<String, ChargeType> labels = new LinkedHashMap<>();
        labels.put("Encargos parcelamento de rotativo", ChargeType.PARCELAMENTO_ROTATIVO);
        labels.put("Encargos parcelamento de fatura", ChargeType.PARCELAMENTO_FATURA);
        labels.put("Encargos compras parceladas", ChargeType.PARCELAMENTO_COMPRAS);
        labels.put("Encargos rotativos", ChargeType.ROTATIVO_JUROS);
        labels.put("Encargos saque", ChargeType.SAQUE_JUROS);
        return labels;
    }

    private static final Pattern BR_AMOUNT = Pattern.compile("(-?\\d{1,3}(?:\\.\\d{3})*,\\d{2})");
    private static final Pattern IOF_LINE = Pattern.compile("^IOF\\s+(-?\\d{1,3}(?:\\.\\d{3})*,\\d{2})");
    private static final Pattern DUE_DATE = Pattern.compile("Vencimento\\s+(\\d{2}/\\d{2}/\\d{4})");
    private static final DateTimeFormatter BR_DATE = DateTimeFormatter.ofPattern("dd/MM/yyyy");

    public record ChargeLine(ChargeType type, BigDecimal amount, String label) {
    }

    public record StatementSummary(LocalDate dueDate, List<ChargeLine> charges) {
    }

    public StatementSummary parse(byte[] pdfBytes) {
        try (PDDocument document = Loader.loadPDF(pdfBytes)) {
            PDFTextStripper stripper = new PDFTextStripper();
            stripper.setLineSeparator("\n");
            stripper.setSortByPosition(true);

            stripper.setStartPage(1);
            stripper.setEndPage(1);
            String pageOne = stripper.getText(document);

            LocalDate dueDate = null;
            if (document.getNumberOfPages() > 1) {
                stripper.setStartPage(2);
                stripper.setEndPage(2);
                Matcher due = DUE_DATE.matcher(stripper.getText(document));
                if (due.find()) {
                    dueDate = LocalDate.parse(due.group(1), BR_DATE);
                }
            }

            return new StatementSummary(dueDate, parseCharges(pageOne));
        } catch (IOException e) {
            throw new PdfParseException("Falha ao ler o resumo da fatura", e);
        }
    }

    private List<ChargeLine> parseCharges(String pageOne) {
        List<ChargeLine> charges = new ArrayList<>();
        for (String rawLine : pageOne.split("\n", -1)) {
            String line = rawLine.strip();
            ChargeType matched = null;
            String matchedLabel = null;
            for (Map.Entry<String, ChargeType> entry : CHARGE_LABELS.entrySet()) {
                if (line.startsWith(entry.getKey())) {
                    matched = entry.getValue();
                    matchedLabel = entry.getKey();
                    break;
                }
            }
            BigDecimal amount = null;
            if (matched != null) {
                // O texto da coluna da direita pode grudar depois do valor:
                // o valor do encargo é sempre o PRIMEIRO número após o rótulo.
                Matcher m = BR_AMOUNT.matcher(line.substring(matchedLabel.length()));
                if (m.find()) {
                    amount = toAmount(m.group(1));
                }
            } else {
                Matcher iof = IOF_LINE.matcher(line);
                if (iof.find()) {
                    matched = ChargeType.IOF_FINANCIAMENTO;
                    matchedLabel = "IOF";
                    amount = toAmount(iof.group(1));
                }
            }
            if (matched != null && amount != null && amount.signum() != 0) {
                charges.add(new ChargeLine(matched, amount, matchedLabel));
            }
        }
        return charges;
    }

    private static BigDecimal toAmount(String br) {
        return new BigDecimal(br.replace(".", "").replace(",", "."));
    }
}

package com.vini.financemonitor.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;

/**
 * Regras puras da máquina de estados de liquidação (sem banco, sem Spring).
 *
 * Duas camadas, na ordem de autoridade:
 * 1. CONFIRMAÇÃO BANCÁRIA (fatura seguinte importada): encargo de rotativo prova
 *    rotativo; multa/mora sem rotativo prova atraso; fatura seguinte limpa prova
 *    que foi paga em dia — mesmo que os pagamentos registrados digam outra coisa
 *    (registro incompleto perde para o extrato do banco).
 * 2. PREVISÃO (sem fatura seguinte): soma dos pagamentos com data até o vencimento
 *    contra o total. Pagar em N parcelas antes do vencimento não é rotativo
 *    (Resolução CMN 4.549/2017; juros correm pró-rata a partir do vencimento).
 */
public final class SettlementCalculator {

    private SettlementCalculator() {
    }

    /** Camada 1: classifica a fatura M-1 a partir dos encargos da fatura M. */
    public static SettlementStatus fromBankCharges(List<StatementCharge> nextStatementCharges) {
        boolean revolving = false;
        boolean lateFees = false;
        for (StatementCharge charge : nextStatementCharges) {
            if (charge.getAmount() == null || charge.getAmount().signum() <= 0) {
                continue;
            }
            switch (charge.getType()) {
                case ROTATIVO_JUROS, PARCELAMENTO_ROTATIVO -> revolving = true;
                case MULTA, MORA -> lateFees = true;
                default -> {
                    // IOF_FINANCIAMENTO sozinho não confirma (acompanha juros quando é
                    // rotativo); PARCELAMENTO_FATURA/COMPRAS/SAQUE não são rotativo.
                }
            }
        }
        if (revolving) {
            return SettlementStatus.ROTATIVO_CONFIRMADO;
        }
        if (lateFees) {
            return SettlementStatus.ATRASO;
        }
        return SettlementStatus.PAGA_EM_DIA;
    }

    /** Camada 2: previsão pelos pagamentos datados, quando a fatura seguinte não existe. */
    public static SettlementStatus predict(BigDecimal total, LocalDate dueDate,
                                           List<StatementPayment> payments, LocalDate today) {
        if (total == null) {
            return SettlementStatus.EM_ABERTO;
        }
        BigDecimal paidUntilDue = paidUntilDueDate(dueDate, payments);
        if (paidUntilDue.compareTo(total) >= 0) {
            return SettlementStatus.PAGA_EM_DIA;
        }
        if (dueDate != null && !today.isAfter(dueDate)) {
            return SettlementStatus.EM_ABERTO;
        }
        if (payments.isEmpty() && dueDate == null) {
            return SettlementStatus.EM_ABERTO;
        }
        return SettlementStatus.SUSPEITA_ROTATIVO;
    }

    /** Soma dos pagamentos que contam para evitar o rotativo (data ≤ vencimento). */
    public static BigDecimal paidUntilDueDate(LocalDate dueDate, List<StatementPayment> payments) {
        BigDecimal sum = BigDecimal.ZERO;
        for (StatementPayment payment : payments) {
            if (dueDate == null || !payment.getPaidAt().isAfter(dueDate)) {
                sum = sum.add(payment.getAmount());
            }
        }
        return sum;
    }
}

package com.vini.financemonitor.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Optional;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Orquestra a máquina de estados de liquidação: confirmação bancária quando a
 * fatura seguinte existe, previsão pelos pagamentos datados quando não.
 * Ver regras em {@link SettlementCalculator}.
 */
@Service
public class SettlementService {

    private final StatementRepository statements;
    private final StatementPaymentRepository payments;
    private final StatementChargeRepository charges;

    public SettlementService(StatementRepository statements,
                             StatementPaymentRepository payments,
                             StatementChargeRepository charges) {
        this.statements = statements;
        this.payments = payments;
        this.charges = charges;
    }

    /** Recalcula o estado da fatura e os agregados legados (paid_amount, entered_revolving). */
    @Transactional
    public Statement recompute(Statement statement) {
        List<StatementPayment> statementPayments =
                payments.findByStatementIdOrderByPaidAt(statement.getId());

        BigDecimal totalPaid = statementPayments.stream()
                .map(StatementPayment::getAmount)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
        statement.setPaidAmount(statementPayments.isEmpty() ? null : totalPaid);

        SettlementStatus status = nextStatement(statement)
                .map(next -> SettlementCalculator.fromBankCharges(charges.findByStatementId(next.getId())))
                .orElseGet(() -> SettlementCalculator.predict(
                        statement.getTotalAmount(), statement.getDueDate(),
                        statementPayments, LocalDate.now()));

        statement.setSettlementStatus(status);
        statement.setEnteredRevolving(status == SettlementStatus.ROTATIVO_CONFIRMADO);
        return statements.save(statement);
    }

    /** Saldo que ficou (ou ficaria) rodando no rotativo: total − pagamentos até o vencimento. */
    public BigDecimal carriedBalance(Statement statement) {
        if (statement.getTotalAmount() == null) {
            return BigDecimal.ZERO;
        }
        BigDecimal paidUntilDue = SettlementCalculator.paidUntilDueDate(
                statement.getDueDate(),
                payments.findByStatementIdOrderByPaidAt(statement.getId()));
        return statement.getTotalAmount().subtract(paidUntilDue).max(BigDecimal.ZERO);
    }

    /** Custo cobrado pelo banco pelo rotativo da fatura M: encargos de financiamento na fatura M+1. */
    public BigDecimal revolvingCost(Statement statement) {
        return nextStatement(statement)
                .map(next -> charges.findByStatementId(next.getId()).stream()
                        .filter(c -> switch (c.getType()) {
                            case ROTATIVO_JUROS, PARCELAMENTO_ROTATIVO, IOF_FINANCIAMENTO, MULTA, MORA -> true;
                            default -> false;
                        })
                        .map(StatementCharge::getAmount)
                        .reduce(BigDecimal.ZERO, BigDecimal::add))
                .orElse(BigDecimal.ZERO);
    }

    private Optional<Statement> nextStatement(Statement statement) {
        return statements.findByAccountIdAndReferenceMonth(
                statement.getAccountId(), statement.getReferenceMonth().plusMonths(1));
    }
}

