import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Comparator;
import java.util.List;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class StatementService {

    private final StatementRepository statements;
    private final StatementPaymentRepository payments;
    private final SettlementService settlement;

    public StatementService(StatementRepository statements,
                            StatementPaymentRepository payments,
                            SettlementService settlement) {
        this.statements = statements;
        this.payments = payments;
        this.settlement = settlement;
    }

    public List<Statement> listOrderedByMonth() {
        return statements.findAll().stream()
                .sorted(Comparator.comparing(Statement::getReferenceMonth))
                .toList();
    }

    public List<StatementPayment> paymentsOf(Long statementId) {
        return payments.findByStatementIdOrderByPaidAt(statementId);
    }

    public List<StatementPayment> paymentsOf(List<Long> statementIds) {
        return statementIds.isEmpty() ? List.of() : payments.findByStatementIdIn(statementIds);
    }

    /** Adiciona um pagamento datado e recalcula o estado da fatura. */
    @Transactional
    public Statement addPayment(Long statementId, BigDecimal amount, LocalDate paidAt,
                                String mode, String note) {
        Statement statement = require(statementId);
        if (amount == null || amount.signum() <= 0) {
            throw new IllegalArgumentException("Valor do pagamento deve ser positivo.");
        }
        StatementPayment payment = new StatementPayment();
        payment.setStatementId(statement.getId());
        payment.setAmount(amount);
        payment.setPaidAt(paidAt == null ? LocalDate.now() : paidAt);
        payment.setMode(mode);
        payment.setNote(note);
        payments.save(payment);
        return settlement.recompute(statement);
    }

    /** Remove um pagamento e recalcula o estado. */
    @Transactional
    public Statement removePayment(Long statementId, Long paymentId) {
        Statement statement = require(statementId);
        StatementPayment payment = payments.findById(paymentId)
                .orElseThrow(() -> new IllegalArgumentException("Pagamento " + paymentId + " não encontrado."));
        if (!payment.getStatementId().equals(statement.getId())) {
            throw new IllegalArgumentException("Pagamento não pertence a essa fatura.");
        }
        payments.delete(payment);
        return settlement.recompute(statement);
    }

    /**
     * Compatibilidade: registra o pagamento como um único lançamento datado de hoje.
     * Prefira {@link #addPayment} com a data real.
     */
    @Transactional
    public Statement registerPayment(Long id, BigDecimal paidAmount) {
        return addPayment(id, paidAmount, LocalDate.now(), null, null);
    }

    private Statement require(Long id) {
        return statements.findById(id)
                .orElseThrow(() -> new IllegalArgumentException("Fatura " + id + " não encontrada."));
    }
}

