open('statement/CreditHealthService.java', 'w').write('''package com.vini.financemonitor.statement;

import com.vini.financemonitor.account.Account;
import com.vini.financemonitor.account.AccountRepository;
import com.vini.financemonitor.web.dto.CreditHealthResponse;
import com.vini.financemonitor.web.dto.CreditStatementView;
import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.List;
import org.springframework.stereotype.Service;

/**
 * Saúde de crédito / rotativo, com semântica honesta:
 * - "agora" = fatura em SUSPEITA_ROTATIVO (pagamentos até o vencimento não cobriram
 *   o total e a fatura seguinte ainda não deu o veredito);
 * - "histórico" = faturas ROTATIVO_CONFIRMADO/ATRASO com o custo REAL que o banco
 *   cobrou (encargos da fatura seguinte).
 * Juros Sicredi observados: 11,2% a.m. Não é conselho financeiro.
 */
@Service
public class CreditHealthService {

    /** 11,2% a.m. observado no rotativo Sicredi. */
    private static final BigDecimal MONTHLY_RATE = new BigDecimal("0.112");

    private final StatementRepository statements;
    private final AccountRepository accounts;
    private final SettlementService settlement;

    public CreditHealthService(StatementRepository statements,
                               AccountRepository accounts,
                               SettlementService settlement) {
        this.statements = statements;
        this.accounts = accounts;
        this.settlement = settlement;
    }

    public CreditHealthResponse build() {
        List<Statement> ordered = statements.findAll().stream()
                .sorted((a, b) -> a.getReferenceMonth().compareTo(b.getReferenceMonth()))
                .toList();

        List<CreditStatementView> views = new ArrayList<>();
        List<CreditHealthResponse.RevolvingEvent> history = new ArrayList<>();
        boolean inRevolvingNow = false;
        BigDecimal currentCarried = BigDecimal.ZERO;

        for (Statement s : ordered) {
            SettlementStatus status = s.getSettlementStatus() == null
                    ? SettlementStatus.EM_ABERTO : s.getSettlementStatus();
            BigDecimal carried = BigDecimal.ZERO;
            BigDecimal interest1m = BigDecimal.ZERO;
            BigDecimal interest6m = BigDecimal.ZERO;
            BigDecimal cost = BigDecimal.ZERO;

            if (status == SettlementStatus.ROTATIVO_CONFIRMADO
                    || status == SettlementStatus.SUSPEITA_ROTATIVO
                    || status == SettlementStatus.ATRASO) {
                carried = settlement.carriedBalance(s);
            }
            if (status == SettlementStatus.ROTATIVO_CONFIRMADO || status == SettlementStatus.ATRASO) {
                cost = settlement.revolvingCost(s);
                history.add(new CreditHealthResponse.RevolvingEvent(
                        s.getReferenceMonth(), carried, cost, status.name()));
            }
            if (status == SettlementStatus.SUSPEITA_ROTATIVO) {
                inRevolvingNow = true;
                currentCarried = currentCarried.add(carried);
                interest1m = compoundInterest(carried, 1);
                interest6m = compoundInterest(carried, 6);
            }

            views.add(new CreditStatementView(s.getId(), s.getReferenceMonth(), s.getTotalAmount(),
                    s.getPaidAmount(), s.isEnteredRevolving(), status.name(),
                    carried, interest1m, interest6m, cost));
        }

        boolean anyEver = ordered.stream().anyMatch(s ->
                s.getSettlementStatus() == SettlementStatus.ROTATIVO_CONFIRMADO
                        || s.getSettlementStatus() == SettlementStatus.SUSPEITA_ROTATIVO);

        Account account = accounts.findAll().stream().findFirst().orElse(null);
        String name = account != null ? account.getName() : null;
        BigDecimal limit = account != null ? account.getCreditLimit() : null;
        BigDecimal latestTotal = ordered.isEmpty() ? null
                : ordered.get(ordered.size() - 1).getTotalAmount();
        BigDecimal usage = (limit != null && limit.signum() > 0 && latestTotal != null)
                ? latestTotal.divide(limit, 4, RoundingMode.HALF_UP) : null;

        return new CreditHealthResponse(name, limit, latestTotal, usage, MONTHLY_RATE,
                inRevolvingNow, currentCarried, anyEver, history, views);
    }

    /** Juros compostos do saldo a 11,2% a.m. por n meses: saldo * ((1+r)^n - 1). */
    private BigDecimal compoundInterest(BigDecimal balance, int months) {
        BigDecimal factor = BigDecimal.ONE.add(MONTHLY_RATE).pow(months)
                .subtract(BigDecimal.ONE);
        return balance.multiply(factor).setScale(2, RoundingMode.HALF_UP);
    }
}
''')
