package com.vini.financemonitor.statement;

import static org.assertj.core.api.Assertions.assertThat;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import org.junit.jupiter.api.Test;

/**
 * Cenários da máquina de estados de liquidação. O caso que motivou tudo:
 * pagar em 2 partes ANTES do vencimento não é rotativo; a 2ª parte DEPOIS
 * do vencimento é (Resolução CMN 4.549/2017, juros pró-rata do vencimento).
 */
class SettlementCalculatorTest {

    private static final LocalDate DUE = LocalDate.of(2026, 5, 10);
    private static final BigDecimal TOTAL = new BigDecimal("12459.15");

    @Test
    void doisPagamentosAntesDoVencimentoSomandoTotal_ehPagaEmDia() {
        List<StatementPayment> payments = List.of(
                payment("9866.67", DUE.minusDays(5)),
                payment("2592.48", DUE));
        assertThat(SettlementCalculator.predict(TOTAL, DUE, payments, DUE.plusDays(30)))
                .isEqualTo(SettlementStatus.PAGA_EM_DIA);
    }

    @Test
    void segundoPagamentoDepoisDoVencimento_ehSuspeitaDeRotativo() {
        List<StatementPayment> payments = List.of(
                payment("9866.67", DUE),
                payment("2592.48", DUE.plusDays(16)));
        assertThat(SettlementCalculator.predict(TOTAL, DUE, payments, DUE.plusDays(30)))
                .isEqualTo(SettlementStatus.SUSPEITA_ROTATIVO);
    }

    @Test
    void pagamentoParcialAntesDoVencimento_aindaDentroDoPrazo_ehEmAberto() {
        List<StatementPayment> payments = List.of(payment("9866.67", DUE.minusDays(2)));
        assertThat(SettlementCalculator.predict(TOTAL, DUE, payments, DUE.minusDays(1)))
                .isEqualTo(SettlementStatus.EM_ABERTO);
    }

    @Test
    void semTotalConhecido_ehEmAberto() {
        assertThat(SettlementCalculator.predict(null, DUE, List.of(), DUE.plusDays(30)))
                .isEqualTo(SettlementStatus.EM_ABERTO);
    }

    @Test
    void confirmacaoBancaria_jurosRotativos_confirmaRotativo() {
        List<StatementCharge> charges = List.of(
                charge(ChargeType.ROTATIVO_JUROS, "300.03"),
                charge(ChargeType.IOF_FINANCIAMENTO, "6.59"));
        assertThat(SettlementCalculator.fromBankCharges(charges))
                .isEqualTo(SettlementStatus.ROTATIVO_CONFIRMADO);
    }

    @Test
    void confirmacaoBancaria_soMultaEMora_ehAtraso() {
        List<StatementCharge> charges = List.of(
                charge(ChargeType.MULTA, "24.92"),
                charge(ChargeType.MORA, "4.15"));
        assertThat(SettlementCalculator.fromBankCharges(charges))
                .isEqualTo(SettlementStatus.ATRASO);
    }

    @Test
    void confirmacaoBancaria_faturaSeguinteLimpa_rebaixaParaPagaEmDia() {
        assertThat(SettlementCalculator.fromBankCharges(List.of()))
                .isEqualTo(SettlementStatus.PAGA_EM_DIA);
    }

    @Test
    void confirmacaoBancaria_encargosQueNaoSaoRotativo_naoConfirmam() {
        List<StatementCharge> charges = List.of(
                charge(ChargeType.PARCELAMENTO_FATURA, "150.00"),
                charge(ChargeType.IOF_FINANCIAMENTO, "2.10"));
        assertThat(SettlementCalculator.fromBankCharges(charges))
                .isEqualTo(SettlementStatus.PAGA_EM_DIA);
    }

    @Test
    void pagamentosDepoisDoVencimentoNaoContamParaEvitarRotativo() {
        List<StatementPayment> payments = List.of(
                payment("9866.67", DUE),
                payment("2592.48", DUE.plusDays(16)));
        assertThat(SettlementCalculator.paidUntilDueDate(DUE, payments))
                .isEqualByComparingTo("9866.67");
    }

    private static StatementPayment payment(String amount, LocalDate paidAt) {
        StatementPayment payment = new StatementPayment();
        payment.setAmount(new BigDecimal(amount));
        payment.setPaidAt(paidAt);
        return payment;
    }

    private static StatementCharge charge(ChargeType type, String amount) {
        StatementCharge charge = new StatementCharge();
        charge.setType(type);
        charge.setAmount(new BigDecimal(amount));
        return charge;
    }
}

package com.vini.financemonitor.ingestion.pdf;

import static org.assertj.core.api.Assertions.assertThat;

import com.vini.financemonitor.statement.ChargeType;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.LocalDate;
import org.junit.jupiter.api.Assumptions;
import org.junit.jupiter.api.Test;

/**
 * Valida o parser do resumo (página 1) contra os PDFs reais em faturas/:
 * vencimento e breakdown tipado dos encargos. Pulado se os PDFs não existirem.
 * Execução: {@code mvn test -Dtest=SicrediSummaryParserIT}.
 */
class SicrediSummaryParserIT {

    private final SicrediSummaryParser parser = new SicrediSummaryParser();

    @Test
    void junhoTemEncargosDeRotativoEIof() throws Exception {
        Path pdf = Path.of("faturas", "2026-06.pdf");
        Assumptions.assumeTrue(Files.isReadable(pdf));

        SicrediSummaryParser.StatementSummary summary = parser.parse(Files.readAllBytes(pdf));

        assertThat(summary.dueDate()).isEqualTo(LocalDate.of(2026, 6, 10));
        assertThat(summary.charges())
                .extracting(SicrediSummaryParser.ChargeLine::type)
                .containsExactlyInAnyOrder(ChargeType.ROTATIVO_JUROS, ChargeType.IOF_FINANCIAMENTO);
        assertThat(summary.charges().stream()
                .filter(c -> c.type() == ChargeType.ROTATIVO_JUROS)
                .findFirst().orElseThrow().amount())
                .isEqualByComparingTo("300.03");
        assertThat(summary.charges().stream()
                .filter(c -> c.type() == ChargeType.IOF_FINANCIAMENTO)
                .findFirst().orElseThrow().amount())
                .isEqualByComparingTo("6.59");
    }

    @Test
    void abrilNaoTemEncargos() throws Exception {
        Path pdf = Path.of("faturas", "2026-04.pdf");
        Assumptions.assumeTrue(Files.isReadable(pdf));

        SicrediSummaryParser.StatementSummary summary = parser.parse(Files.readAllBytes(pdf));

        assertThat(summary.dueDate()).isEqualTo(LocalDate.of(2026, 4, 10));
        assertThat(summary.charges()).isEmpty();
    }
}

