import type { SettlementStatus, Statement } from '@/types/api'

export const Route = createFileRoute('/faturas')({
  component: FaturasRoute,
})

const STATUS_LABEL: Record<string, { label: string; tone: PillTone }> = {
  EM_ABERTO: { label: 'em aberto', tone: 'muted' },
  PAGA_EM_DIA: { label: 'paga em dia', tone: 'ok' },
  SUSPEITA_ROTATIVO: { label: 'suspeita de rotativo', tone: 'warn' },
  ROTATIVO_CONFIRMADO: { label: 'rotativo', tone: 'danger' },
  ATRASO: { label: 'atraso', tone: 'warn' },
  PARCELADA: { label: 'parcelada', tone: 'neutral' },
}

function statusPill(status: SettlementStatus) {
  const meta = STATUS_LABEL[status] ?? { label: status.toLowerCase(), tone: 'neutral' as PillTone }
  return <Pill tone={meta.tone}>{meta.label}</Pill>
}

function brDate(iso: string | null): string {
  if (!iso) return '—'
  return `${iso.slice(8, 10)}/${iso.slice(5, 7)}/${iso.slice(0, 4)}`
}

function FaturasRoute() {
  const [payingId, setPayingId] = useState<number | null>(null)

  const list = useQuery({
    queryKey: ['statements'],
    queryFn: () => statements.list(),
  })

  const items = list.data ?? []
  const paying = items.find((s) => s.id === payingId) ?? null

  return (
    <>
      <PageHeader
        eyebrow="crédito"
        title="Faturas"
        subtitle="Pagamentos com data valem contra o vencimento; a fatura seguinte confirma o rotativo"
      />

      <div className="mt-6">
        {list.isLoading ? (
          <Skeleton className="h-40 w-full" />
        ) : items.length === 0 ? (
          <EmptyState
            icon={CreditCard}
            title="Nenhuma fatura importada"
            description="Importe um PDF da Sicredi em /importar para começar."
          />
        ) : (
          <div className="rounded-lg border border-border bg-surface">
            <Table>
              <TableHeader>
                <TableRow>
                  <TableHead>Mês</TableHead>
                  <TableHead>Vencimento</TableHead>
                  <TableHead>Status</TableHead>
                  <TableHead className="text-right">Total</TableHead>
                  <TableHead className="text-right">Pago</TableHead>
                  <TableHead className="text-right">Até o venc.</TableHead>
                  <TableHead className="text-right">Ações</TableHead>
                </TableRow>
              </TableHeader>
              <TableBody>
                {items.map((s) => (
                  <StatementRow key={s.id} s={s} onManage={() => setPayingId(s.id)} />
                ))}
              </TableBody>
            </Table>
          </div>
        )}
      </div>

      <PaymentsDialog statement={paying} onClose={() => setPayingId(null)} />
    </>
  )
}

function paidUntilDue(s: Statement): number {
  return s.payments
    .filter((p) => !s.dueDate || p.paidAt <= s.dueDate)
    .reduce((acc, p) => acc + Number(p.amount), 0)
}

function StatementRow({ s, onManage }: { s: Statement; onManage: () => void }) {
  const paid = Number(s.paidAmount ?? 0)
  const untilDue = paidUntilDue(s)
  return (
    <TableRow>
      <TableCell>{monthLabel(s.referenceMonth)}</TableCell>
      <TableCell className="font-mono text-xs tabular-nums text-muted">
        {brDate(s.dueDate)}
      </TableCell>
      <TableCell>{statusPill(s.settlementStatus)}</TableCell>
      <TableCell className="text-right font-mono tabular-nums">
        {brlMoney(s.totalAmount)}
      </TableCell>
      <TableCell className="text-right font-mono tabular-nums">
        {brlMoney(paid)}
        {s.payments.length > 1 && (
          <span className="ml-1 text-[10px] text-muted">×{s.payments.length}</span>
        )}
      </TableCell>
      <TableCell className="text-right font-mono tabular-nums text-muted">
        {brlMoney(untilDue)}
      </TableCell>
      <TableCell className="text-right">
        <Button size="sm" variant={paid > 0 ? 'ghost' : 'default'} onClick={onManage}>
          Pagamentos
        </Button>
      </TableCell>
    </TableRow>
  )
}

function PaymentsDialog({
  statement,
  onClose,
}: {
  statement: Statement | null
  onClose: () => void
}) {
  const qc = useQueryClient()
  const [amount, setAmount] = useState('')
  const [paidAt, setPaidAt] = useState('')
  const [error, setError] = useState<string | null>(null)

  useEffect(() => {
    if (statement) {
      const remaining = Math.max(0, statement.totalAmount - Number(statement.paidAmount ?? 0))
      setAmount(remaining > 0 ? remaining.toFixed(2) : '')
      setPaidAt(new Date().toISOString().slice(0, 10))
      setError(null)
    }
  }, [statement])

  function invalidate() {
    qc.invalidateQueries({ queryKey: ['statements'] })
    qc.invalidateQueries({ queryKey: ['credit-health'] })
  }

  const add = useMutation({
    mutationFn: ({ id, value, date }: { id: number; value: number; date: string }) =>
      statements.addPayment(id, { amount: value, paidAt: date }),
    onSuccess: (data) => {
      toast.success(
        data.settlementStatus === 'SUSPEITA_ROTATIVO'
          ? 'Pagamento registrado — atenção: até o vencimento não cobriu o total'
          : 'Pagamento registrado',
      )
      invalidate()
    },
    onError: (err: ApiError) =>
      toast.error('Falha ao registrar pagamento', { description: err.message }),
  })

  const remove = useMutation({
    mutationFn: ({ id, paymentId }: { id: number; paymentId: number }) =>
      statements.removePayment(id, paymentId),
    onSuccess: () => {
      toast.success('Pagamento removido')
      invalidate()
    },
    onError: (err: ApiError) =>
      toast.error('Falha ao remover', { description: err.message }),
  })

  function submit(e: React.FormEvent) {
    e.preventDefault()
    setError(null)
    if (!statement) return
    const value = Number(amount.replace(',', '.'))
    if (!Number.isFinite(value) || value <= 0) {
      setError('Informe um valor positivo.')
      return
    }
    if (!paidAt) {
      setError('Informe a data do pagamento.')
      return
    }
    add.mutate({ id: statement.id, value, date: paidAt })
  }

  return (
    <Dialog open={!!statement} onOpenChange={(open) => !open && onClose()}>
      <DialogContent>
        <DialogHeader>
          <DialogTitle>Pagamentos da fatura</DialogTitle>
          <DialogDescription>
            {statement
              ? `${monthLabel(statement.referenceMonth)} — total ${brlMoney(statement.totalAmount)} · vencimento ${brDate(statement.dueDate)}`
              : ''}
          </DialogDescription>
        </DialogHeader>

        {statement && statement.payments.length > 0 && (
          <ul className="divide-y divide-border rounded-md border border-border bg-panel">
            {statement.payments.map((p) => (
              <li key={p.id} className="flex items-center justify-between gap-3 px-3 py-2">
                <span className="font-mono text-xs tabular-nums text-muted">
                  {brDate(p.paidAt)}
                  {statement.dueDate && p.paidAt > statement.dueDate && (
                    <span className="ml-2 text-warn">após o venc.</span>
                  )}
                </span>
                <span className="flex items-center gap-2">
                  <span className="font-mono text-sm tabular-nums text-text">
                    {brlMoney(p.amount)}
                  </span>
                  <button
                    type="button"
                    title="Remover pagamento"
                    className="text-muted transition-colors hover:text-danger"
                    onClick={() =>
                      remove.mutate({ id: statement.id, paymentId: p.id })
                    }
                    disabled={remove.isPending}
                  >
                    <Trash2 className="h-3.5 w-3.5" />
                  </button>
                </span>
              </li>
            ))}
          </ul>
        )}

        <form onSubmit={submit} className="space-y-4">
          <div className="grid grid-cols-2 gap-3">
            <Field
              label="Valor (BRL)"
              htmlFor="pay-amount"
              required
              hint="Pagar em partes antes do vencimento não gera rotativo."
            >
              <Input
                id="pay-amount"
                inputMode="decimal"
                value={amount}
                onChange={(e) => setAmount(e.target.value)}
                placeholder="0,00"
                autoFocus
              />
            </Field>
            <Field label="Data do pagamento" htmlFor="pay-date" required>
              <Input
                id="pay-date"
                type="date"
                value={paidAt}
                onChange={(e) => setPaidAt(e.target.value)}
              />
            </Field>
          </div>
          {error && (
            <p className="text-sm text-danger" role="alert">
              {error}
            </p>
          )}
          <div className="flex justify-end gap-2">
            <Button type="button" variant="ghost" onClick={onClose} disabled={add.isPending}>
              Fechar
            </Button>
            <Button type="submit" disabled={add.isPending}>
              Adicionar pagamento
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  )
}

import { brlMoney, monthLabel, pct } from '@/lib/format'
import { cn } from '@/lib/utils'
import type { CreditHealthResponse } from '@/types/api'

import { Eyebrow, Num, Panel } from './Panel'

interface CreditHealthPanelProps {
  data: CreditHealthResponse
}

const STATEMENT_PILL: Record<string, { label: string; className: string }> = {
  ROTATIVO_CONFIRMADO: {
    label: 'rotativo',
    className: 'border-danger/40 bg-danger/10 text-danger',
  },
  SUSPEITA_ROTATIVO: {
    label: 'suspeita',
    className: 'border-warn/40 bg-warn/10 text-warn',
  },
  ATRASO: { label: 'atraso', className: 'border-warn/40 bg-warn/10 text-warn' },
  PAGA_EM_DIA: { label: 'paga em dia', className: 'border-ok/40 bg-ok/10 text-ok' },
  PARCELADA: { label: 'parcelada', className: 'border-border bg-panel text-muted' },
  EM_ABERTO: { label: 'em aberto', className: 'border-border bg-panel text-muted' },
}

export function CreditHealthPanel({ data }: CreditHealthPanelProps) {
  if (!data.statements || data.statements.length === 0) {
    return (
      <Panel eyebrow="saúde de crédito" title={data.accountName ?? 'Cartão'}>
        <p className="text-sm text-muted">Sem faturas importadas ainda.</p>
      </Panel>
    )
  }

  const statusPill = data.inRevolvingNow ? (
    <span className="whitespace-nowrap rounded-full border border-danger/40 bg-danger/10 px-2.5 py-0.5 font-mono text-[10px] uppercase tracking-[0.18em] text-danger">
      rotativo agora
    </span>
  ) : (
    <span className="whitespace-nowrap rounded-full border border-ok/40 bg-ok/10 px-2.5 py-0.5 font-mono text-[10px] uppercase tracking-[0.18em] text-ok">
      em dia
    </span>
  )

  const limitPct = data.limitUsagePercent
  const limitTone =
    limitPct == null
      ? 'neutral'
      : limitPct >= 0.7
        ? 'danger'
        : limitPct >= 0.3
          ? 'warn'
          : 'ok'
  const limitBarColor =
    limitTone === 'danger'
      ? 'bg-danger'
      : limitTone === 'warn'
        ? 'bg-warn'
        : limitTone === 'ok'
          ? 'bg-ok'
          : 'bg-muted'

  const recent = data.statements.slice(-3).reverse()
  const suspect = data.statements.find((s) => s.settlementStatus === 'SUSPEITA_ROTATIVO')

  return (
    <Panel
      eyebrow="saúde de crédito"
      title={data.accountName ?? 'Cartão'}
      actions={statusPill}
    >
      <div className="flex flex-col gap-5">
        <div>
          <Eyebrow>rotativo agora</Eyebrow>
          {data.inRevolvingNow ? (
            <>
              <Num className="mt-1 block text-2xl text-danger">
                {brlMoney(data.currentCarriedBalance)}
              </Num>
              {suspect && (
                <p className="mt-1 text-[11px] text-muted">
                  fatura de {monthLabel(suspect.referenceMonth)} sem cobertura até o
                  vencimento · custo projetado 1m{' '}
                  <Num className="text-warn">{brlMoney(suspect.projectedInterest1m)}</Num>
                </p>
              )}
            </>
          ) : (
            <>
              <Num className="mt-1 block text-2xl text-ok">Em dia</Num>
              <p className="mt-1 text-[11px] text-muted">
                nenhum saldo rodando no rotativo hoje
              </p>
            </>
          )}
        </div>

        {data.history.length > 0 && (
          <div>
            <Eyebrow>histórico de rotativo</Eyebrow>
            <ul className="mt-2 divide-y divide-border">
              {data.history.map((event) => (
                <li key={event.referenceMonth} className="py-2 text-xs">
                  <div className="flex items-center justify-between gap-3">
                    <Num className="text-text">{monthLabel(event.referenceMonth)}</Num>
                    <span className="text-muted">
                      levou <Num className="text-text">{brlMoney(event.carriedBalance)}</Num>{' '}
                      ao rotativo
                    </span>
                    <span className="whitespace-nowrap text-muted">
                      custou <Num className="text-danger">{brlMoney(event.costCharged)}</Num>
                    </span>
                  </div>
                </li>
              ))}
            </ul>
            <p className="mt-1 text-[11px] text-muted">
              custo real cobrado pelo banco na fatura seguinte · já quitado
            </p>
          </div>
        )}

        <div>
          <div className="flex items-baseline justify-between">
            <Eyebrow>uso de limite</Eyebrow>
            <Num className="text-xs">
              {limitPct == null ? '—' : pct(limitPct)}
            </Num>
          </div>
          <div className="mt-2 h-2 w-full overflow-hidden rounded-full bg-panel">
            <div
              className={cn('h-full transition-all duration-700', limitBarColor)}
              style={{
                width: `${Math.min(100, Math.max(0, (limitPct ?? 0) * 100))}%`,
              }}
            />
          </div>
          {data.creditLimit != null && (
            <p className="mt-1 text-[11px] text-muted">
              limite {brlMoney(data.creditLimit)}
            </p>
          )}
        </div>

        <div>
          <div className="flex items-baseline justify-between">
            <Eyebrow>últimas faturas</Eyebrow>
            <span className="font-mono text-[10px] text-muted">
              juros {pct(data.monthlyRevolvingRate)}/mês
            </span>
          </div>
          <ul className="mt-2 divide-y divide-border">
            {recent.map((s) => {
              const pill = STATEMENT_PILL[s.settlementStatus] ?? STATEMENT_PILL.EM_ABERTO
              return (
                <li
                  key={s.id}
                  className="flex items-center justify-between gap-3 py-2 text-xs"
                >
                  <Num className="text-text">{monthLabel(s.referenceMonth)}</Num>
                  <div className="flex flex-1 items-baseline justify-end gap-3">
                    <Num className="text-muted">{brlMoney(s.total)}</Num>
                    <span
                      className={cn(
                        'whitespace-nowrap rounded-full border px-2 py-0.5 font-mono text-[9px] uppercase tracking-[0.18em]',
                        pill.className,
                      )}
                    >
                      {pill.label}
                    </span>
                  </div>
                </li>
              )
            })}
          </ul>
        </div>
      </div>
    </Panel>
  )
}

