package com.vini.financemonitor.ai;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.vini.financemonitor.web.dto.AssistantConversationView;
import com.vini.financemonitor.web.dto.AssistantMessageView;
import com.vini.financemonitor.web.dto.AssistantReply;
import com.vini.financemonitor.web.dto.AssistantSendResponse;
import java.time.OffsetDateTime;
import java.util.Arrays;
import java.util.List;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Conversas persistidas do assistente (histórico estilo ChatGPT). A chamada à
 * IA acontece fora de transação (pode levar dezenas de segundos); cada escrita
 * no banco é curta e independente.
 */
@Service
public class AssistantConversationService {

    private static final Logger log = LoggerFactory.getLogger(AssistantConversationService.class);
    private static final int TITLE_MAX = 60;

    private final AssistantService assistant;
    private final AiClient ai;
    private final ObjectMapper json;
    private final AssistantConversationRepository conversations;
    private final AssistantChatMessageRepository messages;

    public AssistantConversationService(AssistantService assistant,
                                        AiClient ai,
                                        ObjectMapper json,
                                        AssistantConversationRepository conversations,
                                        AssistantChatMessageRepository messages) {
        this.assistant = assistant;
        this.ai = ai;
        this.json = json;
        this.conversations = conversations;
        this.messages = messages;
    }

    public List<AssistantConversationView> list() {
        return conversations.findAllByOrderByUpdatedAtDesc().stream()
                .map(c -> new AssistantConversationView(c.getId(), c.getTitle(), c.getUpdatedAt()))
                .toList();
    }

    public List<AssistantMessageView> history(Long conversationId) {
        requireConversation(conversationId);
        return messages.findByConversationIdOrderByIdAsc(conversationId).stream()
                .map(this::toView)
                .toList();
    }

    public AssistantSendResponse send(Long conversationId, String content) {
        AssistantConversation conversation = conversationId == null
                ? conversations.save(new AssistantConversation())
                : requireConversation(conversationId);

        List<AssistantChatMessage> previous =
                messages.findByConversationIdOrderByIdAsc(conversation.getId());

        List<com.vini.financemonitor.web.dto.AssistantMessage> chatInput = new java.util.ArrayList<>();
        for (AssistantChatMessage m : previous) {
            chatInput.add(new com.vini.financemonitor.web.dto.AssistantMessage(m.getRole(), m.getContent()));
        }
        chatInput.add(new com.vini.financemonitor.web.dto.AssistantMessage("user", content));

        AssistantReply reply = assistant.chat(chatInput);

        AssistantChatMessage userMessage = new AssistantChatMessage();
        userMessage.setConversationId(conversation.getId());
        userMessage.setRole("user");
        userMessage.setContent(content);
        messages.save(userMessage);

        AssistantChatMessage assistantMessage = new AssistantChatMessage();
        assistantMessage.setConversationId(conversation.getId());
        assistantMessage.setRole("assistant");
        assistantMessage.setContent(reply.reply());
        assistantMessage.setToolsUsed(reply.toolsUsed().isEmpty()
                ? null
                : String.join(",", reply.toolsUsed()));
        messages.save(assistantMessage);

        if (conversation.getTitle() == null) {
            conversation.setTitle(generateTitle(content));
        }
        conversation.setUpdatedAt(OffsetDateTime.now());
        conversations.save(conversation);

        return new AssistantSendResponse(conversation.getId(), conversation.getTitle(),
                toView(assistantMessage), reply.model());
    }

    public AssistantConversationView rename(Long conversationId, String title) {
        AssistantConversation conversation = requireConversation(conversationId);
        conversation.setTitle(title.strip());
        conversation.setUpdatedAt(OffsetDateTime.now());
        conversations.save(conversation);
        return new AssistantConversationView(conversation.getId(), conversation.getTitle(),
                conversation.getUpdatedAt());
    }

    @Transactional
    public void delete(Long conversationId) {
        requireConversation(conversationId);
        messages.deleteByConversationId(conversationId);
        conversations.deleteById(conversationId);
    }

    /**
     * Título curto gerado pela IA a partir da primeira pergunta; se a chamada
     * falhar, cai para o início da própria pergunta.
     */
    private String generateTitle(String firstQuestion) {
        try {
            ObjectNode body = json.createObjectNode();
            body.putArray("contents").addObject()
                    .put("role", "user")
                    .putArray("parts").addObject()
                    .put("text", "Resuma a pergunta abaixo num título de conversa em português, "
                            + "com no máximo 5 palavras, sem aspas e sem ponto final. "
                            + "Responda só o título.\n\nPergunta: " + firstQuestion);
            body.putObject("generationConfig").put("maxOutputTokens", 512);
            JsonNode response = ai.generateContent(body);
            StringBuilder text = new StringBuilder();
            for (JsonNode part : response.path("candidates").path(0).path("content").path("parts")) {
                text.append(part.path("text").asText(""));
            }
            String title = text.toString().replaceAll("[\"\n\r]", " ").strip();
            if (!title.isBlank()) {
                return truncate(title);
            }
        } catch (Exception e) {
            log.warn("Falha ao gerar título da conversa; usando fallback: {}", e.getMessage());
        }
        return truncate(firstQuestion.strip());
    }

    private String truncate(String value) {
        return value.length() <= TITLE_MAX ? value : value.substring(0, TITLE_MAX - 1).strip() + "…";
    }

    private AssistantMessageView toView(AssistantChatMessage m) {
        List<String> tools = m.getToolsUsed() == null || m.getToolsUsed().isBlank()
                ? List.of()
                : Arrays.asList(m.getToolsUsed().split(","));
        return new AssistantMessageView(m.getId(), m.getRole(), m.getContent(), tools, m.getCreatedAt());
    }

    private AssistantConversation requireConversation(Long id) {
        return conversations.findById(id)
                .orElseThrow(() -> new IllegalArgumentException("Conversa não encontrada: " + id));
    }
}

package com.vini.financemonitor.web;

import com.vini.financemonitor.ai.AssistantConversationService;
import com.vini.financemonitor.ai.AssistantService;
import com.vini.financemonitor.web.dto.AssistantConversationView;
import com.vini.financemonitor.web.dto.AssistantMessageView;
import com.vini.financemonitor.web.dto.AssistantRenameRequest;
import com.vini.financemonitor.web.dto.AssistantSendRequest;
import com.vini.financemonitor.web.dto.AssistantSendResponse;
import jakarta.validation.Valid;
import java.util.List;
import java.util.Map;
import org.springframework.web.bind.annotation.DeleteMapping;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PatchMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** Assistente do casal: chat com histórico persistido e acesso (somente leitura) aos dados. */
@RestController
@RequestMapping("/api/assistant")
public class AssistantController {

    private final AssistantService assistant;
    private final AssistantConversationService conversations;

    public AssistantController(AssistantService assistant,
                               AssistantConversationService conversations) {
        this.assistant = assistant;
        this.conversations = conversations;
    }

    @GetMapping("/status")
    public Map<String, Object> status() {
        return Map.of("enabled", assistant.enabled(), "model", assistant.model());
    }

    @GetMapping("/conversations")
    public List<AssistantConversationView> conversations() {
        return conversations.list();
    }

    @GetMapping("/conversations/{id}/messages")
    public List<AssistantMessageView> messages(@PathVariable Long id) {
        return conversations.history(id);
    }

    @PatchMapping("/conversations/{id}")
    public AssistantConversationView rename(@PathVariable Long id,
                                            @Valid @RequestBody AssistantRenameRequest request) {
        return conversations.rename(id, request.title());
    }

    @DeleteMapping("/conversations/{id}")
    public void delete(@PathVariable Long id) {
        conversations.delete(id);
    }

    @PostMapping("/chat")
    public AssistantSendResponse chat(@Valid @RequestBody AssistantSendRequest request) {
        if (!assistant.enabled()) {
            throw new IllegalStateException(
                    "IA não configurada: defina GEMINI_API_KEY no ambiente da API.");
        }
        return conversations.send(request.conversationId(), request.content());
    }
}

