import ReactMarkdown from 'react-markdown'
import remarkGfm from 'remark-gfm'

import { cn } from '@/lib/utils'

/**
 * Markdown (GFM) do assistente no tema Cockpit: tabelas densas com números em
 * mono/tabular, listas compactas, sem tipografia de "documento".
 */
export function Markdown({ content, className }: { content: string; className?: string }) {
  return (
    <div className={cn('space-y-2 text-sm leading-relaxed text-text', className)}>
      <ReactMarkdown
        remarkPlugins={[remarkGfm]}
        components={{
          p: ({ children }) => <p>{children}</p>,
          strong: ({ children }) => (
            <strong className="font-semibold text-text">{children}</strong>
          ),
          em: ({ children }) => <em className="italic">{children}</em>,
          a: ({ children, href }) => (
            <a
              href={href}
              target="_blank"
              rel="noreferrer"
              className="text-ok underline decoration-ok/40 underline-offset-2 hover:decoration-ok"
            >
              {children}
            </a>
          ),
          ul: ({ children }) => (
            <ul className="list-disc space-y-1 pl-5 marker:text-muted">{children}</ul>
          ),
          ol: ({ children }) => (
            <ol className="list-decimal space-y-1 pl-5 marker:text-muted">{children}</ol>
          ),
          li: ({ children }) => <li className="[&>p]:inline">{children}</li>,
          h1: ({ children }) => (
            <h3 className="pt-2 text-sm font-semibold text-text">{children}</h3>
          ),
          h2: ({ children }) => (
            <h3 className="pt-2 text-sm font-semibold text-text">{children}</h3>
          ),
          h3: ({ children }) => (
            <h4 className="pt-2 text-sm font-semibold text-text">{children}</h4>
          ),
          blockquote: ({ children }) => (
            <blockquote className="border-l-2 border-accent/50 pl-3 text-muted">
              {children}
            </blockquote>
          ),
          hr: () => <hr className="border-border" />,
          code: ({ children, className: codeClass }) => {
            const isBlock = codeClass?.includes('language-')
            if (isBlock) {
              return <code className="font-mono text-xs">{children}</code>
            }
            return (
              <code className="rounded bg-panel px-1 py-0.5 font-mono text-[0.85em] text-text">
                {children}
              </code>
            )
          },
          pre: ({ children }) => (
            <pre className="overflow-x-auto rounded-md border border-border bg-panel p-3">
              {children}
            </pre>
          ),
          table: ({ children }) => (
            <div className="overflow-x-auto rounded-md border border-border">
              <table className="w-full text-sm">{children}</table>
            </div>
          ),
          thead: ({ children }) => <thead className="bg-panel">{children}</thead>,
          th: ({ children }) => (
            <th className="border-b border-border px-3 py-1.5 text-left font-mono text-[10px] uppercase tracking-[0.14em] text-muted [&:not(:first-child)]:text-right">
              {children}
            </th>
          ),
          td: ({ children }) => (
            <td className="border-b border-border/60 px-3 py-1.5 align-top [&:not(:first-child)]:text-right [&:not(:first-child)]:font-mono [&:not(:first-child)]:tabular-nums">
              {children}
            </td>
          ),
          tr: ({ children }) => <tr className="last:[&>td]:border-b-0">{children}</tr>,
        }}
      >
        {content}
      </ReactMarkdown>
    </div>
  )
}

import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { createFileRoute } from '@tanstack/react-router'
import {
  ArrowDown,
  ArrowUp,
  Check,
  Copy,
  KeyRound,
  MessageSquare,
  Pencil,
  Plus,
  Sparkles,
  Trash2,
  X,
} from 'lucide-react'
import { useEffect, useRef, useState } from 'react'
import { toast } from 'sonner'

import { Markdown } from '@/components/assistant/Markdown'
import { Pill } from '@/components/lists/Pill'
import { PageHeader } from '@/components/shell/PageHeader'
import { Skeleton } from '@/components/ui/skeleton'
import { ApiError, assistant } from '@/lib/api'
import { cn } from '@/lib/utils'
import type { AssistantMessage } from '@/types/api'

export const Route = createFileRoute('/assistente')({
  component: AssistenteRoute,
})

const TOOL_LABELS: Record<string, string> = {
  get_projection: 'projeção',
  get_subscriptions_weight: 'assinaturas',
  get_credit_health: 'saúde de crédito',
  get_couple_summary: 'casal',
  get_month_transactions: 'transações',
  get_category_totals: 'categorias',
  list_statements: 'faturas',
  list_members: 'membros',
}

const SUGGESTIONS = [
  'Como está nosso comprometimento para os próximos meses?',
  'Quais assinaturas estão redundantes ou caras?',
  'Quanto cada um gastou na fatura de agosto?',
  'Entramos no rotativo em algum mês? Quanto custou?',
  'Compare os gastos de mercado entre os últimos meses.',
]

function relativeTime(iso: string): string {
  const date = new Date(iso)
  const diffMs = Date.now() - date.getTime()
  const min = Math.floor(diffMs / 60_000)
  if (min < 1) return 'agora'
  if (min < 60) return `há ${min} min`
  const hours = Math.floor(min / 60)
  if (hours < 24) return `há ${hours} h`
  const days = Math.floor(hours / 24)
  if (days === 1) return 'ontem'
  if (days < 7) return `há ${days} dias`
  return date.toLocaleDateString('pt-BR', { day: '2-digit', month: '2-digit' })
}

function AssistenteRoute() {
  const status = useQuery({
    queryKey: ['assistant', 'status'],
    queryFn: () => assistant.status(),
  })

  return (
    <>
      <PageHeader
        eyebrow="ia"
        title="Assistente"
        subtitle="Converse sobre os dados de vocês: ele consulta o app, não inventa números"
        actions={
          status.data?.enabled ? (
            <Pill tone="ok">{status.data.model}</Pill>
          ) : undefined
        }
      />
      {status.isLoading ? (
        <Skeleton className="mt-6 h-64 w-full" />
      ) : status.data?.enabled ? (
        <Workspace />
      ) : (
        <DisabledState />
      )}
    </>
  )
}

function DisabledState() {
  return (
    <div className="mt-6 rounded-lg border border-border bg-surface p-8">
      <div className="flex items-start gap-4">
        <KeyRound className="mt-1 h-5 w-5 shrink-0 text-accent" />
        <div className="space-y-2">
          <h2 className="text-sm font-medium text-text">IA não configurada</h2>
          <p className="max-w-xl text-sm text-muted">
            Defina a variável <span className="font-mono text-text">GEMINI_API_KEY</span>{' '}
            no ambiente da API (arquivo <span className="font-mono text-text">.env</span> na
            raiz do projeto) e reinicie o serviço. A chave é criada em{' '}
            <span className="font-mono text-text">aistudio.google.com (Google AI Studio)</span>. O modelo pode
            ser trocado via <span className="font-mono text-text">APP_AI_MODEL</span>.
          </p>
          <p className="max-w-xl text-xs text-muted">
            Sem a chave, o app continua funcionando normalmente; apenas o assistente e o
            fallback de extração por IA no import ficam desligados.
          </p>
        </div>
      </div>
    </div>
  )
}

function Workspace() {
  const queryClient = useQueryClient()
  const [activeId, setActiveId] = useState<number | null>(null)
  const [pending, setPending] = useState<{ conversationId: number | null; content: string } | null>(
    null,
  )

  const conversations = useQuery({
    queryKey: ['assistant', 'conversations'],
    queryFn: () => assistant.conversations(),
  })

  const messages = useQuery({
    queryKey: ['assistant', 'messages', activeId],
    queryFn: () => assistant.messages(activeId as number),
    enabled: activeId !== null,
  })

  const send = useMutation({
    mutationFn: (body: { conversationId: number | null; content: string }) =>
      assistant.send(body),
    onSuccess: (data) => {
      setActiveId(data.conversationId)
      setPending(null)
      void queryClient.invalidateQueries({ queryKey: ['assistant', 'messages', data.conversationId] })
      void queryClient.invalidateQueries({ queryKey: ['assistant', 'conversations'] })
    },
    onError: (err: ApiError) => {
      setPending(null)
      toast.error('Falha no assistente', { description: err.message })
    },
  })

  function submit(text: string) {
    const content = text.trim()
    if (content === '' || send.isPending) return
    setPending({ conversationId: activeId, content })
    send.mutate({ conversationId: activeId, content })
  }

  const remove = useMutation({
    mutationFn: (id: number) => assistant.remove(id),
    onSuccess: (_, id) => {
      if (activeId === id) setActiveId(null)
      queryClient.removeQueries({ queryKey: ['assistant', 'messages', id] })
      void queryClient.invalidateQueries({ queryKey: ['assistant', 'conversations'] })
      toast.success('Conversa apagada')
    },
    onError: (err: ApiError) =>
      toast.error('Não foi possível apagar', { description: err.message }),
  })

  const rename = useMutation({
    mutationFn: (body: { id: number; title: string }) =>
      assistant.rename(body.id, body.title),
    onSuccess: () =>
      void queryClient.invalidateQueries({ queryKey: ['assistant', 'conversations'] }),
    onError: (err: ApiError) =>
      toast.error('Não foi possível renomear', { description: err.message }),
  })

  const pendingHere =
    pending !== null && (pending.conversationId === activeId || send.isPending === false)

  return (
    <div className="mt-6 flex h-[calc(100vh-210px)] min-h-[480px] overflow-hidden rounded-lg border border-border bg-surface">
      <ConversationSidebar
        conversations={conversations.data ?? []}
        loading={conversations.isLoading}
        activeId={activeId}
        busy={send.isPending}
        onSelect={(id) => setActiveId(id)}
        onNew={() => setActiveId(null)}
        onDelete={(id) => remove.mutate(id)}
        onRename={(id, title) => rename.mutate({ id, title })}
      />
      <ChatPane
        key={activeId ?? 'nova'}
        messages={activeId === null ? [] : (messages.data ?? [])}
        loading={activeId !== null && messages.isLoading}
        pendingQuestion={pendingHere && send.isPending ? pending.content : null}
        onSubmit={submit}
        busy={send.isPending}
      />
    </div>
  )
}

/* ------------------------------------------------------------- sidebar */

function ConversationSidebar({
  conversations,
  loading,
  activeId,
  busy,
  onSelect,
  onNew,
  onDelete,
  onRename,
}: {
  conversations: { id: number; title: string | null; updatedAt: string }[]
  loading: boolean
  activeId: number | null
  busy: boolean
  onSelect: (id: number) => void
  onNew: () => void
  onDelete: (id: number) => void
  onRename: (id: number, title: string) => void
}) {
  const [editing, setEditing] = useState<{ id: number; value: string } | null>(null)
  const [armedDelete, setArmedDelete] = useState<number | null>(null)

  useEffect(() => {
    if (armedDelete === null) return
    const t = setTimeout(() => setArmedDelete(null), 2500)
    return () => clearTimeout(t)
  }, [armedDelete])

  return (
    <aside className="flex w-60 shrink-0 flex-col border-r border-border">
      <div className="p-2">
        <button
          type="button"
          onClick={onNew}
          disabled={busy}
          className={cn(
            'flex w-full items-center gap-2 rounded-md border border-border bg-panel px-3 py-2 text-sm text-text transition-colors',
            'hover:border-accent/50 disabled:opacity-50',
            activeId === null && 'border-accent/50',
          )}
        >
          <Plus className="h-4 w-4 text-accent" />
          Nova conversa
        </button>
      </div>

      <div className="min-h-0 flex-1 space-y-0.5 overflow-y-auto px-2 pb-2">
        {loading && (
          <>
            <Skeleton className="h-9 w-full" />
            <Skeleton className="h-9 w-full" />
            <Skeleton className="h-9 w-full" />
          </>
        )}
        {!loading && conversations.length === 0 && (
          <p className="px-2 pt-4 text-xs text-muted">
            Nenhuma conversa ainda. As conversas ficam salvas aqui.
          </p>
        )}
        {conversations.map((c) => {
          const isActive = c.id === activeId
          const isEditing = editing?.id === c.id
          return (
            <div
              key={c.id}
              className={cn(
                'group relative rounded-md transition-colors',
                isActive ? 'bg-panel' : 'hover:bg-panel/60',
              )}
            >
              {isEditing ? (
                <form
                  className="flex items-center gap-1 p-1.5"
                  onSubmit={(e) => {
                    e.preventDefault()
                    const value = editing.value.trim()
                    if (value !== '') onRename(c.id, value)
                    setEditing(null)
                  }}
                >
                  <input
                    autoFocus
                    value={editing.value}
                    onChange={(e) => setEditing({ id: c.id, value: e.target.value })}
                    onKeyDown={(e) => {
                      if (e.key === 'Escape') setEditing(null)
                    }}
                    className="h-7 min-w-0 flex-1 rounded border border-accent/50 bg-bg px-2 text-xs text-text outline-none"
                  />
                  <button type="submit" className="p-1 text-ok" aria-label="Salvar título">
                    <Check className="h-3.5 w-3.5" />
                  </button>
                  <button
                    type="button"
                    className="p-1 text-muted"
                    aria-label="Cancelar"
                    onClick={() => setEditing(null)}
                  >
                    <X className="h-3.5 w-3.5" />
                  </button>
                </form>
              ) : (
                <>
                  <button
                    type="button"
                    onClick={() => onSelect(c.id)}
                    className="block w-full px-2.5 py-2 pr-14 text-left"
                  >
                    <span
                      className={cn(
                        'block truncate text-[13px]',
                        isActive ? 'text-text' : 'text-text/80',
                      )}
                    >
                      {c.title ?? 'Nova conversa'}
                    </span>
                    <span className="block text-[10px] text-muted">
                      {relativeTime(c.updatedAt)}
                    </span>
                  </button>
                  <div className="absolute right-1.5 top-1/2 flex -translate-y-1/2 items-center gap-0.5 opacity-0 transition-opacity group-hover:opacity-100">
                    <button
                      type="button"
                      aria-label="Renomear conversa"
                      className="rounded p-1 text-muted hover:bg-bg hover:text-text"
                      onClick={() =>
                        setEditing({ id: c.id, value: c.title ?? 'Nova conversa' })
                      }
                    >
                      <Pencil className="h-3.5 w-3.5" />
                    </button>
                    <button
                      type="button"
                      aria-label={
                        armedDelete === c.id
                          ? 'Clique de novo para apagar'
                          : 'Apagar conversa'
                      }
                      title={
                        armedDelete === c.id ? 'Clique de novo para apagar' : undefined
                      }
                      className={cn(
                        'rounded p-1 transition-colors hover:bg-bg',
                        armedDelete === c.id
                          ? 'text-danger'
                          : 'text-muted hover:text-text',
                      )}
                      onClick={() => {
                        if (armedDelete === c.id) {
                          setArmedDelete(null)
                          onDelete(c.id)
                        } else {
                          setArmedDelete(c.id)
                        }
                      }}
                    >
                      <Trash2 className="h-3.5 w-3.5" />
                    </button>
                  </div>
                </>
              )}
            </div>
          )
        })}
      </div>
    </aside>
  )
}

/* ---------------------------------------------------------------- chat */

function ChatPane({
  messages,
  loading,
  pendingQuestion,
  onSubmit,
  busy,
}: {
  messages: AssistantMessage[]
  loading: boolean
  pendingQuestion: string | null
  onSubmit: (text: string) => void
  busy: boolean
}) {
  const scrollRef = useRef<HTMLDivElement>(null)
  const [atBottom, setAtBottom] = useState(true)

  const isEmpty = messages.length === 0 && pendingQuestion === null && !loading

  useEffect(() => {
    if (atBottom) {
      scrollRef.current?.scrollTo({ top: scrollRef.current.scrollHeight, behavior: 'smooth' })
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [messages.length, pendingQuestion, loading])

  function handleScroll() {
    const el = scrollRef.current
    if (!el) return
    setAtBottom(el.scrollHeight - el.scrollTop - el.clientHeight < 80)
  }

  return (
    <div className="relative flex min-w-0 flex-1 flex-col">
      <div
        ref={scrollRef}
        onScroll={handleScroll}
        className="min-h-0 flex-1 overflow-y-auto"
      >
        {isEmpty ? (
          <EmptyState onPick={onSubmit} />
        ) : (
          <div className="mx-auto w-full max-w-3xl space-y-5 px-4 py-5">
            {loading && (
              <>
                <Skeleton className="ml-auto h-10 w-2/3" />
                <Skeleton className="h-24 w-full" />
              </>
            )}
            {messages.map((m) =>
              m.role === 'user' ? (
                <UserMessage key={m.id} content={m.content} />
              ) : (
                <AssistantBubble key={m.id} message={m} />
              ),
            )}
            {pendingQuestion !== null && (
              <>
                <UserMessage content={pendingQuestion} />
                <TypingIndicator />
              </>
            )}
          </div>
        )}
      </div>

      {!atBottom && (
        <button
          type="button"
          aria-label="Descer para a última mensagem"
          onClick={() =>
            scrollRef.current?.scrollTo({
              top: scrollRef.current.scrollHeight,
              behavior: 'smooth',
            })
          }
          className="absolute bottom-24 left-1/2 z-10 -translate-x-1/2 rounded-full border border-border bg-panel p-2 text-muted shadow-lg transition-colors hover:text-text"
        >
          <ArrowDown className="h-4 w-4" />
        </button>
      )}

      <Composer onSubmit={onSubmit} busy={busy} />
    </div>
  )
}

function EmptyState({ onPick }: { onPick: (text: string) => void }) {
  return (
    <div className="flex h-full flex-col items-center justify-center gap-5 px-6">
      <Sparkles className="h-6 w-6 text-accent" />
      <div className="space-y-1 text-center">
        <h2 className="text-lg font-medium text-text">
          Como posso ajudar com as finanças de vocês?
        </h2>
        <p className="text-sm text-muted">
          Eu consulto projeção, faturas, assinaturas e o modo casal. Não invento números.
        </p>
      </div>
      <div className="flex max-w-xl flex-wrap justify-center gap-2">
        {SUGGESTIONS.map((s) => (
          <button
            key={s}
            type="button"
            onClick={() => onPick(s)}
            className="rounded-full border border-border bg-panel px-3 py-1.5 text-xs text-muted transition-colors hover:border-accent/50 hover:text-text"
          >
            {s}
          </button>
        ))}
      </div>
    </div>
  )
}

function UserMessage({ content }: { content: string }) {
  return (
    <div className="flex justify-end">
      <div className="max-w-[80%] whitespace-pre-wrap rounded-2xl rounded-br-md border border-accent/30 bg-accent/10 px-4 py-2.5 text-sm leading-relaxed text-text">
        {content}
      </div>
    </div>
  )
}

function AssistantBubble({ message }: { message: AssistantMessage }) {
  const [copied, setCopied] = useState(false)

  async function copy() {
    try {
      await navigator.clipboard.writeText(message.content)
      setCopied(true)
      setTimeout(() => setCopied(false), 1500)
    } catch {
      toast.error('Não foi possível copiar')
    }
  }

  return (
    <div className="group">
      <Markdown content={message.content} />
      <div className="mt-2 flex items-center gap-2">
        <button
          type="button"
          aria-label="Copiar resposta"
          onClick={() => void copy()}
          className="rounded p-1 text-muted opacity-0 transition-opacity hover:bg-panel hover:text-text group-hover:opacity-100"
        >
          {copied ? <Check className="h-3.5 w-3.5 text-ok" /> : <Copy className="h-3.5 w-3.5" />}
        </button>
        {message.toolsUsed.length > 0 && (
          <div className="flex flex-wrap items-center gap-1">
            <span className="font-mono text-[9px] uppercase tracking-[0.18em] text-muted">
              consultou:
            </span>
            {message.toolsUsed.map((t) => (
              <span
                key={t}
                className="rounded-full border border-ok/30 bg-ok/10 px-1.5 py-0.5 font-mono text-[9px] uppercase tracking-[0.12em] text-ok"
              >
                {TOOL_LABELS[t] ?? t}
              </span>
            ))}
          </div>
        )}
      </div>
    </div>
  )
}

function TypingIndicator() {
  return (
    <div className="flex items-center gap-2">
      <MessageSquare className="h-4 w-4 text-accent" />
      <span className="font-mono text-[10px] uppercase tracking-[0.22em] text-muted">
        consultando os dados
      </span>
      <span className="flex gap-1">
        <span className="h-1 w-1 animate-bounce rounded-full bg-accent [animation-delay:0ms]" />
        <span className="h-1 w-1 animate-bounce rounded-full bg-accent [animation-delay:150ms]" />
        <span className="h-1 w-1 animate-bounce rounded-full bg-accent [animation-delay:300ms]" />
      </span>
    </div>
  )
}

function Composer({ onSubmit, busy }: { onSubmit: (text: string) => void; busy: boolean }) {
  const [input, setInput] = useState('')
  const textareaRef = useRef<HTMLTextAreaElement>(null)

  function submit() {
    if (input.trim() === '' || busy) return
    onSubmit(input)
    setInput('')
    if (textareaRef.current) textareaRef.current.style.height = 'auto'
  }

  return (
    <div className="border-t border-border p-3">
      <form
        className="mx-auto max-w-3xl rounded-xl border border-border bg-panel p-2 transition-colors focus-within:border-accent/60"
        onSubmit={(e) => {
          e.preventDefault()
          submit()
        }}
      >
        <textarea
          ref={textareaRef}
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onInput={(e) => {
            const el = e.currentTarget
            el.style.height = 'auto'
            el.style.height = `${Math.min(el.scrollHeight, 160)}px`
          }}
          onKeyDown={(e) => {
            if (e.key === 'Enter' && !e.shiftKey) {
              e.preventDefault()
              submit()
            }
          }}
          rows={1}
          placeholder="Pergunte sobre projeção, faturas, assinaturas, rotativo..."
          className="max-h-40 min-h-[38px] w-full resize-none border-none bg-transparent px-2 py-1.5 text-sm text-text outline-none placeholder:text-muted/60"
        />
        <div className="flex items-center justify-between pl-2">
          <span className="hidden text-[10px] text-muted sm:block">
            Enter envia · Shift+Enter quebra linha
          </span>
          <button
            type="submit"
            aria-label="Enviar mensagem"
            disabled={busy || input.trim() === ''}
            className={cn(
              'flex h-8 w-8 items-center justify-center rounded-md bg-accent text-bg transition-opacity',
              (busy || input.trim() === '') && 'opacity-40',
            )}
          >
            <ArrowUp className="h-4 w-4" />
          </button>
        </div>
      </form>
    </div>
  )
}

