/** Estatísticas por merchant (meses vistos, cobranças por mês) para enriquecer a UI. */
public Map<String, MerchantStats> statsByKey() {
    return analyze();
}

private Map<String, MerchantStats> analyze() {
    Map<Long, LocalDate> months = statementMonths();
    List<Transaction> candidates = transactions.findAll().stream()
            .filter(t -> t.getSupersededBy() == null)
            .filter(t -> t.getInstallmentTotal() == null)   // parcelas não são assinaturas
            .filter(t -> t.getAmount().signum() > 0)          // só despesas
            .toList();

    Map<String, List<Transaction>> byMerchant = new LinkedHashMap<>();
    for (Transaction tx : candidates) {
        String key = MerchantText.key(tx.getDescriptionRaw());
        if (!key.isBlank()) {
            byMerchant.computeIfAbsent(key, k -> new ArrayList<>()).add(tx);
        }
    }

    Map<String, MerchantStats> result = new LinkedHashMap<>();
    byMerchant.forEach((key, txs) -> {
        // Agrupa por mês de fatura: o "valor" de uma assinatura é o total do mês.
        Map<LocalDate, List<Transaction>> byMonth = new java.util.TreeMap<>();
        for (Transaction tx : txs) {
            LocalDate month = months.getOrDefault(tx.getStatementId(),
                    tx.getPostedAt().withDayOfMonth(1));
            byMonth.computeIfAbsent(month, m -> new ArrayList<>()).add(tx);
        }
        List<BigDecimal> monthlyTotals = byMonth.values().stream()
                .map(list -> list.stream().map(Transaction::getAmount)
                        .reduce(BigDecimal.ZERO, BigDecimal::add))
                .toList();
        int timesPerMonth = medianInt(byMonth.values().stream().map(List::size).toList());
        String display = MerchantText.extract(txs.get(0).getDescriptionRaw());
        result.put(key, new MerchantStats(display, byMonth.size(),
                median(monthlyTotals), isStable(monthlyTotals), timesPerMonth));
    });
    return result;
}

private int medianInt(List<Integer> counts) {
    List<Integer> sorted = counts.stream().sorted().toList();
    return sorted.isEmpty() ? 1 : sorted.get(sorted.size() / 2);
}

