import org.springframework.web.bind.annotation.RestController;

/** Dashboard do "passado" (Fase 0): gastos por categoria num período. */
@RestController
@RequestMapping("/api/dashboard")
public class DashboardController {

    private final TransactionRepository transactions;
    private final StatementRepository statements;

    public DashboardController(TransactionRepository transactions, StatementRepository statements) {
        this.transactions = transactions;
        this.statements = statements;
    }

    @GetMapping("/by-category")
    public CategorySummaryResponse byCategory(
            @RequestParam(required = false)
            @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate from,
            @RequestParam(required = false)
            @DateTimeFormat(iso = DateTimeFormat.ISO.DATE) LocalDate to) {

        LocalDate start = from != null ? from : LocalDate.of(2000, 1, 1);
        LocalDate end = to != null ? to : LocalDate.now();

        List<CategoryTotal> categories = transactions.totalsByCategory(start, end);
        BigDecimal total = categories.stream()
                .map(CategoryTotal::total)
                .reduce(BigDecimal.ZERO, BigDecimal::add);

        return new CategorySummaryResponse(start, end, total, categories);
    }

    /**
     * Análise por mês de fatura. Sem parâmetros usa todo o histórico; {@code last=N}
     * recorta as N faturas mais recentes; {@code from}/{@code to} (YYYY-MM) fixam
     * o intervalo explicitamente e ganham de {@code last}.
     */
    @GetMapping("/category-analysis")
    public CategoryAnalysisResponse categoryAnalysis(
            @RequestParam(required = false) String from,
            @RequestParam(required = false) String to,
            @RequestParam(required = false) Integer last) {

        List<LocalDate> available = statements.findAll().stream()
                .map(com.vini.financemonitor.statement.Statement::getReferenceMonth)
                .distinct()
                .sorted()
                .toList();
        if (available.isEmpty()) {
            return new CategoryAnalysisResponse(null, null, BigDecimal.ZERO,
                    List.of(), List.of(), List.of());
        }

        LocalDate start;
        LocalDate end;
        if (from != null || to != null) {
            start = from != null ? YearMonth.parse(from).atDay(1) : available.get(0);
            end = to != null ? YearMonth.parse(to).atDay(1) : available.get(available.size() - 1);
        } else if (last != null && last > 0) {
            end = available.get(available.size() - 1);
            start = available.get(Math.max(0, available.size() - last));
        } else {
            start = available.get(0);
            end = available.get(available.size() - 1);
        }

        List<MonthCategoryTotal> rows = transactions.totalsByStatementMonthAndCategory(start, end);

        Map<LocalDate, List<CategoryTotal>> byMonth = new LinkedHashMap<>();
        Map<String, BigDecimal> byCategory = new LinkedHashMap<>();
        for (MonthCategoryTotal row : rows) {
            byMonth.computeIfAbsent(row.month(), m -> new ArrayList<>())
                    .add(new CategoryTotal(row.categoryName(), null, row.total()));
            byCategory.merge(row.categoryName(), row.total(), BigDecimal::add);
        }

        List<CategoryMonthBucket> months = byMonth.entrySet().stream()
                .map(e -> new CategoryMonthBucket(
                        e.getKey(),
                        e.getValue().stream().map(CategoryTotal::total)
                                .reduce(BigDecimal.ZERO, BigDecimal::add),
                        e.getValue()))
                .toList();

        List<CategoryTotal> totals = byCategory.entrySet().stream()
                .map(e -> new CategoryTotal(e.getKey(), null, e.getValue()))
                .sorted((a, b) -> b.total().compareTo(a.total()))
                .toList();

        BigDecimal total = totals.stream()
                .map(CategoryTotal::total)
                .reduce(BigDecimal.ZERO, BigDecimal::add);

        return new CategoryAnalysisResponse(start, end, total, totals, months, available);
    }
}

