import { DonutChart } from '@tremor/react'
import { Link } from '@tanstack/react-router'
import { ArrowRight } from 'lucide-react'

import { brlMoney } from '@/lib/format'
import type { CategoryAnalysisResponse } from '@/types/api'

import { Eyebrow, Num, Panel } from './Panel'
import { paletteHex } from './SubscriptionsPanel'

/**
 * Ordem categórica FIXA do cockpit (validada p/ daltonismo contra a superfície
 * dark): as 4 maiores categorias ganham cor; o resto vira "outros" em cinza.
 */
export const CATEGORY_COLORS = ['amber', 'cyan', 'rose', 'yellow']

interface CategoriesPanelProps {
  data: CategoryAnalysisResponse
  /** Substitui o "from → to" do rodapé (ex.: "últimas 3 faturas"). */
  periodLabel?: string
  /** Mostra o atalho para a tela de análise completa. */
  showAnalysisLink?: boolean
}

export function CategoriesPanel({ data, periodLabel, showAnalysisLink }: CategoriesPanelProps) {
  if (!data.totals || data.totals.length === 0) {
    return (
      <Panel eyebrow="por categoria" title="Gastos por categoria">
        <p className="text-sm text-muted">Sem gastos categorizados no período.</p>
      </Panel>
    )
  }

  const sorted = [...data.totals]
    .filter((c) => Number(c.total) > 0)
    .sort((a, b) => b.total - a.total)

  const top = sorted.slice(0, CATEGORY_COLORS.length)
  const rest = sorted.slice(CATEGORY_COLORS.length)
  const restTotal = rest.reduce((acc, c) => acc + Number(c.total), 0)

  const donutData = [
    ...top.map((c) => ({ name: c.categoryName, value: Number(c.total) })),
    ...(rest.length > 0 ? [{ name: 'outros', value: restTotal }] : []),
  ]
  const donutColors = [...CATEGORY_COLORS.slice(0, top.length), 'zinc']

  const max = Math.max(...sorted.map((c) => Number(c.total)), 1)

  return (
    <Panel
      eyebrow="por categoria"
      title="Gastos por categoria"
      hint={`${sorted.length} categorias`}
      actions={
        <Num className="text-base text-accent">{brlMoney(data.total)}</Num>
      }
    >
      <div className="flex flex-col gap-5">
        <div className="flex items-center justify-center">
          <DonutChart
            data={donutData}
            category="value"
            index="name"
            colors={donutColors}
            valueFormatter={brlMoney}
            showLabel={false}
            className="h-36"
          />
        </div>

        <ul className="space-y-2">
          {sorted.map((c, idx) => {
            const widthPct = (Number(c.total) / max) * 100
            const swatch = paletteHex(CATEGORY_COLORS[idx] ?? 'zinc')
            return (
              <li
                key={c.categoryName}
                className="grid grid-cols-[1fr_auto] items-center gap-2 text-xs"
              >
                <div className="flex min-w-0 flex-col gap-1">
                  <div className="flex items-center gap-2">
                    <span
                      className="inline-block size-2 shrink-0 rounded-sm"
                      style={{ background: swatch }}
                    />
                    <span className="truncate text-text">{c.categoryName}</span>
                  </div>
                  <div className="h-1 w-full overflow-hidden rounded-full bg-panel">
                    <div
                      className="h-full rounded-full"
                      style={{
                        width: `${widthPct}%`,
                        background: swatch,
                        opacity: 0.7,
                      }}
                    />
                  </div>
                </div>
                <Num className="text-xs">{brlMoney(c.total)}</Num>
              </li>
            )
          })}
        </ul>

        <div className="flex items-center justify-between border-t border-border pt-3">
          <Eyebrow>período</Eyebrow>
          <div className="flex items-center gap-3">
            <Num className="text-[11px] text-muted">
              {periodLabel ?? `${data.from ?? '—'} → ${data.to ?? '—'}`}
            </Num>
            {showAnalysisLink && (
              <Link
                to="/categorias"
                className="flex items-center gap-1 text-[11px] text-ok transition-colors hover:text-text"
              >
                análise completa
                <ArrowRight className="h-3 w-3" />
              </Link>
            )}
          </div>
        </div>
      </div>
    </Panel>
  )
}

