/** "2025-03-01" -> "mar/25" */
export function monthLabel(isoDate: string | null | undefined): string {
  if (!isoDate) return ''
  const [y, m] = isoDate.split('-')
  const idx = Number(m) - 1
  if (idx < 0 || idx > 11) return ''
  return `${MONTHS_SHORT[idx]}/${y.slice(2)}`
}

/** "2025-03-01" -> "mar" */
export function shortMonth(isoDate: string | null | undefined): string {
  if (!isoDate) return ''
  const [, m] = isoDate.split('-')
  const idx = Number(m) - 1
  if (idx < 0 || idx > 11) return ''
  return MONTHS_SHORT[idx]
}
