import { BarChart } from '@tremor/react'
import { useQuery } from '@tanstack/react-query'
import { createFileRoute } from '@tanstack/react-router'
import { PieChart } from 'lucide-react'
import { useState } from 'react'

import { CategoriesPanel, CATEGORY_COLORS } from '@/components/dashboard/CategoriesPanel'
import { Panel } from '@/components/dashboard/Panel'
import { EmptyState } from '@/components/lists/EmptyState'
import { KpiTile } from '@/components/lists/KpiTile'
import { PageHeader } from '@/components/shell/PageHeader'
import { Skeleton } from '@/components/ui/skeleton'
import { dashboard } from '@/lib/api'
import { brlMoney, brlShort, monthLabel } from '@/lib/format'
import type { CategoryAnalysisResponse } from '@/types/api'

export const Route = createFileRoute('/categorias')({
  component: CategoriasRoute,
})

const OUTROS = 'outros'

function CategoriasRoute() {
  const [from, setFrom] = useState<string | undefined>(undefined)
  const [to, setTo] = useState<string | undefined>(undefined)

  const analysis = useQuery({
    queryKey: ['dashboard', 'category-analysis', from ?? 'inicio', to ?? 'fim'],
    queryFn: () => dashboard.categoryAnalysis({ from, to }),
  })

  return (
    <>
      <PageHeader
        eyebrow="análise"
        title="Categorias"
        subtitle="Para onde o dinheiro foi, por mês de fatura, com o período que você escolher"
        actions={
          analysis.data && analysis.data.availableMonths.length > 0 ? (
            <PeriodFilter
              available={analysis.data.availableMonths}
              from={from}
              to={to}
              onFrom={setFrom}
              onTo={setTo}
            />
          ) : undefined
        }
      />

      {analysis.isLoading ? (
        <div className="mt-6 space-y-4">
          <Skeleton className="h-20 w-full" />
          <Skeleton className="h-72 w-full" />
        </div>
      ) : !analysis.data || analysis.data.months.length === 0 ? (
        <div className="mt-6">
          <EmptyState
            icon={PieChart}
            title="Sem dados no período"
            description="Importe faturas (ou ajuste o filtro) para ver a análise por categoria."
          />
        </div>
      ) : (
        <Content data={analysis.data} />
      )}
    </>
  )
}

function PeriodFilter({
  available,
  from,
  to,
  onFrom,
  onTo,
}: {
  available: string[]
  from: string | undefined
  to: string | undefined
  onFrom: (v: string | undefined) => void
  onTo: (v: string | undefined) => void
}) {
  const selectClass =
    'h-9 rounded-md border border-border bg-panel px-2 text-sm text-text outline-none focus:border-accent'

  return (
    <div className="flex items-center gap-2">
      <label className="font-mono text-[10px] uppercase tracking-[0.18em] text-muted">
        de
      </label>
      <select
        value={from ?? ''}
        onChange={(e) => onFrom(e.target.value === '' ? undefined : e.target.value)}
        className={selectClass}
      >
        <option value="">primeira fatura</option>
        {available.map((m) => (
          <option key={m} value={m.slice(0, 7)}>
            {monthLabel(m)}
          </option>
        ))}
      </select>
      <label className="font-mono text-[10px] uppercase tracking-[0.18em] text-muted">
        até
      </label>
      <select
        value={to ?? ''}
        onChange={(e) => onTo(e.target.value === '' ? undefined : e.target.value)}
        className={selectClass}
      >
        <option value="">última fatura</option>
        {available.map((m) => (
          <option key={m} value={m.slice(0, 7)}>
            {monthLabel(m)}
          </option>
        ))}
      </select>
    </div>
  )
}

function Content({ data }: { data: CategoryAnalysisResponse }) {
  const monthCount = data.months.length
  const monthlyAverage = monthCount > 0 ? data.total / monthCount : 0
  const topCategory = data.totals[0]

  // Cor segue a entidade: as 4 maiores do PERÍODO definem as séries do
  // empilhado; o resto agrega em "outros" (cinza) em todos os meses.
  const topNames = data.totals.slice(0, CATEGORY_COLORS.length).map((c) => c.categoryName)
  const hasOutros = data.totals.length > topNames.length

  const chartData = data.months.map((bucket) => {
    const row: Record<string, string | number> = { month: monthLabel(bucket.month) }
    let assigned = 0
    for (const name of topNames) {
      const value = Number(
        bucket.categories.find((c) => c.categoryName === name)?.total ?? 0,
      )
      row[name] = value
      assigned += value
    }
    if (hasOutros) {
      row[OUTROS] = Math.max(0, Number(bucket.total) - assigned)
    }
    return row
  })

  const series = hasOutros ? [...topNames, OUTROS] : topNames
  const colors = hasOutros
    ? [...CATEGORY_COLORS.slice(0, topNames.length), 'zinc']
    : CATEGORY_COLORS.slice(0, topNames.length)

  return (
    <div className="mt-6 flex flex-col gap-4">
      <div className="grid grid-cols-1 gap-3 md:grid-cols-3">
        <KpiTile
          label="Total no período"
          value={brlMoney(data.total)}
          tone="accent"
        />
        <KpiTile
          label={`Média por fatura (${monthCount} ${monthCount === 1 ? 'mês' : 'meses'})`}
          value={brlMoney(monthlyAverage)}
          tone="ok"
        />
        <KpiTile
          label="Maior categoria"
          value={topCategory ? topCategory.categoryName : 'sem dados'}
          hint={topCategory ? brlMoney(topCategory.total) : undefined}
          tone="warn"
        />
      </div>

      <div className="grid gap-4 xl:grid-cols-3">
        <div className="xl:col-span-2">
          <Panel
            eyebrow="mês a mês"
            title="Evolução por categoria"
            hint={`${monthLabel(data.from)} → ${monthLabel(data.to)}`}
          >
            <BarChart
              data={chartData}
              index="month"
              categories={series}
              colors={colors}
              stack
              valueFormatter={brlShort}
              showLegend
              yAxisWidth={64}
              className="h-72"
            />
          </Panel>
        </div>

        <CategoriesPanel
          data={data}
          periodLabel={`${monthLabel(data.from)} → ${monthLabel(data.to)}`}
        />
      </div>
    </div>
  )
}

