    /** Visão agregada dos planos (usada pela tela de parcelas e pelo assistente). */
    public InstallmentsResponse summary() {
        Map<Long, String> categoryNames = categories.findAll().stream()
                .collect(java.util.stream.Collectors.toMap(Category::getId, Category::getName));

        List<InstallmentPlanView> views = plans.findAll().stream()
                .map(plan -> toView(plan, categoryNames))
                .sorted(Comparator.comparing(InstallmentPlanView::remainingLiability).reversed())
                .toList();

        int active = (int) views.stream()
                .filter(v -> v.remainingInstallments() != null && v.remainingInstallments() > 0)
                .count();
        BigDecimal totalRemaining = views.stream()
                .map(InstallmentPlanView::remainingLiability)
                .reduce(BigDecimal.ZERO, BigDecimal::add);

        return new InstallmentsResponse(views.size(), active, totalRemaining, views);
    }

    private InstallmentPlanView toView(InstallmentPlan plan, Map<Long, String> categoryNames) {
        int total = plan.getTotalInstallments() == null ? 0 : plan.getTotalInstallments();
        int remaining = plan.getRemainingInstallments() == null ? 0 : plan.getRemainingInstallments();
        BigDecimal amount = plan.getInstallmentAmount() == null ? BigDecimal.ZERO : plan.getInstallmentAmount();
        BigDecimal remainingLiability = amount.multiply(BigDecimal.valueOf(remaining));
        return new InstallmentPlanView(
                plan.getId(),
                plan.getMerchant(),
                plan.getTotalInstallments(),
                total - remaining,
                plan.getRemainingInstallments(),
                amount,
                remainingLiability,
                plan.getFirstPostedAt(),
                plan.getCategoryId() == null ? null : categoryNames.get(plan.getCategoryId()));
    }''')

open(p, 'w').write(s)
print('service ok')
