/**
 * Previsão de descompressão: a parcela k de cada plano cai na fatura âncora+k,
 * então a carga mensal e os alívios são deriváveis dos próprios planos. Vale
 * enquanto nada novo for parcelado (a ressalva aparece na UI).
 */
function ForecastSection({
  active,
  anchor,
  monthlyLoad,
}: {
  active: InstallmentPlan[]
  anchor: string
  monthlyLoad: number
}) {
  const maxRemaining = Math.max(
    ...active.map((p) => p.remainingInstallments ?? 0),
  )

  const series = Array.from({ length: maxRemaining }, (_, i) => {
    const k = i + 1
    const load = active
      .filter((p) => (p.remainingInstallments ?? 0) >= k)
      .reduce((acc, p) => acc + Number(p.installmentAmount), 0)
    return { month: monthLabel(addMonths(anchor, k)), 'carga de parcelas': load }
  })

  // Marcos de alívio: planos agrupados pelo mês da última parcela; o valor
  // deixa de pesar no mês seguinte.
  const byEnd = new Map<string, InstallmentPlan[]>()
  for (const p of active) {
    const end = addMonths(anchor, p.remainingInstallments ?? 0)
    byEnd.set(end, [...(byEnd.get(end) ?? []), p])
  }
  let runningLoad = monthlyLoad
  const milestones = [...byEnd.entries()]
    .sort(([a], [b]) => a.localeCompare(b))
    .map(([endIso, plans]) => {
      const relief = plans.reduce((acc, p) => acc + Number(p.installmentAmount), 0)
      runningLoad -= relief
      return {
        from: monthLabel(addMonths(endIso, 1)),
        relief,
        loadAfter: Math.max(0, runningLoad),
        names: plans.map((p) => p.merchant),
      }
    })
  const freeFrom = monthLabel(addMonths(anchor, maxRemaining + 1))

  return (
    <div className="mt-6 grid gap-4 xl:grid-cols-3">
      <div className="xl:col-span-2">
        <Panel
          eyebrow="previsão"
          title="Descompressão das parcelas"
          hint="se nada novo for parcelado"
        >
          <BarChart
            data={series}
            index="month"
            categories={['carga de parcelas']}
            colors={['amber']}
            valueFormatter={brlShort}
            showLegend={false}
            yAxisWidth={56}
            className="h-64"
          />
        </Panel>
      </div>

      <Panel
        eyebrow="marcos de alívio"
        title="Quando o bolso respira"
        hint={`livre de parcelas em ${freeFrom}`}
      >
        <ul className="space-y-3">
          {milestones.map((m) => (
            <li key={m.from} className="border-b border-border/60 pb-3 last:border-b-0 last:pb-0">
              <div className="flex items-center justify-between gap-2">
                <span className="flex items-center gap-1.5 text-sm text-text">
                  <TrendingDown className="h-3.5 w-3.5 text-ok" />
                  a partir de {m.from}
                </span>
                <span className="font-mono text-sm tabular-nums text-ok">
                  {brlMoney(m.relief)} a menos
                </span>
              </div>
              <p className="mt-1 truncate text-[11px] text-muted" title={m.names.join(', ')}>
                quita {m.names.slice(0, 2).join(', ')}
                {m.names.length > 2 ? ` +${m.names.length - 2}` : ''}
              </p>
              <p className="text-[11px] text-muted">
                carga mensal vira{' '}
                <span className="font-mono tabular-nums text-text">
                  {brlMoney(m.loadAfter)}
                </span>
              </p>
            </li>
          ))}
        </ul>
      </Panel>
    </div>
  )
}

