function handleBarClick(event: EventProps) {
  if (!event) return
  // O Tremor espalha a linha clicada no evento; `index` nem sempre vem
  // preenchido, então caímos no campo `month` da própria linha.
  const row = event as Record<string, unknown>
  const label = (row.index ?? row.month) as string | undefined
  const idx = series.findIndex((s) => s.month === label)
  if (idx >= 0) setOpenMonthK(idx + 1)
}

