import {
  type ColumnDef,
  type RowData,
  type SortingState,
  flexRender,
  getCoreRowModel,
  getFilteredRowModel,
  getSortedRowModel,
  useReactTable,
} from '@tanstack/react-table'
import { ArrowDown, ArrowUp, ArrowUpDown, Search } from 'lucide-react'
import { type ReactNode, useState } from 'react'

import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import { cn } from '@/lib/utils'

declare module '@tanstack/react-table' {
  // eslint-disable-next-line @typescript-eslint/no-unused-vars
  interface ColumnMeta<TData extends RowData, TValue> {
    /** Classe extra do <th> (ex.: text-right). */
    headerClassName?: string
    /** Classe extra do <td>. */
    cellClassName?: string
  }
}

interface DataTableProps<TData> {
  columns: ColumnDef<TData, unknown>[]
  data: TData[]
  /** Presente = mostra o campo de busca global com esse placeholder. */
  searchPlaceholder?: string
  initialSorting?: SortingState
  /** Controles extras na barra (ex.: um filtro específico da tela). */
  toolbar?: ReactNode
  emptyMessage?: string
}

/**
 * Tabela do cockpit com ordenação por coluna e busca global (TanStack Table).
 * Sem paginação de propósito: os volumes do app não justificam esconder linhas.
 */
export function DataTable<TData>({
  columns,
  data,
  searchPlaceholder,
  initialSorting = [],
  toolbar,
  emptyMessage = 'Nada por aqui.',
}: DataTableProps<TData>) {
  const [sorting, setSorting] = useState<SortingState>(initialSorting)
  const [globalFilter, setGlobalFilter] = useState('')

  const table = useReactTable({
    data,
    columns,
    state: { sorting, globalFilter },
    onSortingChange: setSorting,
    onGlobalFilterChange: setGlobalFilter,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(),
    getFilteredRowModel: getFilteredRowModel(),
    globalFilterFn: 'includesString',
  })

  const rows = table.getRowModel().rows
  const hasToolbar = searchPlaceholder !== undefined || toolbar !== undefined

  return (
    <div className="rounded-lg border border-border bg-surface">
      {hasToolbar && (
        <div className="flex flex-wrap items-center justify-between gap-3 border-b border-border px-3 py-2">
          <div className="flex items-center gap-3">
            {searchPlaceholder !== undefined && (
              <div className="flex h-8 items-center gap-2 rounded-md border border-border bg-panel px-2 focus-within:border-accent">
                <Search className="h-3.5 w-3.5 shrink-0 text-muted" />
                <input
                  value={globalFilter}
                  onChange={(e) => setGlobalFilter(e.target.value)}
                  placeholder={searchPlaceholder}
                  className="w-48 bg-transparent text-sm text-text outline-none placeholder:text-muted/60 sm:w-64"
                />
              </div>
            )}
            <span className="font-mono text-[10px] uppercase tracking-[0.18em] text-muted">
              {rows.length === data.length
                ? `${data.length} ${data.length === 1 ? 'linha' : 'linhas'}`
                : `${rows.length} de ${data.length}`}
            </span>
          </div>
          {toolbar}
        </div>
      )}

      <Table>
        <TableHeader>
          {table.getHeaderGroups().map((headerGroup) => (
            <TableRow key={headerGroup.id}>
              {headerGroup.headers.map((header) => {
                const canSort = header.column.getCanSort()
                const dir = header.column.getIsSorted()
                return (
                  <TableHead
                    key={header.id}
                    className={header.column.columnDef.meta?.headerClassName}
                  >
                    {header.isPlaceholder ? null : canSort ? (
                      <button
                        type="button"
                        onClick={header.column.getToggleSortingHandler()}
                        className={cn(
                          'inline-flex items-center gap-1 transition-colors hover:text-text',
                          header.column.columnDef.meta?.headerClassName?.includes(
                            'text-right',
                          ) && 'flex-row-reverse',
                          dir && 'text-text',
                        )}
                      >
                        {flexRender(header.column.columnDef.header, header.getContext())}
                        {dir === 'asc' ? (
                          <ArrowUp className="h-3 w-3 text-accent" />
                        ) : dir === 'desc' ? (
                          <ArrowDown className="h-3 w-3 text-accent" />
                        ) : (
                          <ArrowUpDown className="h-3 w-3 opacity-40" />
                        )}
                      </button>
                    ) : (
                      flexRender(header.column.columnDef.header, header.getContext())
                    )}
                  </TableHead>
                )
              })}
            </TableRow>
          ))}
        </TableHeader>
        <TableBody>
          {rows.length === 0 ? (
            <TableRow>
              <TableCell
                colSpan={columns.length}
                className="py-8 text-center text-sm text-muted"
              >
                {emptyMessage}
              </TableCell>
            </TableRow>
          ) : (
            rows.map((row) => (
              <TableRow key={row.id}>
                {row.getVisibleCells().map((cell) => (
                  <TableCell
                    key={cell.id}
                    className={cell.column.columnDef.meta?.cellClassName}
                  >
                    {flexRender(cell.column.columnDef.cell, cell.getContext())}
                  </TableCell>
                ))}
              </TableRow>
            ))
          )}
        </TableBody>
      </Table>
    </div>
  )
}

