import { useQuery } from '@tanstack/react-query'

import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { installments } from '@/lib/api'
import { brlMoney, monthLabel, pct } from '@/lib/format'
import type { ProjectionMonth } from '@/types/api'

/** Diferença em meses entre dois primeiros-dias ISO (YYYY-MM-01). */
function monthOffset(fromIso: string, toIso: string): number {
  const [fy, fm] = fromIso.split('-').map(Number)
  const [ty, tm] = toIso.split('-').map(Number)
  return (ty - fy) * 12 + (tm - fm)
}

/**
 * Drill do gráfico de projeção: a composição de um mês futuro — números do
 * comprometimento + exatamente quais parcelas caem naquela fatura.
 */
export function MonthDetailDialog({
  month,
  anchorMonth,
  onClose,
}: {
  month: ProjectionMonth | null
  anchorMonth: string
  onClose: () => void
}) {
  const plansQ = useQuery({
    queryKey: ['installments'],
    queryFn: () => installments.list(),
    enabled: month !== null,
  })

  const k = month ? monthOffset(anchorMonth, month.month) : 0
  const monthPlans = (plansQ.data?.plans ?? []).filter(
    (p) => (p.remainingInstallments ?? 0) >= k && k > 0,
  )

  return (
    <Dialog open={month !== null} onOpenChange={(open) => !open && onClose()}>
      <DialogContent>
        {month && (
          <>
            <DialogHeader>
              <DialogTitle>Comprometido de {monthLabel(month.month)}</DialogTitle>
              <DialogDescription>
                {brlMoney(month.committedGross)} bruto · {brlMoney(month.committedNet)}{' '}
                líquido · índice {pct(month.ratioNet)} da renda
              </DialogDescription>
            </DialogHeader>

            <div className="grid grid-cols-3 gap-2">
              <MiniStat label="parcelas suas" value={brlMoney(
                Math.max(0, Number(month.installmentsGross) - Number(month.installmentsThirdParty)),
              )} />
              <MiniStat label="assinaturas" value={brlMoney(month.recurring)} />
              <MiniStat
                label="terceiros"
                value={brlMoney(month.installmentsThirdParty)}
              />
            </div>

            <div>
              <p className="mb-1.5 font-mono text-[10px] uppercase tracking-[0.18em] text-muted">
                parcelas nessa fatura · {monthPlans.length}
              </p>
              {monthPlans.length === 0 ? (
                <p className="text-sm text-muted">
                  Nenhuma parcela cai neste mês. O comprometido é só de assinaturas.
                </p>
              ) : (
                <ul className="max-h-64 divide-y divide-border overflow-y-auto rounded-md border border-border bg-panel">
                  {monthPlans.map((p) => {
                    const total = p.totalInstallments ?? 0
                    const numberInMonth = p.paidInstallments + k
                    return (
                      <li
                        key={p.id}
                        className="flex items-center justify-between gap-3 px-3 py-2"
                      >
                        <div className="flex min-w-0 flex-col">
                          <span className="truncate text-sm text-text">
                            {p.merchant}
                          </span>
                          <span className="text-[11px] text-muted">
                            parcela {numberInMonth}/{total}
                            {numberInMonth === total ? ' · última' : ''}
                          </span>
                        </div>
                        <span className="font-mono text-sm tabular-nums text-text">
                          {brlMoney(p.installmentAmount)}
                        </span>
                      </li>
                    )
                  })}
                </ul>
              )}
            </div>
          </>
        )}
      </DialogContent>
    </Dialog>
  )
}

function MiniStat({ label, value }: { label: string; value: string }) {
  return (
    <div className="rounded-md border border-border bg-panel px-2.5 py-2">
      <p className="font-mono text-[9px] uppercase tracking-[0.14em] text-muted">
        {label}
      </p>
      <p className="font-mono text-sm tabular-nums text-text">{value}</p>
    </div>
  )
}

