 */
function Heatmap({ data }: { data: CategoryAnalysisResponse }) {
  const months = data.months
  const categories = data.totals

  return (
    <Panel
      eyebrow="mapa de calor"
      title="Intensidade por categoria e mês"
      hint="cor relativa ao pico da própria categoria"
    >
