package com.vini.financemonitor.recurrence;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import org.springframework.stereotype.Component;

/**
 * Classifica a FUNÇÃO de uma assinatura (streaming de vídeo, música, IA...)
 * a partir de {@code rules/subscription-functions.json}. É isso que torna o
 * alerta de sobreposição acionável: várias assinaturas na mesma função fazem
 * o mesmo trabalho. Regras são config (edite o JSON, não o código); a primeira
 * que casar vence; sem match vira {@link #FALLBACK}.
 */
@Component
public class SubscriptionFunctionClassifier {

    public static final String FALLBACK = "outras";

    private record Group(String name, List<String> keywords) {
    }

    private final List<Group> groups;

    public SubscriptionFunctionClassifier(ObjectMapper json) {
        this.groups = load(json);
    }

    public String classify(String displayName) {
        if (displayName == null) {
            return FALLBACK;
        }
        String normalized = displayName.toLowerCase(Locale.ROOT);
        for (Group group : groups) {
            for (String keyword : group.keywords()) {
                if (normalized.contains(keyword)) {
                    return group.name();
                }
            }
        }
        return FALLBACK;
    }

    private List<Group> load(ObjectMapper json) {
        try (InputStream in = getClass().getResourceAsStream("/rules/subscription-functions.json")) {
            JsonNode root = json.readTree(in);
            List<Group> result = new ArrayList<>();
            for (JsonNode node : root.path("groups")) {
                List<String> keywords = new ArrayList<>();
                node.path("keywords").forEach(k -> keywords.add(k.asText().toLowerCase(Locale.ROOT)));
                result.add(new Group(node.path("name").asText(), keywords));
            }
            return List.copyOf(result);
        } catch (Exception e) {
            throw new IllegalStateException("Falha ao carregar subscription-functions.json", e);
        }
    }
}

