function FunctionGroupDialog({
  data,
  group,
  onClose,
}: {
  data: SubscriptionWeightResponse
  group: string | null
  onClose: () => void
}) {
  if (group === null) {
    return null
  }
  const members = data.items
    .filter((it) => it.functionGroup === group)
