package com.vini.financemonitor.recurrence;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.InputStream;
import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import org.springframework.stereotype.Component;

/**
 * Colapsa merchant keys de um mesmo serviço que muda de nome na fatura
 * (ex.: "claude ai subscription" e "anthropic claude sub" são a MESMA
 * assinatura). Sem isso a detecção de recorrência vê dois candidatos com
 * histórico curto em vez de um com histórico completo. Regras em
 * {@code rules/merchant-aliases.json}.
 */
@Component
public class MerchantAliases {

    private record Alias(String canonical, List<String> contains) {
    }

    private final List<Alias> aliases;

    public MerchantAliases(ObjectMapper json) {
        this.aliases = load(json);
    }

    /** Chave canônica para agrupamento; devolve a própria chave se não há alias. */
    public String canonicalKey(String merchantKey) {
        String normalized = merchantKey.toLowerCase(Locale.ROOT);
        for (Alias alias : aliases) {
            for (String fragment : alias.contains()) {
                if (normalized.contains(fragment)) {
                    return alias.canonical();
                }
            }
        }
        return merchantKey;
    }

    private List<Alias> load(ObjectMapper json) {
        try (InputStream in = getClass().getResourceAsStream("/rules/merchant-aliases.json")) {
            JsonNode root = json.readTree(in);
            List<Alias> result = new ArrayList<>();
            for (JsonNode node : root.path("aliases")) {
                List<String> contains = new ArrayList<>();
                node.path("contains").forEach(c -> contains.add(c.asText().toLowerCase(Locale.ROOT)));
                result.add(new Alias(node.path("canonical").asText(), contains));
            }
            return List.copyOf(result);
        } catch (Exception e) {
            throw new IllegalStateException("Falha ao carregar merchant-aliases.json", e);
        }
    }
}

