import org.apache.pdfbox.Loader;
import org.apache.pdfbox.pdmodel.PDDocument;
import org.apache.pdfbox.text.PDFTextStripper;
import org.springframework.stereotype.Component;

/** Descobre qual adapter de banco entende o PDF enviado (sniff do texto). */
@Component
public class BankAdapterRegistry {

    private final List<BankStatementAdapter> adapters;

    public BankAdapterRegistry(List<BankStatementAdapter> adapters) {
        this.adapters = adapters;
    }

    public BankStatementAdapter detect(byte[] pdf) {
        String text = extractText(pdf);
        return adapters.stream()
                .filter(a -> a.supports(text))
                .findFirst()
                .orElseThrow(() -> new PdfParseException(
                        "Nenhum adapter reconheceu esta fatura. Bancos suportados: "
                                + adapters.stream().map(BankStatementAdapter::provider).toList()));
    }

    static String extractText(byte[] pdf) {
        try (PDDocument document = Loader.loadPDF(pdf)) {
            PDFTextStripper stripper = new PDFTextStripper();
            stripper.setSortByPosition(true);
            return stripper.getText(document);
        } catch (IOException e) {
            throw new PdfParseException("Falha ao ler o PDF: " + e.getMessage());
        }
    }
}

