package com.vini.financemonitor.ingestion.pdf;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import org.springframework.stereotype.Component;

/**
 * Adapter Sicredi: embrulha o parser de linhas (com a costura das transações
 * internacionais/parceladas quebradas em 2-3 linhas) e o parser do resumo da
 * página 1. Toda a interpretação Sicredi-specific (datas "DD/mmm", marcador de
 * parcela "NN/MM", descrição após Online/Presencial) mora AQUI — o pipeline de
 * import não conhece mais nada disso.
 */
@Component
public class SicrediStatementAdapter implements BankStatementAdapter {

    private static final Pattern DATE_TOKEN = Pattern.compile("^(\\d{2})/([a-z]{3})");
    private static final Pattern INSTALLMENT = Pattern.compile("\\b(\\d{2})/(\\d{2})\\b");
    private static final Map<String, Integer> MONTHS = Map.ofEntries(
            Map.entry("jan", 1), Map.entry("fev", 2), Map.entry("mar", 3), Map.entry("abr", 4),
            Map.entry("mai", 5), Map.entry("jun", 6), Map.entry("jul", 7), Map.entry("ago", 8),
            Map.entry("set", 9), Map.entry("out", 10), Map.entry("nov", 11), Map.entry("dez", 12));

    private final SicrediPdfStatementParser parser;
    private final SicrediSummaryParser summaryParser;

    public SicrediStatementAdapter(SicrediPdfStatementParser parser,
                                   SicrediSummaryParser summaryParser) {
        this.parser = parser;
        this.summaryParser = summaryParser;
    }

    @Override
    public String provider() {
        return "SICREDI";
    }

    @Override
    public boolean supports(String pdfText) {
        return pdfText.toLowerCase(java.util.Locale.ROOT).contains("sicredi");
    }

    @Override
    public ParsedStatement parse(byte[] pdf, LocalDate referenceMonth) {
        List<ParsedRow> rows = parser.parse(pdf);
        SicrediSummaryParser.StatementSummary summary = summaryParser.parse(pdf);

        List<ParsedTransaction> transactions = rows.stream()
                .map(row -> toTransaction(row, referenceMonth))
                .toList();
        List<ParsedCharge> charges = summary.charges().stream()
                .map(c -> new ParsedCharge(c.type(), c.amount(), c.label()))
                .toList();

        // Sicredi não imprime o gabarito num formato que confiamos parsear —
        // officialFigures nulo mantém o gabarito digitado pelo usuário.
        return new ParsedStatement(transactions, summary.dueDate(), charges, null);
    }

    private ParsedTransaction toTransaction(ParsedRow row, LocalDate referenceMonth) {
        String description = SicrediDescription.resolve(row.raw(), row.merchant());
        Integer no = null;
        Integer total = null;
        Matcher m = INSTALLMENT.matcher(description);
        if (m.find()) {
            int candidateNo = Integer.parseInt(m.group(1));
            int candidateTotal = Integer.parseInt(m.group(2));
            if (candidateTotal >= 2 && candidateTotal <= 99
                    && candidateNo >= 1 && candidateNo <= candidateTotal) {
                no = candidateNo;
                total = candidateTotal;
            }
        }
        boolean international = row.raw().contains("US$") || row.raw().contains("BRL ");
        return new ParsedTransaction(row.raw(), description, blankToNull(row.merchant()),
                row.amount(), resolvePostedDate(row.raw(), referenceMonth), no, total,
                row.cardLast4(), international);
    }

    private String blankToNull(String value) {
        return value == null || value.isBlank() ? null : value;
    }

    /**
     * "DD/mmm" sem ano: usa o mês de referência como âncora; data muito depois
     * da fatura é do ano anterior (ex.: "20/dez" numa fatura de janeiro).
     */
    private LocalDate resolvePostedDate(String raw, LocalDate referenceMonth) {
        Matcher m = DATE_TOKEN.matcher(raw);
        if (!m.find()) {
            return referenceMonth;
        }
        int day = Integer.parseInt(m.group(1));
        Integer monthNo = MONTHS.get(m.group(2));
        if (monthNo == null) {
            return referenceMonth;
        }
        LocalDate candidate;
        try {
            candidate = LocalDate.of(referenceMonth.getYear(), monthNo, day);
        } catch (java.time.DateTimeException e) {
            return referenceMonth;
        }
        if (candidate.isAfter(referenceMonth.plusMonths(1))) {
            candidate = candidate.minusYears(1);
        }
        return candidate;
    }

    @SuppressWarnings("unused")
    private static BigDecimal unusedKeepImports() {
        return BigDecimal.ZERO;
    }
}

