import org.springframework.stereotype.Component;

/**
 * Adapter Mercado Pago (layout documentado em docs/mercado-pago-fatura-layout.md).
 *
 * <p>Diferenciais vs Sicredi: o "Resumo da fatura" da página 1 imprime o
 * gabarito completo (consumos, encargos, pagamentos, total) — o gate ao centavo
 * é AUTOMÁTICO, sem digitação. Transações vêm em seções por cartão
 * ("Cartão Visa [****NNNN]"), com parcela como "Parcela N de M" e datas "dd/MM".
 */
@Component
public class MercadoPagoStatementAdapter implements BankStatementAdapter {

    private static final DateTimeFormatter BR_DATE = DateTimeFormatter.ofPattern("dd/MM/yyyy");

    private static final Pattern DUE_DATE = Pattern.compile("Vence em\\s+(\\d{2}/\\d{2}/\\d{4})");
    private static final Pattern DUE_DATE_FOOTER = Pattern.compile("Vencimento:\\s*(\\d{2}/\\d{2}/\\d{4})");
    private static final Pattern CONSUMOS = Pattern.compile("Consumos de \\d{2}/\\d{2} a \\d{2}/\\d{2}\\s+R\\$\\s*([\\d.,]+)");
    private static final Pattern TARIFAS = Pattern.compile("Tarifas e encargos\\s+R\\$\\s*([\\d.,]+)");
    private static final Pattern MULTAS = Pattern.compile("Multas por atraso\\s+R\\$\\s*([\\d.,]+)");
    private static final Pattern JUROS_ANTERIOR = Pattern.compile("Juros do m[eê]s anterior\\s+R\\$\\s*([\\d.,]+)");
    private static final Pattern FATURA_ANTERIOR = Pattern.compile("Total da fatura de \\p{L}+\\s+R\\$\\s*([\\d.,]+)");
    private static final Pattern PAGAMENTOS = Pattern.compile("Pagamentos e cr[eé]ditos devolvidos\\s+R\\$\\s*([\\d.,]+)");
    private static final Pattern TOTAL = Pattern.compile("Total\\s+R\\$\\s*([\\d.,]+)");
    private static final Pattern CARD_HEADER = Pattern.compile("Cart[aã]o .*?\\[\\**(\\d{4})\\]");
    private static final Pattern TX_LINE = Pattern.compile(
            "^(\\d{2})/(\\d{2})\\s+(.+?)\\s+R\\$\\s*([\\d.,]+)\\s*$");
    private static final Pattern PARCELA = Pattern.compile("\\s*Parcela (\\d+) de (\\d+)\\s*");

    @Override
    public String provider() {
        return "MERCADO_PAGO";
    }

    @Override
    public boolean supports(String pdfText) {
        return pdfText.toLowerCase(Locale.ROOT).contains("mercado pago");
    }

    @Override
    public ParsedStatement parse(byte[] pdf, LocalDate referenceMonth) {
        String text = BankAdapterRegistry.extractText(pdf);

        LocalDate dueDate = findDate(text);
        Summary summary = parseSummary(text);
        List<ParsedTransaction> transactions = parseTransactions(text, referenceMonth);

        List<ParsedCharge> charges = new ArrayList<>();
        addChargeIfPositive(charges, ChargeType.ROTATIVO_JUROS, summary.jurosAnterior, "Juros do mês anterior");
        addChargeIfPositive(charges, ChargeType.MULTA, summary.multas, "Multas por atraso");
        addChargeIfPositive(charges, ChargeType.OUTROS, summary.tarifas, "Tarifas e encargos");

        OfficialStatementFigures official = summary.toOfficialFigures();

        return new ParsedStatement(transactions, dueDate, charges, official);
    }

    /* ----------------------------------------------------------- resumo */

    private record Summary(BigDecimal consumos, BigDecimal tarifas, BigDecimal multas,
                           BigDecimal jurosAnterior, BigDecimal faturaAnterior,
                           BigDecimal pagamentos, BigDecimal total) {

        OfficialStatementFigures toOfficialFigures() {
            if (consumos == null) {
                return null;
            }
            BigDecimal charges = nz(tarifas).add(nz(multas)).add(nz(jurosAnterior));
            // Convenção do gate: pagamentos/créditos entram NEGATIVOS na equação
            // previous + payments + expenses + charges = total.
            BigDecimal payments = pagamentos == null ? BigDecimal.ZERO : pagamentos.negate();
            return new OfficialStatementFigures(consumos, nz(faturaAnterior), payments, charges, total);
        }

        private static BigDecimal nz(BigDecimal v) {
            return v == null ? BigDecimal.ZERO : v;
        }
    }

    private Summary parseSummary(String text) {
        // Recorta do "Resumo da fatura" até "Detalhes de consumo" para o Total
        // não colidir com os totais das seções por cartão.
        int start = text.indexOf("Resumo da fatura");
        int end = text.indexOf("Detalhes de consumo");
        String block = start >= 0 && end > start ? text.substring(start, end) : text;

        return new Summary(
                money(block, CONSUMOS),
                money(block, TARIFAS),
                money(block, MULTAS),
                money(block, JUROS_ANTERIOR),
                money(block, FATURA_ANTERIOR),
                money(block, PAGAMENTOS),
                lastMoney(block, TOTAL));
    }

    /* ------------------------------------------------------- transações */

    private List<ParsedTransaction> parseTransactions(String text, LocalDate referenceMonth) {
        List<ParsedTransaction> result = new ArrayList<>();
        int detailsStart = text.indexOf("Detalhes de consumo");
        if (detailsStart < 0) {
            throw new PdfParseException("Fatura Mercado Pago sem seção 'Detalhes de consumo'.");
        }

        String currentCard = null;
        boolean beforeFirstCard = true;   // seção "Movimentações na fatura" = pagamentos/créditos

        for (String line : text.substring(detailsStart).split("\\R")) {
            String trimmed = line.strip();
            if (trimmed.isEmpty()) {
                continue;
            }
            Matcher card = CARD_HEADER.matcher(trimmed);
            if (card.find()) {
                currentCard = card.group(1);
                beforeFirstCard = false;
                continue;
            }
            // Fim da área de consumo: marketing de parcelamento encerra as seções.
            if (trimmed.startsWith("Parcele a fatura")) {
                break;
            }
            // Linha de conversão de compra internacional: valor certo já veio na principal.
            if (trimmed.startsWith("BRL ")) {
                continue;
            }
            Matcher tx = TX_LINE.matcher(trimmed);
            if (!tx.matches()) {
                continue;
            }

            int day = Integer.parseInt(tx.group(1));
            int month = Integer.parseInt(tx.group(2));
            String middle = tx.group(3).strip();
            BigDecimal amount = brMoney(tx.group(4));

            Integer no = null;
            Integer total = null;
            Matcher parcela = PARCELA.matcher(middle);
            if (parcela.find()) {
                no = Integer.parseInt(parcela.group(1));
                total = Integer.parseInt(parcela.group(2));
                middle = parcela.replaceFirst(" ").strip();
            }

            boolean credit = beforeFirstCard;
            boolean international = middle.toLowerCase(Locale.ROOT).contains("internacional");
            String description = international
                    ? middle.replaceFirst("(?i)^Compra internacional em\\s+", "").strip()
                    : middle;

            // raw SEM o marcador de parcela: MerchantText.key limpa data/valor
            // sozinho e a chave fica compatível com a do Sicredi (ex.: MP*VMSOLUTIONS
            // e "Mp Vmsolutions" agrupam juntos nas recorrências).
            String raw = String.format("%02d/%02d %s R$ %s", day, month, description, tx.group(4));

            result.add(new ParsedTransaction(
                    raw,
                    description,
                    description,
                    credit ? amount.negate() : amount,
                    resolvePostedDate(day, month, referenceMonth),
                    no, total,
                    currentCard,
                    international));
        }

        if (result.isEmpty()) {
            throw new PdfParseException("Nenhuma transação encontrada na fatura Mercado Pago.");
        }
        return result;
    }

    /** "dd/MM" sem ano: âncora no mês de referência; muito à frente = ano anterior. */
    private LocalDate resolvePostedDate(int day, int month, LocalDate referenceMonth) {
        LocalDate candidate;
        try {
            candidate = LocalDate.of(referenceMonth.getYear(), month, day);
        } catch (java.time.DateTimeException e) {
            return referenceMonth;
        }
        if (candidate.isAfter(referenceMonth.plusMonths(1))) {
            candidate = candidate.minusYears(1);
        }
        return candidate;
    }

    /* --------------------------------------------------------- helpers */

    private LocalDate findDate(String text) {
        Matcher m = DUE_DATE.matcher(text);
        if (m.find()) {
            return LocalDate.parse(m.group(1), BR_DATE);
        }
        m = DUE_DATE_FOOTER.matcher(text);
        return m.find() ? LocalDate.parse(m.group(1), BR_DATE) : null;
    }

    private void addChargeIfPositive(List<ParsedCharge> charges, ChargeType type,
                                     BigDecimal amount, String label) {
        if (amount != null && amount.signum() > 0) {
            charges.add(new ParsedCharge(type, amount, label));
        }
    }

    private BigDecimal money(String block, Pattern pattern) {
        Matcher m = pattern.matcher(block);
        return m.find() ? brMoney(m.group(1)) : null;
    }

    private BigDecimal lastMoney(String block, Pattern pattern) {
        Matcher m = pattern.matcher(block);
        BigDecimal last = null;
        while (m.find()) {
            last = brMoney(m.group(1));
        }
        return last;
    }

    private BigDecimal brMoney(String value) {
        return new BigDecimal(value.replace(".", "").replace(",", "."));
    }
}

package com.vini.financemonitor.ingestion.pdf;

import com.vini.financemonitor.account.Account;
import com.vini.financemonitor.account.AccountRepository;
import com.vini.financemonitor.category.Categorizer;
import com.vini.financemonitor.category.Category;
import com.vini.financemonitor.category.CategoryRepository;
import com.vini.financemonitor.common.DataSource;
import com.vini.financemonitor.ingestion.ImportRejectedException;
import com.vini.financemonitor.statement.Statement;
import com.vini.financemonitor.statement.StatementRepository;
import com.vini.financemonitor.transaction.InstallmentPlanService;
import com.vini.financemonitor.transaction.Transaction;
import com.vini.financemonitor.transaction.TransactionRepository;
import com.vini.financemonitor.web.dto.ImportSummary;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Pipeline de importação de fatura por PDF, AGNÓSTICO de banco:
 * detecta o adapter (sniff) → parse estruturado → reconcilia (gate ao centavo)
 * → categoriza → persiste. Tudo que é específico de layout mora nos adapters
 * ({@link SicrediStatementAdapter}, {@link MercadoPagoStatementAdapter}, ...).
 */
@Service
public class PdfImportService {

    private final BankAdapterRegistry adapterRegistry;
    private final ReconciliationService reconciliation;
    private final Categorizer categorizer;
    private final AccountRepository accounts;
    private final StatementRepository statements;
    private final TransactionRepository transactions;
    private final CategoryRepository categories;
    private final InstallmentPlanService installmentPlans;
    private final com.vini.financemonitor.member.HouseholdMemberRepository members;
    private final com.vini.financemonitor.ai.LlmStatementExtractor llmExtractor;
    private final com.vini.financemonitor.statement.StatementChargeRepository statementCharges;
    private final com.vini.financemonitor.statement.SettlementService settlement;

    public PdfImportService(BankAdapterRegistry adapterRegistry,
                            ReconciliationService reconciliation,
                            Categorizer categorizer,
                            AccountRepository accounts,
                            StatementRepository statements,
                            TransactionRepository transactions,
                            CategoryRepository categories,
                            InstallmentPlanService installmentPlans,
                            com.vini.financemonitor.member.HouseholdMemberRepository members,
                            com.vini.financemonitor.ai.LlmStatementExtractor llmExtractor,
                            com.vini.financemonitor.statement.StatementChargeRepository statementCharges,
                            com.vini.financemonitor.statement.SettlementService settlement) {
        this.adapterRegistry = adapterRegistry;
        this.reconciliation = reconciliation;
        this.categorizer = categorizer;
        this.accounts = accounts;
        this.statements = statements;
        this.transactions = transactions;
        this.categories = categories;
        this.installmentPlans = installmentPlans;
        this.members = members;
        this.llmExtractor = llmExtractor;
        this.statementCharges = statementCharges;
        this.settlement = settlement;
    }

    @Transactional
    public ImportSummary importStatement(byte[] pdf, Long accountId, LocalDate referenceMonth,
                                         OfficialStatementFigures typedFigures, BigDecimal paidAmount) {
        BankStatementAdapter adapter = adapterRegistry.detect(pdf);
        Account account = resolveAccount(accountId, adapter.provider());
        LocalDate month = referenceMonth.withDayOfMonth(1);

        if (statements.findByAccountIdAndReferenceMonth(account.getId(), month).isPresent()) {
            throw new IllegalStateException("Fatura já importada para " + month
                    + " na conta " + account.getName() + ".");
        }

        ParsedStatement parsed = adapter.parse(pdf, month);

        // Gabarito: o digitado pelo usuário vence; sem ele, usa o impresso na
        // fatura quando o banco fornece (Mercado Pago = gate automático).
        OfficialStatementFigures official = typedFigures != null && typedFigures.expensesTotal() != null
                ? typedFigures
                : parsed.officialFigures();
        if (official == null || official.expensesTotal() == null) {
            throw new IllegalArgumentException("Informe o subtotal de despesas (expensesTotal): "
                    + "a fatura " + adapter.provider() + " não traz gabarito parseável.");
        }

        List<ParsedTransaction> txs = parsed.transactions();
        ReconciliationResult result = reconciliation.reconcile(toRows(txs), official);
        DataSource source = DataSource.PDF_IMPORT;

        // Fallback de IA: layout que o adapter não reconheceu direito vai para o
        // LLM, e as linhas extraídas passam pelo MESMO gate ao centavo.
        if (!result.passesGate() && llmExtractor.enabled()) {
            List<ParsedRow> aiRows = llmExtractor.extract(pdf);
            ReconciliationResult aiResult = reconciliation.reconcile(aiRows, official);
            if (aiResult.passesGate()) {
                txs = aiRows.stream().map(r -> genericTransaction(r, month)).toList();
                result = aiResult;
                source = DataSource.LLM_IMPORT;
            }
        }

        if (!result.passesGate()) {
            throw new ImportRejectedException(
                    "Reconciliação falhou: soma das despesas R$ " + result.expensesSum()
                            + " difere do subtotal oficial em R$ " + result.expensesDiff()
                            + ". Importação rejeitada."
                            + (llmExtractor.enabled() ? " (fallback de IA também não reconciliou)" : ""),
                    result);
        }

        Statement statement = persistStatement(account.getId(), month, official, result, paidAmount);
        applyParsedSummary(statement, parsed);
        Map<String, Long> categoryIds = loadCategoryIds();
        Map<String, Long> memberByCard = loadMemberByCard();

        int expensesCount = 0;
        int creditsCount = 0;
        for (ParsedTransaction tx : txs) {
            transactions.save(toTransaction(tx, account.getId(), statement.getId(), categoryIds,
                    memberByCard, source));
            if (tx.amount().signum() > 0) {
                expensesCount++;
            } else if (tx.amount().signum() < 0) {
                creditsCount++;
            }
        }

        // Mantém os planos de parcelamento em dia e propaga a atribuição a terceiros
        // para as novas parcelas importadas (ex.: parcela do sogro do mês seguinte).
        installmentPlans.rebuild();

        // Máquina de estados: recalcula esta fatura e retro-confirma a anterior —
        // os encargos desta fatura são o veredito do banco sobre o mês passado.
        settlement.recompute(statement);
        statements.findByAccountIdAndReferenceMonth(account.getId(), month.minusMonths(1))
                .ifPresent(settlement::recompute);

        return new ImportSummary(
                statement.getId(), month, txs.size(), expensesCount, creditsCount,
                result.expensesSum(), result.expensesDiff(), result.passesGate(),
                result.sumMatches(), result.accountingMatches(), result.structuralOk(),
                result.coincidences().size(),
                source == DataSource.LLM_IMPORT ? "AI_FALLBACK" : "PARSER");
    }

    /** O gate/reconciliação trabalha com a visão de linha bruta. */
    private List<ParsedRow> toRows(List<ParsedTransaction> txs) {
        return txs.stream()
                .map(t -> new ParsedRow(0, t.raw(), t.amount(), t.merchant(), t.cardLast4()))
                .toList();
    }

    /** Linhas do fallback de IA viram transações com resolução genérica. */
    private ParsedTransaction genericTransaction(ParsedRow row, LocalDate referenceMonth) {
        return new ParsedTransaction(row.raw(), row.raw(), row.merchant(), row.amount(),
                referenceMonth, null, null, row.cardLast4(),
                row.raw().contains("US$") || row.raw().contains("BRL "));
    }

    /** Vencimento + encargos tipados vindos do adapter (veredito de rotativo). */
    private void applyParsedSummary(Statement statement, ParsedStatement parsed) {
        if (parsed.dueDate() != null) {
            statement.setDueDate(parsed.dueDate());
            statements.save(statement);
        }
        for (ParsedCharge line : parsed.charges()) {
            com.vini.financemonitor.statement.StatementCharge charge =
                    new com.vini.financemonitor.statement.StatementCharge();
            charge.setStatementId(statement.getId());
            charge.setType(line.type());
            charge.setAmount(line.amount());
            charge.setLabel(line.label());
            statementCharges.save(charge);
        }
    }

    /**
     * Conta: id explícito vence; sem id, resolve pela conta do PROVIDER que o
     * adapter detectou (é isso que torna o import multi-banco sem formulário).
     */
    private Account resolveAccount(Long accountId, String provider) {
        if (accountId != null) {
            return accounts.findById(accountId)
                    .orElseThrow(() -> new IllegalArgumentException("Conta " + accountId + " não encontrada."));
        }
        List<Account> byProvider = accounts.findAll().stream()
                .filter(a -> provider.equals(a.getProvider()))
                .toList();
        if (byProvider.size() == 1) {
            return byProvider.get(0);
        }
        if (byProvider.isEmpty()) {
            throw new IllegalArgumentException("Nenhuma conta cadastrada para o banco "
                    + provider + " — crie a conta antes de importar.");
        }
        throw new IllegalArgumentException("Informe accountId: há " + byProvider.size()
                + " contas do banco " + provider + ".");
    }

    private Statement persistStatement(Long accountId, LocalDate month, OfficialStatementFigures official,
                                       ReconciliationResult result, BigDecimal paidAmount) {
        Statement statement = new Statement();
        statement.setAccountId(accountId);
        statement.setReferenceMonth(month);
        statement.setExpensesTotal(result.expensesSum());
        statement.setSource(DataSource.PDF_IMPORT);
        if (official.hasAccountingFigures()) {
            statement.setPreviousTotal(official.previousTotal());
            statement.setPaymentsCredits(official.paymentsCredits());
            statement.setChargesTotal(official.charges());
            statement.setTotalAmount(official.total());
        }
        if (paidAmount != null) {
            statement.setPaidAmount(paidAmount);
            // Pagou menos que o total da fatura -> entrou no rotativo.
            if (statement.getTotalAmount() != null) {
                statement.setEnteredRevolving(paidAmount.compareTo(statement.getTotalAmount()) < 0);
            }
        }
        return statements.save(statement);
    }

    private Transaction toTransaction(ParsedTransaction parsed, Long accountId, Long statementId,
                                      Map<String, Long> categoryIds, Map<String, Long> memberByCard,
                                      DataSource source) {
        String categoryName = categorizer.categorize(parsed.description());

        Transaction tx = new Transaction();
        tx.setAccountId(accountId);
        tx.setStatementId(statementId);
        tx.setCategoryId(categoryIds.get(categoryName));
        tx.setPostedAt(parsed.postedAt());
        tx.setDescriptionRaw(parsed.raw());
        tx.setMerchant(parsed.merchant());
        tx.setAmount(parsed.amount());
        tx.setInternational(parsed.international());
        tx.setSource(source);
        // Modo casal: a seção de cartão da fatura identifica o dono (cartão
        // cadastrado em household_member.card_last4 => atribuição automática).
        tx.setCardLast4(parsed.cardLast4());
        if (parsed.cardLast4() != null) {
            tx.setMemberId(memberByCard.get(parsed.cardLast4()));
        }
        if (parsed.installmentNo() != null && parsed.installmentTotal() != null) {
            tx.setInstallmentNo(parsed.installmentNo());
            tx.setInstallmentTotal(parsed.installmentTotal());
        }
        return tx;
    }

    private Map<String, Long> loadMemberByCard() {
        Map<String, Long> byCard = new HashMap<>();
        for (com.vini.financemonitor.member.HouseholdMember member : members.findAll()) {
            if (member.getCardLast4() != null) {
                byCard.put(member.getCardLast4(), member.getId());
            }
        }
        return byCard;
    }

    private Map<String, Long> loadCategoryIds() {
        Map<String, Long> map = new HashMap<>();
        for (Category category : categories.findAll()) {
            map.put(category.getName(), category.getId());
        }
        return map;
    }
}

