    /** Juros compostos do saldo à taxa da conta por n meses: saldo * ((1+r)^n - 1). */
    private BigDecimal compoundInterest(BigDecimal balance, int months, BigDecimal monthlyRate) {
        BigDecimal factor = BigDecimal.ONE.add(monthlyRate).pow(months)
                .subtract(BigDecimal.ONE);
        return balance.multiply(factor).setScale(2, RoundingMode.HALF_UP);
    }
