package com.vini.financemonitor.ingestion.pdf;

import static org.assertj.core.api.Assertions.assertThat;

import java.math.BigDecimal;
import java.nio.file.Files;
import java.nio.file.Path;
import java.time.LocalDate;
import java.util.List;
import org.junit.jupiter.api.Assumptions;
import org.junit.jupiter.api.Test;

/**
 * Valida o adapter Mercado Pago contra a fatura real de julho/2026 em faturas/.
 * O gate é a prova: consumos impressos na página 1 (R$ 2.499,83) têm que bater
 * ao centavo com a soma das transações extraídas por seção de cartão.
 * Pulado se o PDF não existir. Execução: {@code mvn test -Dtest=MercadoPagoAdapterIT}.
 */
class MercadoPagoAdapterIT {

    private final MercadoPagoStatementAdapter adapter = new MercadoPagoStatementAdapter();

    @Test
    void faturaJulhoReconciliaAoCentavo() throws Exception {
        Path pdf = Path.of("faturas", "fatura_mp_julho.pdf");
        Assumptions.assumeTrue(Files.isReadable(pdf));
        byte[] bytes = Files.readAllBytes(pdf);

        assertThat(adapter.supports(BankAdapterRegistry.extractText(bytes))).isTrue();

        ParsedStatement parsed = adapter.parse(bytes, LocalDate.of(2026, 7, 1));

        // Gabarito automático da página 1.
        OfficialStatementFigures official = parsed.officialFigures();
        assertThat(official).isNotNull();
        assertThat(official.expensesTotal()).isEqualByComparingTo("2499.83");
        assertThat(official.paymentsCredits()).isEqualByComparingTo("-150.00");
        assertThat(official.total()).isEqualByComparingTo("2349.83");
        assertThat(official.hasAccountingFigures()).isTrue();

        // Vencimento da página 1.
        assertThat(parsed.dueDate()).isEqualTo(LocalDate.of(2026, 7, 16));

        // Gate ao centavo: soma das despesas extraídas == consumos oficiais.
        List<ParsedTransaction> txs = parsed.transactions();
        BigDecimal expenses = txs.stream()
                .map(ParsedTransaction::amount)
                .filter(a -> a.signum() > 0)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
        assertThat(expenses).isEqualByComparingTo("2499.83");

        // Crédito do pagamento parcial.
        BigDecimal credits = txs.stream()
                .map(ParsedTransaction::amount)
                .filter(a -> a.signum() < 0)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
        assertThat(credits).isEqualByComparingTo("-150.00");

        // Seções por cartão (modo casal): 4326 e 5888, com os totais da fatura.
        BigDecimal card4326 = sumByCard(txs, "4326");
        BigDecimal card5888 = sumByCard(txs, "5888");
        assertThat(card4326).isEqualByComparingTo("2037.17");
        assertThat(card5888).isEqualByComparingTo("462.66");

        // Parcelamentos com marcador "Parcela N de M".
        assertThat(txs.stream()
                .filter(t -> t.installmentTotal() != null)
                .count()).isEqualTo(2);

        // Internacional: valor principal em R$, linha de conversão descartada.
        ParsedTransaction paypal = txs.stream()
                .filter(ParsedTransaction::international)
                .findFirst().orElseThrow();
        assertThat(paypal.amount()).isEqualByComparingTo("44.77");

        // Datas ancoradas: compra de 24/06 na fatura de julho fica em 2026.
        assertThat(txs.stream()
                .filter(t -> t.postedAt().equals(LocalDate.of(2026, 6, 24)))
                .count()).isGreaterThanOrEqualTo(1);
    }

    private BigDecimal sumByCard(List<ParsedTransaction> txs, String card) {
        return txs.stream()
                .filter(t -> card.equals(t.cardLast4()))
                .map(ParsedTransaction::amount)
                .reduce(BigDecimal.ZERO, BigDecimal::add);
    }
}

