    @Transactional
    public MemberView update(Long id, String name, String cardLast4) {
        HouseholdMember member = members.findById(id)
                .orElseThrow(() -> new IllegalArgumentException("Membro " + id + " não encontrado."));
        if (name != null && !name.isBlank()) {
            member.setName(name.strip());
        }
        members.save(member);
        String normalized = normalizeCard(cardLast4);
        if (normalized != null) {
            addCard(id, normalized);
        }
        return toView(member);
    }

    /**
     * Vincula um cartão ao membro e RETRO-ATRIBUI: transações já importadas
     * daquele cartão que ainda estavam na "Casa" (member_id nulo) viram do
     * membro. Atribuições manuais existentes não são tocadas.
     */
    @Transactional
    public MemberView addCard(Long memberId, String cardLast4) {
        HouseholdMember member = members.findById(memberId)
                .orElseThrow(() -> new IllegalArgumentException("Membro " + memberId + " não encontrado."));
        String normalized = normalizeCard(cardLast4);
        if (normalized == null) {
            throw new IllegalArgumentException("cardLast4 deve ter 4 dígitos.");
        }
        MemberCard existing = cards.findByCardLast4(normalized).orElse(null);
        if (existing != null) {
            if (!existing.getMemberId().equals(memberId)) {
                throw new IllegalStateException("Cartão " + normalized + " já pertence a outro membro.");
            }
        } else {
            MemberCard card = new MemberCard();
            card.setMemberId(memberId);
            card.setCardLast4(normalized);
            cards.save(card);
        }
        List<Transaction> orphans = transactions.findByCardLast4AndMemberIdIsNull(normalized);
        for (Transaction tx : orphans) {
            tx.setMemberId(memberId);
        }
        transactions.saveAll(orphans);
        return toView(member);
    }

    /** Desvincula o cartão (atribuições já feitas permanecem). */
    @Transactional
    public MemberView removeCard(Long memberId, String cardLast4) {
        HouseholdMember member = members.findById(memberId)
                .orElseThrow(() -> new IllegalArgumentException("Membro " + memberId + " não encontrado."));
        cards.findByCardLast4(normalizeCard(cardLast4))
                .filter(c -> c.getMemberId().equals(memberId))
                .ifPresent(cards::delete);
        return toView(member);
    }''')

