'''    /** Linhas da extração por IA viram transações com resolução genérica. */
    private ParsedTransaction genericTransaction(ParsedRow row, LocalDate referenceMonth) {
        Integer no = null;
        Integer total = null;
        Matcher inst = GENERIC_INSTALLMENT.matcher(row.raw());
        while (inst.find()) {
            int candidateNo = Integer.parseInt(inst.group(1));
            int candidateTotal = Integer.parseInt(inst.group(2));
            if (candidateTotal >= 2 && candidateTotal <= 99
                    && candidateNo >= 1 && candidateNo <= candidateTotal) {
                no = candidateNo;
                total = candidateTotal;
            }
        }
        return new ParsedTransaction(row.raw(), row.raw(), row.merchant(), row.amount(),
                genericPostedDate(row.raw(), referenceMonth), no, total, row.cardLast4(),
                row.raw().contains("US$") || row.raw().contains("BRL "));
    }

    /** "DD/mmm" da extração por IA, ancorado no mês de referência (sem ano). */
    private LocalDate genericPostedDate(String raw, LocalDate referenceMonth) {
        Matcher m = GENERIC_DATE.matcher(raw);
        if (!m.find()) {
            return referenceMonth;
        }
        Integer monthNo = MONTHS.get(m.group(2));
        if (monthNo == null) {
            return referenceMonth;
        }
        LocalDate candidate;
        try {
            candidate = LocalDate.of(referenceMonth.getYear(), monthNo, Integer.parseInt(m.group(1)));
        } catch (java.time.DateTimeException e) {
            return referenceMonth;
        }
        if (candidate.isAfter(referenceMonth.plusMonths(1))) {
            candidate = candidate.minusYears(1);
        }
        return candidate;
    }

    private boolean isImage(byte[] file, String contentType) {
        if (contentType != null && contentType.startsWith("image/")) {
            return true;
        }
        // Magic bytes: PNG e JPEG (PDF começa com %PDF).
        return file.length > 3
                && ((file[0] & 0xFF) == 0x89 && file[1] == 0x50
                    || (file[0] & 0xFF) == 0xFF && (file[1] & 0xFF) == 0xD8);
    }

