     * A extração é 100% IA, mas o invariante é o mesmo: o usuário digita o
     * total de despesas visível na tela e a soma extraída tem que bater ao
     * centavo — alucinação não sobrevive ao gate.
     */
    private ImportSummary importFromImage(byte[] image, String contentType, Long accountId,
                                          LocalDate referenceMonth, LocalDate dueDate,
                                          OfficialStatementFigures typedFigures, BigDecimal paidAmount) {
        if (accountId == null) {
            throw new IllegalArgumentException("Import por imagem exige accountId (não há como detectar o banco).");
        }
        if (typedFigures == null || typedFigures.expensesTotal() == null) {
            throw new IllegalArgumentException("Import por imagem exige o total de despesas (gate ao centavo).");
        }
        if (!llmExtractor.enabled()) {
            throw new IllegalStateException("Import por imagem precisa da IA configurada (GEMINI_API_KEY).");
        }
        Account account = accounts.findById(accountId)
                .orElseThrow(() -> new IllegalArgumentException("Conta " + accountId + " não encontrada."));
        LocalDate month = referenceMonth.withDayOfMonth(1);
        if (statements.findByAccountIdAndReferenceMonth(account.getId(), month).isPresent()) {
            throw new IllegalStateException("Fatura já importada para " + month
                    + " na conta " + account.getName() + ".");
        }

        List<ParsedRow> rows = llmExtractor.extract(image,
                contentType != null && contentType.startsWith("image/") ? contentType : "image/png");
        ReconciliationResult result = reconciliation.reconcile(rows, typedFigures);
        if (!result.passesGate()) {
            throw new ImportRejectedException(
